#[derive(Clone, Copy, Debug, PartialEq)]
enum Key {
    Up,
    Down,
    Tab,
    /// Shift+Tab (`ESC [ Z`): the previous tab (v7.7 ticket 150).
    BackTab,
    /// A left click at (column, row), both from 1 (v7.7 ticket 159, SGR mouse reporting).
    /// A click is a key, never a mapped control.
    Click(u16, u16),
    Left,
    Right,
    Enter,
    Space,
    Escape,
    Other,
    Character(u8),
    Backspace,
    InvalidInput,
}

fn csi_key(sequence: &[u8]) -> Key {
    let (code, modifier) = match sequence {
        [b'Z'] => return Key::BackTab,
        // v7.7 ticket 159: `ESC [ < button ; column ; row M` (press) or `m` (release).
        [b'<', rest @ ..] => {
            let Some((&end, params)) = rest.split_last() else {
                return Key::Other;
            };
            let fields = std::str::from_utf8(params)
                .unwrap_or_default()
                .split(';')
                .map(|f| f.parse::<u16>().ok())
                .collect::<Vec<_>>();
            return match (end, fields.as_slice()) {
                (b'M', [Some(0), Some(x), Some(y)]) => Key::Click(*x, *y),
                (b'M', [Some(64), _, _]) => Key::Up, // wheel up
                (b'M', [Some(65), _, _]) => Key::Down,
                _ => Key::Other,
            };
        }
        [code @ (b'A' | b'B' | b'C' | b'D')] => (*code, 1),
        [
            b'1',
            b';',
            modifier @ b'2'..=b'8',
            code @ (b'A' | b'B' | b'C' | b'D'),
        ] => (*code, *modifier - b'0'),
        _ => {
            let Some((&final_byte, params)) = sequence.split_last() else {
                return Key::Other;
            };
            let Ok(params) = std::str::from_utf8(params) else {
                return Key::Other;
            };
            let mut fields = params.split(';');
            let (Some(code), Some(modifier)) = (fields.next(), fields.next()) else {
                return Key::Other;
            };
            let Ok(code) = code.parse::<u8>() else {
                return Key::Other;
            };
            let Ok(modifier) = modifier.parse::<u8>() else {
                return Key::Other;
            };
            if !(2..=8).contains(&modifier) {
                return Key::Other;
            }
            let code = match final_byte {
                b'u' if fields.next().is_none() => code,
                b'~' if code == 27 => match fields.next().and_then(|s| s.parse::<u8>().ok()) {
                    Some(code) if fields.next().is_none() => code,
                    _ => return Key::Other,
                },
                _ => return Key::Other,
            };
            return match code {
                13 => Key::Enter,
                27 => Key::Escape,
                32 => Key::Space,
                _ => Key::Other,
            };
        }
    };
    if !(1..=8).contains(&modifier) {
        return Key::Other;
    }
    match code {
        b'A' => Key::Up,
        b'B' => Key::Down,
        b'C' => Key::Right,
        b'D' => Key::Left,
        _ => Key::Other,
    }
}

/// What a Learn page saw (v7 ticket 45): a press (a pad, a piano key, an Xbox button, or a
/// first movement of a knob or the joystick), or a calibrated knob or joystick.
#[derive(Clone, Debug, PartialEq)]
enum Learned {
    Press(Control),
    Motion(Control, mappings::Input, String),
}

/// v7.8 ticket 19: an Xbox control's name in the hints: Ⓐ Ⓑ Ⓧ Ⓨ, LB, RB, LT, RT, View,
/// Menu, D-pad (any direction), LS and RS; others (stick directions) by their label.
fn xbox_hint_name(control: Control) -> String {
    let name = (control.message == crate::Message::Button)
        .then(|| crate::gamepad::BUTTONS.get(usize::from(control.id)))
        .flatten()
        .map(|(_, name)| *name);
    match name {
        Some("A") => "Ⓐ".into(),
        Some("B") => "Ⓑ".into(),
        Some("X") => "Ⓧ".into(),
        Some("Y") => "Ⓨ".into(),
        Some("Left stick press") => "LS".into(),
        Some("Right stick press") => "RS".into(),
        Some(name) if name.starts_with("D-pad") => "D-pad".into(),
        Some(name) => name.into(),
        None => control.label(),
    }
}

/// v7.8 ticket 26: one device on Detect's speed rows.
#[derive(Default)]
struct SpeedDevice {
    /// Its name (kept results are filed under it) and its header line (name and details).
    name: String,
    header: String,
    connection: String,
    link: String,
    /// The last press: its name and how long after the computer got it VibeConsole handled
    /// it (None: a clock changed in between).
    press: Option<(String, Option<f64>)>,
    /// The speed test's line while it runs and after.
    test: String,
}
/// v7.8 ticket 26: Detect's link and speed test (only while Detect is open, never while Run
/// sends keys).
#[derive(Default)]
struct Speed {
    xbox: Option<SpeedDevice>,
    akai: Option<SpeedDevice>,
    /// The Xbox test's start; the pad collects right-stick stamps until it ends.
    xbox_since: Option<Instant>,
    /// The Akai test's press delays.
    akai_delays: Option<Vec<f64>>,
    kept: Vec<crate::speed::Kept>,
}
const XBOX_TEST: Duration = Duration::from_secs(3);
const AKAI_PRESSES: usize = 10;

trait Ui {
    fn draw(&mut self, text: &str) -> Result<()>;
    fn key(&mut self) -> Result<Option<Key>>;
    /// v7.7 ticket 211: time since the program started; tests pass a clock.
    fn clock(&mut self) -> Duration {
        static START: std::sync::OnceLock<Instant> = std::sync::OnceLock::new();
        START.get_or_init(Instant::now).elapsed()
    }
    /// v7.7 ticket 211: every light shows `state` as an agent in it would (None: the agents'
    /// own states again). Returns what can't show it, or None once a transition stopped it.
    fn light_test(&mut self, _state: Option<&'static str>) -> Result<Option<Vec<String>>> {
        Ok(Some(vec!["No lights are driven from this screen.".into()]))
    }
    /// v7.7 ticket 236: output is paused (Run would start it).
    fn paused(&self) -> bool {
        false
    }
    /// Run, exactly as the Run command does (its gates and confirmations).
    fn run_now(&mut self) -> Result<()> {
        Ok(())
    }
    /// v7.7 ticket 206: the row last opened in each list, by the list's name, in memory only.
    fn rows_left(&mut self) -> Option<&mut BTreeMap<String, (usize, String)>> {
        None
    }
    fn edit_file(&mut self, _path: &Path) -> Result<()> {
        Err("editor unavailable".into())
    }
    fn height(&self) -> usize {
        24
    }
    fn width(&self) -> usize {
        80
    }
    fn context(&self) -> u8 {
        0
    }
    fn program(&self) -> Option<(u8, crate::feedback::Payload)> {
        None
    }
    fn label(&mut self, control: Control, _current: &[Mapping]) -> Result<Option<String>> {
        Ok(Some(control.label()))
    }
    fn applications(&self) -> Result<Vec<(String, String)>> {
        crate::actions::catalog()
    }
    /// An assignment was saved or removed inside `/configure` (v7 ticket 112): the session
    /// uses it from the next press.
    fn applied(&mut self) -> Result<()> {
        Ok(())
    }
    /// The first control pressed (a note or an Xbox button) or moved (a CC or pitch bend).
    fn learn(&mut self) -> Result<Option<Control>>;
    /// "Learn an Xbox button" (v7 ticket 45): like `learn`, under its own title.
    fn learn_button(&mut self) -> Result<Option<Control>> {
        self.learn()
    }
    /// Whether an Xbox controller is connected now (v7 ticket 111: its built-in defaults are
    /// listed for editing only then).
    fn xbox_connected(&self) -> bool {
        false
    }
    /// The Xbox program in use (v7 ticket 115): Learn saves an Xbox button there.
    fn xbox_program(&self) -> u8 {
        1
    }
    /// v7.7 ticket 267: the Akai's program names as read from it (else "Program N").
    fn program_names(&self) -> Vec<String> {
        (1..=8).map(|n| format!("Program {n}")).collect()
    }
    /// v7 ticket 129: the driver holding the Xbox controller now, and ALSA's card list.
    fn xbox_audio(&self) -> (Option<&'static str>, String) {
        (None, String::new())
    }
    /// v7 ticket 129: runs a program with fixed arguments (pkexec, speaker-test, arecord,
    /// aplay); unavailable unless the real terminal provides it.
    fn run(&mut self, _args: &[&str]) -> Result<String> {
        Err("unavailable here".into())
    }
    /// v7 ticket 130: whether VibeConsole's Xbox light rule is installed.
    fn light_rule(&self) -> bool {
        false
    }
    fn learn_knob(&mut self) -> Result<Option<Learned>> {
        Err("knob learning unavailable".into())
    }
    fn learn_joystick(&mut self) -> Result<Option<Learned>> {
        Err("joystick learning unavailable".into())
    }
    fn learn_piano(&mut self) -> Result<Option<Control>> {
        Err("piano learning unavailable".into())
    }
    fn record(&mut self) -> Result<Vec<String>> {
        Err("recording unavailable; use Select keys".into())
    }
    /// Settings -> Login service; the session overrides this with systemctl (ticket 21).
    fn login(&mut self, _request: crate::runtime::Login) -> Result<bool> {
        Err("login service unavailable".into())
    }
    /// v7.8 ticket 13: the paired Bluetooth devices (address, name); read only. The session
    /// asks bluetoothctl; tests answer from their script.
    fn paired_bluetooth(&mut self) -> Result<Vec<(String, String)>> {
        Err("Bluetooth devices unavailable".into())
    }
    /// v7.7 ticket 255: what Quit did about the login service, and why: to the journal now,
    /// and on the terminal once its screen is restored.
    fn quit_note(&mut self, _line: &str) {}
    /// v7 ticket 26: the user's own `claude -p` (their login, no key stored), 3 minutes at
    /// most. Tests answer with a fake reply.
    /// v7.7 ticket 146: where the usage log lives (None: nothing counted).
    fn usage_dir(&self) -> Option<PathBuf> {
        None
    }
    /// v7.7 ticket 168: where Set up agents looks: `PATH` and the home folder (read; nothing
    /// found there is run). v7.7 ticket 169: and the working folder (its `.claude/skills`).
    fn lookup_env(&self) -> (String, Option<PathBuf>, Option<PathBuf>) {
        (
            std::env::var("PATH").unwrap_or_default(),
            std::env::var_os("HOME").map(PathBuf::from),
            std::env::current_dir().ok(),
        )
    }
    /// v7.7 ticket 170: run a program (each argument one argument, no shell) in tmux window
    /// `window` in `dir`, shown in a terminal. Tests never start it.
    fn show_in_terminal(&mut self, window: &str, dir: &str, argv: &[&str]) -> Result<String> {
        #[cfg(test)]
        {
            let _ = (window, dir);
            Err(format!("{}: not started in tests", argv[0]).into())
        }
        #[cfg(not(test))]
        crate::actions::show_program(window, dir, argv)
    }
    /// v7.7 ticket 175: the default agent's one-shot command (`mappings::one_shot`: its
    /// binary, fixed arguments, then the request as one argument), 3 minutes at most, through
    /// the injected runner: no shell. Tests answer with a fake reply.
    fn ask_agent(&mut self, argv: &[String]) -> Result<String> {
        let mut args = vec!["timeout", "180"];
        args.extend(argv.iter().map(String::as_str));
        self.run(&args)
            .map_err(|e| format!("{} (the default agent): {e}", argv[0]).into())
    }
    /// The free-key helper's write (v7 ticket 19): backup first, then an atomic write.
    fn write_t3_key_file(&mut self, text: &str) -> Result<String> {
        crate::actions::write_t3_key_file(text).map(|backup| backup.display().to_string())
    }
    /// herdr's agent names (v7 ticket 18).
    fn herdr_agents(&mut self) -> Result<Vec<String>> {
        let output = vibeconsole_core::program("herdr")
            .args(["agent", "list"])
            .output()
            .map_err(|e| format!("herdr isn't available: {e}"))?;
        Ok(
            crate::status::herdr_agents(&String::from_utf8_lossy(&output.stdout))
                .into_iter()
                .map(|(name, _, _)| name)
                .collect(),
        )
    }
    /// T3 Code's key file (v7 ticket 17).
    fn t3_key_file(&mut self) -> Result<String> {
        let path = crate::actions::t3_key_file()?;
        std::fs::read_to_string(&path)
            .map_err(|e| format!("T3 key file {}: {e}", path.display()).into())
    }
    /// Orca's agent terminals as (agent, folder) (v7 ticket 15).
    fn orca_agents(&mut self) -> Result<Vec<(String, String)>> {
        // v7 ticket 102: Orca IDE's CLI, never the screen reader.
        let output = vibeconsole_core::program(crate::actions::orca_program()?)
            .args(["terminal", "list", "--json"])
            .output()
            .map_err(|e| format!("Orca CLI unavailable: {e}"))?;
        let mut agents = crate::actions::orca_terminals(&String::from_utf8_lossy(&output.stdout))?
            .into_iter()
            .map(|(agent, folder, _)| (agent, folder))
            .collect::<Vec<_>>();
        agents.sort();
        agents.dedup();
        Ok(agents)
    }
    /// Settings -> MIDI device: connected other MIDI devices (v7 ticket 06).
    fn midi_devices(&mut self) -> Result<Vec<String>> {
        crate::midi::other_devices()
    }
}

