    /// v7.8 ticket 07: program select lists both devices' programs by name (each row saying
    /// which device only when both are there), opens on the one in use, and says what was picked.
    #[test]
    fn program_select_lists_both_devices_by_name() {
        use Key::*;
        let akai = strings(&["Program 1 — TradingView", "Program 2"]);
        let xbox = strings(&["Apps", "Program 2"]);
        let mut ui = Script {
            keys: [Down, Down, Enter].into(),
            ..Default::default()
        };
        let picked = program_select(&mut ui, &akai, &xbox, Picked::Akai(0)).unwrap();
        let screen = ui.screens.last().unwrap();
        for row in [
            "TradingView · Akai",
            "Program 2 · Akai",
            "Apps · Xbox",
            "Program 2 · Xbox",
        ] {
            assert!(screen.contains(row), "{screen}");
        }
        assert_eq!(picked, Some(Picked::Xbox(1)));
        // Only the Xbox connected: its programs alone, no device names; opens on the one in use.
        let mut ui = Script {
            keys: [Enter].into(),
            ..Default::default()
        };
        let picked = program_select(&mut ui, &[], &xbox, Picked::Xbox(2)).unwrap();
        let screen = ui.screens.last().unwrap();
        assert!(
            screen.contains("Apps") && !screen.contains("· Xbox") && !screen.contains("· Akai")
        );
        assert_eq!(picked, Some(Picked::Xbox(2)));
        // Only the Akai: its programs alone.
        let mut ui = Script {
            keys: [Down, Enter].into(),
            ..Default::default()
        };
        let picked = program_select(&mut ui, &akai, &[], Picked::Akai(0)).unwrap();
        assert!(!ui.screens.last().unwrap().contains("Apps"));
        assert_eq!(picked, Some(Picked::Akai(1)));
    }

    /// v7.8 ticket 06: the header names the program (Program N only when unnamed), then the
    /// link and driver as sysfs gives them (gamepad::link_and_driver_come_from_sysfs).
    #[test]
    fn xbox_header_names_program_link_and_driver() {
        let link = |c: &str, d: &str| link_text(&[c.into(), d.into()]);
        assert_eq!(
            xbox_header("Apps", 1, &link("USB", "xone")),
            "Xbox · Apps · USB · xone"
        );
        assert_eq!(
            xbox_header("Apps", 1, &link("USB dongle", "xone")),
            "Xbox · Apps · USB dongle · xone"
        );
        assert_eq!(
            xbox_header("Browser", 2, &link("Bluetooth", "xpadneo")),
            "Xbox · Browser · Bluetooth · xpadneo"
        );
        assert_eq!(xbox_header("", 3, &link_text(&[])), "Xbox · Program 3");
        assert_eq!(
            xbox_header("Program 4", 4, &link_text(&["Bluetooth".into()])),
            "Xbox · Program 4 · Bluetooth"
        );
        // v7.8 ticket 09: the battery (charging) and xpadneo's profile follow, when reported.
        let with = |power, profile| {
            let mut parts = vec!["Bluetooth".to_string(), "xpadneo".into()];
            parts.extend(crate::gamepad::power_parts(power, profile));
            xbox_header("Apps", 1, &link_text(&parts))
        };
        use crate::gamepad::PowerInfo::*;
        assert_eq!(
            with(Discharging(62), None),
            "Xbox · Apps · Bluetooth · xpadneo · battery 62%"
        );
        assert_eq!(
            with(Charging(40), Some(2)),
            "Xbox · Apps · Bluetooth · xpadneo · battery 40% charging · profile 2"
        );
        assert_eq!(
            with(Charged, Some(0)),
            "Xbox · Apps · Bluetooth · xpadneo · battery full · profile 0"
        );
        assert_eq!(with(Unknown, None), "Xbox · Apps · Bluetooth · xpadneo");
        assert_eq!(with(Wired, None), "Xbox · Apps · Bluetooth · xpadneo");
    }

