    /// v7.7 ticket 169: Ask for a prompt makes two calls: the questions, answered in text
    /// entries, then the prompt; Name it saves it through $EDITOR. Esc at a question or Cancel
    /// saves nothing.
    #[test]
    fn ask_for_a_prompt_asks_its_questions_then_writes_it() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-ai-prompt-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let prompts = crate::actions::prompts_dir_for(&path).unwrap();
        let run = |keys: Vec<Key>| {
            let mut ui = Script {
                keys: keys.into(),
                replies: [
                    "Sure.\nQ: Which language?\nQ: Tests too?\n".to_string(),
                    "```\nReview the Rust diff and its tests.\n```".to_string(),
                ]
                .into(),
                ..Default::default()
            };
            let result = ask_for(&mut ui, &path, AskKind::Prompt);
            assert!(ui.keys.is_empty());
            (result, ui.screens, ui.asked)
        };
        let mut keys = typed("review my diff");
        keys.push(Enter);
        // Esc at the first question: one call, nothing saved.
        let mut esc = keys.clone();
        esc.push(Escape);
        let (result, _, asked) = run(esc);
        result.unwrap();
        assert_eq!(asked.len(), 1);
        assert!(asked[0].contains("The user wants: review my diff") && asked[0].contains("`Q:`"));
        assert!(prompt_files(&prompts).unwrap().is_empty());
        keys.extend(typed("rust"));
        keys.extend([Enter, Enter]); // answers
        // Cancel at the review: two calls, nothing saved.
        let mut cancel = keys.clone();
        cancel.push(Enter);
        let (result, screens, asked) = run(cancel);
        result.unwrap();
        assert!(asked[1].contains("Q: Which language?\nA: rust\nQ: Tests too?\nA: \n"));
        assert!(
            screens
                .iter()
                .any(|s| s.contains("wrote this prompt:\n\nReview the Rust diff and its tests."))
        );
        assert!(prompt_files(&prompts).unwrap().is_empty());
        // Name it: saved through the editor under the checked name.
        keys.extend([Down, Enter]);
        keys.extend(typed("review-diff"));
        keys.push(Enter);
        run(keys.clone()).0.unwrap();
        assert_eq!(prompt_files(&prompts).unwrap(), ["review-diff"]);
        // A name that leaves the folder is refused.
        let mut bad = keys[..keys.len() - 12].to_vec();
        bad.extend(typed("../x"));
        bad.push(Enter);
        assert!(run(bad).0.is_err());
        assert_eq!(prompt_files(&prompts).unwrap(), ["review-diff"]);
        std::fs::remove_dir_all(dir).unwrap();
    }
    /// v7.7 ticket 169: a sequence request holds only skill names and descriptions and the
    /// saved prompts' names by how often each was sent; the sequence and its new prompts are
    /// saved only on Save.
    #[test]
    fn ask_for_a_sequence_sends_only_skill_names_and_top_prompts() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-ai-seq-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let home = dir.join("home");
        std::fs::create_dir_all(home.join(".claude/skills/review")).unwrap();
        std::fs::write(
            home.join(".claude/skills/review/SKILL.md"),
            "---\nname: review\ndescription: Reviews a diff\n---\nSECRET SKILL BODY\n",
        )
        .unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let prompts = crate::actions::prompts_dir_for(&path).unwrap();
        std::fs::create_dir_all(&prompts).unwrap();
        for name in ["fix", "plan"] {
            std::fs::write(prompts.join(name), "SECRET PROMPT TEXT\n").unwrap();
        }
        let usage = dir.join("usage");
        let mut day = crate::usage::Day::default();
        day.add("prompt", "plan", 7);
        crate::usage::flush(&usage, crate::usage::today(), &day).unwrap();
        let reply =
            "sequence\tship\nstep\tplan\nnew\tship-it\tRun /review then commit\nstep\tship-it\n";
        let run = |then: Vec<Key>| {
            let mut keys = vec![Enter];
            keys.extend(then);
            let mut ui = Script {
                keys: keys.into(),
                claude: reply.into(),
                usage: Some(usage.clone()),
                lookup: (String::new(), Some(home.clone()), None),
                ..Default::default()
            };
            let result = ask_for(&mut ui, &path, AskKind::Sequence);
            assert!(ui.keys.is_empty());
            (result, ui.screens, ui.asked)
        };
        let (result, screens, asked) = run(vec![Enter]); // Cancel
        result.unwrap();
        let request = &asked[0];
        assert!(request.contains("- review: Reviews a diff\n"), "{request}");
        assert!(
            request.contains("- plan (sent 7 times)\n- fix (sent 0 times)\n"),
            "{request}"
        );
        assert!(
            !request.contains("SECRET"),
            "never skill bodies or prompt text"
        );
        assert!(
            screens
                .iter()
                .any(|s| s.contains("1. plan (saved)\n2. ship-it (new): Run /review then commit"))
        );
        assert!(mappings::load_config(&path).unwrap().sequences.is_empty());
        assert!(!prompts.join("ship-it").exists());
        run(vec![Down, Enter, Enter, Enter]).0.unwrap(); // Save: the first agent, as it is
        let config = mappings::load_config(&path).unwrap();
        let steps = mappings::saved_sequence(&config, "ship").unwrap();
        assert_eq!(steps.len(), 2);
        assert_eq!(
            std::fs::read_to_string(prompts.join("ship-it")).unwrap(),
            "Run /review then commit\n"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }
    /// v7.7 ticket 169: a preset is saved to Presets and not applied; a whole setup and an
    /// action family save only on Save; a family's action is offered in /configure; a family
    /// with a command is refused.
    #[test]
    fn ask_for_a_preset_a_setup_and_a_family_save_only_on_save() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-ai-more-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let before = config_bytes(&path);
        let file = |list: Vec<Mapping>, name: &str| {
            format!(
                "```\n{}```\n",
                mappings::export_profile(&mappings::Profile {
                    name: name.into(),
                    apps: vec![],
                    mappings: list,
                })
                .unwrap()
            )
        };
        let xbox = file(
            vec![Mapping::new(Control::button(6), "Ctrl+N", "hold").unwrap()],
            "AI",
        );
        let ask = |kind, keys: Vec<Key>, claude: String| {
            let mut ui = Script {
                keys: keys.into(),
                claude,
                ..Default::default()
            };
            let result = ask_for(&mut ui, &path, kind);
            assert!(ui.keys.is_empty());
            (result, ui.screens, ui.asked)
        };
        // Preset: named, saved to Presets, the config itself unchanged.
        let mut keys = typed("Stream");
        keys.push(Enter);
        keys.extend(typed("streaming"));
        keys.extend([Enter, Down, Space, Enter, Down, Enter]);
        let (result, screens, asked) = ask(AskKind::Preset, keys, xbox.clone());
        result.unwrap();
        assert!(asked[0].contains("A whole setup saved as a preset for later: streaming"));
        assert!(screens.iter().any(|s| s.contains("not applied")));
        let preset =
            mappings::load_config(&beside(&path, "presets").join("Stream.preset")).unwrap();
        assert_eq!(preset.mappings[0].keys, ["Ctrl", "N"]);
        assert_eq!(config_bytes(&path), before);
        // Whole setup: Cancel saves nothing; Save fills the button.
        let mut keys = typed("I stream");
        keys.extend([Enter, Down, Space, Enter]);
        let mut cancel = keys.clone();
        cancel.push(Enter);
        let (result, _, asked) = ask(AskKind::Setup, cancel, xbox.clone());
        result.unwrap();
        assert!(asked[0].contains("A whole setup for: I stream."));
        assert_eq!(config_bytes(&path), before);
        keys.extend([Down, Enter]);
        ask(AskKind::Setup, keys, xbox).0.unwrap();
        let config = mappings::load_config(&path).unwrap();
        assert!(
            mappings::default_on(&config, mappings::GAMEPAD_CONTEXT, Control::button(6)).is_some()
        );
        // Family: saved under families/, then one of its actions copied in /configure.
        let pad = |n| Control::from_note(10, n).unwrap();
        let mut close = Mapping::new(pad(37), "Ctrl+W", "hold").unwrap();
        close.label = "Close tab".into();
        let family = file(
            vec![Mapping::new(pad(36), "Ctrl+T", "hold").unwrap(), close],
            "Browser",
        );
        let mut keys = typed("browser tabs");
        keys.extend([Enter, Enter]);
        assert!(ask(AskKind::Family, keys.clone(), family.clone()).0.is_ok()); // Cancel
        assert!(!beside(&path, "families").join("Browser.family").exists());
        keys.pop();
        keys.extend([Down, Enter]);
        let (result, _, asked) = ask(AskKind::Family, keys.clone(), family.clone());
        result.unwrap();
        assert!(asked[0].contains("browser tabs") && asked[0].contains("- app:"));
        assert!(beside(&path, "families").join("Browser.family").exists());
        let mut ui = Script {
            keys: vec![Enter, Down, Enter].into(),
            ..Default::default()
        };
        let copy = family_mapping(&mut ui, &path, Control::button(3), mappings::Input::Pad)
            .unwrap()
            .unwrap();
        assert_eq!(
            (copy.control, copy.keys.join("+")),
            (Control::button(3), "Ctrl+W".into())
        );
        // A family with a command is refused naming the control; nothing saved.
        let command = Mapping::new_action(
            pad(36),
            mappings::Input::Pad,
            crate::actions::Action::Command {
                window: "command".into(),
                dir: "/tmp".into(),
                line: "rm -rf ~".into(),
            },
        )
        .unwrap();
        let error = ask(
            AskKind::Family,
            keys[..keys.len() - 2].to_vec(),
            file(vec![command], "Bad"),
        )
        .0
        .unwrap_err()
        .to_string();
        assert!(error.contains("would run a terminal command"), "{error}");
        assert!(!beside(&path, "families").join("Bad.family").exists());
        std::fs::remove_dir_all(dir).unwrap();
    }
    /// v7.7 ticket 170: Improve clones the source with the URL as one argument, then shows
    /// Claude Code on it with the wish as one argument; nothing goes through a shell and
    /// nothing is saved.
    #[test]
    fn ask_how_to_improve_opens_claude_code_on_the_source() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-ai-improve-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let before = config_bytes(&path);
        let home = dir.join("home");
        let source = home.join(".local/share/vibeconsole/source");
        let source_text = source.display().to_string();
        let run = |wish: &str| {
            let mut keys = typed(wish);
            keys.extend([Enter, Enter]);
            let mut ui = Script {
                keys: keys.into(),
                lookup: (String::new(), Some(home.clone()), None),
                ..Default::default()
            };
            ask_for(&mut ui, &path, AskKind::Improve).unwrap();
            assert!(ui.keys.is_empty());
            (ui.argv, ui.shown, ui.screens)
        };
        let (argv, shown, screens) = run("--add a; rm -rf ~ plugin");
        assert_eq!(
            argv,
            [vec![
                "git",
                "clone",
                "--depth",
                "1",
                "https://github.com/7kim/vibeconsole",
                source_text.as_str()
            ]]
        );
        // v7.7 ticket 183: the skill first, the wish last, all one argument.
        assert_eq!(shown.len(), 1);
        assert_eq!(shown[0][..3], ["improve", source_text.as_str(), "claude"]);
        assert_eq!(shown[0].len(), 4);
        assert!(shown[0][3].starts_with(
            "VibeConsole's instructions for this ask (the vibeconsole-ask-improve skill)"
        ));
        assert!(shown[0][3].ends_with("\n---\n\nadd a; rm -rf ~ plugin"));
        assert!(
            screens
                .iter()
                .any(|s| s.contains("VibeConsole saved nothing"))
        );
        // Already cloned: updated, never cloned again.
        std::fs::create_dir_all(source.join(".git")).unwrap();
        let (argv, shown, _) = run("themes");
        assert_eq!(
            argv,
            [vec!["git", "-C", source_text.as_str(), "pull", "--ff-only"]]
        );
        assert!(shown[0][3].ends_with("\n---\n\nthemes"));
        assert_eq!(config_bytes(&path), before);
        std::fs::remove_dir_all(dir).unwrap();
    }
    /// v7.7 ticket 148: a question goes to the agent with what `describe` says; the answer is
    /// shown and nothing is saved; a proposed profile goes through the review and Cancel
    /// saves nothing.
    #[test]
    fn ask_about_my_setup_answers_and_saves_nothing() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-about-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let before = config_bytes(&path);
        let mut keys = typed("Why didn't Pad 6 fire?");
        keys.extend([Enter, Up, Enter]); // ask; Back (last row)
        let mut ui = Script {
            keys: keys.into(),
            claude: "Pad 6 has no mapping in Program 1, so it does nothing.".into(),
            ..Default::default()
        };
        ask_for(&mut ui, &path, AskKind::About).unwrap();
        assert!(ui.asked[0].contains("Question: Why didn't Pad 6 fire?"));
        assert!(
            ui.asked[0].contains("VibeConsole: what each device has"),
            "describe sent"
        );
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("nothing was changed") && s.contains("Pad 6 has no mapping"))
        );
        assert_eq!(config_bytes(&path), before);

        // A proposed change: reviewed, then Cancel.
        let pad = Control::from_note(10, 36).unwrap();
        let profile = mappings::Profile {
            name: "Firefox".into(),
            apps: vec!["firefox.desktop".into()],
            mappings: vec![Mapping::new(pad, "Ctrl+T", "hold").unwrap()],
        };
        let reply = format!(
            "Add a profile:\n```\n{}```\n",
            mappings::export_profile(&profile).unwrap()
        );
        let mut keys = typed("Make Pad 1 open a tab in Firefox");
        keys.extend([Enter, Up, Up, Enter, Enter]); // ask; Review; Cancel
        let mut ui = Script {
            keys: keys.into(),
            claude: reply,
            ..Default::default()
        };
        ask_for(&mut ui, &path, AskKind::About).unwrap();
        assert!(ui.keys.is_empty());
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Review the change it proposes"))
        );
        assert!(
            ui.screens
                .iter()
                .any(|s| s.starts_with("Claude suggests profile Firefox"))
        );
        assert_eq!(config_bytes(&path), before, "Cancel saves nothing");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 167: the AI tab names the default agent and its Ask for a profile opens
    /// the same flow as Apps & profiles' (one ask path, whose tests cover both entries); the
    /// kinds that aren't built yet are listed but open nothing.
    #[test]
    fn ai_tab_asks_the_default_agent_through_the_profile_path() {
        let (dir, mut ui, _ran, _) = configure_session("ai-tab");
        ui.read_view(None);
        let opens = |ui: &Terminal, tab: usize, text: &str| {
            (ui.tab_panes(tab, 100, usize::MAX).into_iter())
                .flat_map(|(_, entries)| entries)
                .find(|(lines, _)| lines[0].contains(text))
                .unwrap_or_else(|| panic!("{text} on tab {tab}"))
                .1
        };
        let ai = opens(&ui, 9, "Ask Claude Code for a profile…");
        assert!(ai.is_some());
        assert_eq!(ai, opens(&ui, 5, "Ask Claude for a profile…"));
        // v7.7 ticket 168: mappings and agents open their own asks.
        assert_eq!(
            opens(&ui, 9, "for mappings…"),
            Some(Open::Command(ASK_MAPPINGS))
        );
        assert_eq!(
            opens(&ui, 9, "to map agents…"),
            Some(Open::Command(ASK_MAP_AGENTS))
        );
        assert_eq!(
            opens(&ui, 9, "for a prompt…"),
            Some(Open::Command(ASK_PROMPT))
        );
        assert_eq!(
            opens(&ui, 9, "how to improve"),
            Some(Open::Command(ASK_IMPROVE))
        );
        let titles = ui
            .tab_panes(9, 100, usize::MAX)
            .into_iter()
            .map(|(t, _)| t)
            .collect::<Vec<_>>();
        assert!(titles[0].starts_with("Ask Claude Code ·"), "{titles:?}");
        assert!(titles.iter().any(|t| t.starts_with("AI Recommendations")));
        assert!(titles.iter().any(|t| t == "AI settings"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 165: `/ > vol` lists the volume actions; Enter runs the first through the
    /// dispatcher once; an action on a risky mapping isn't listed; paused, nothing runs.
    #[test]
    fn find_actions_run_once_and_never_list_risky_ones() {
        use crate::actions::Action;
        let (dir, mut ui, ran, [mute, ..]) = configure_session("find-actions");
        ui.at_menu = true;
        for m in &mut ui.run_mappings {
            if m.control == mute {
                m.risky = true; // Output mute on a risky pad
            }
        }
        let listed = ui.action_matches("");
        assert!(
            !listed.iter().any(|(_, a)| *a == Action::OutputMute),
            "{listed:?}"
        );
        assert!(listed.iter().any(|(_, a)| *a == Action::MicrophoneMute));
        let vol = ui.action_matches(" vol");
        assert_eq!(vol.len(), 2, "{vol:?}");
        assert!(vol[0].0.contains("on no control"), "{}", vol[0].0);
        let mut steps = vec![Step::Key(Key::Character(b'/'))];
        steps.extend(typed(">vol").into_iter().map(Step::Key));
        steps.extend([Key::Enter, Key::Escape].map(Step::Key));
        ui.script = Some(Play {
            steps: steps.into(),
            ..Play::default()
        });
        assert_eq!(command_menu(&mut ui).unwrap(), None);
        let play = ui.script.take().unwrap();
        assert!(
            play.screens
                .iter()
                .any(|s| s.contains("2 actions · Enter runs it now"))
        );
        assert_eq!(
            ran.recv_timeout(Duration::from_secs(2)).unwrap(),
            Action::Volume { up: true, step: 5 }
        );
        assert!(
            ran.recv_timeout(Duration::from_millis(300)).is_err(),
            "once"
        );
        ui.wanted_run = false;
        ui.script = Some(Play {
            steps: [
                Key::Character(b'/'),
                Key::Character(b'>'),
                Key::Enter,
                Key::Escape,
            ]
            .map(Step::Key)
            .into(),
            ..Play::default()
        });
        command_menu(&mut ui).unwrap();
        assert!(ui.notice.starts_with("Paused: nothing fires"));
        assert!(ran.recv_timeout(Duration::from_millis(300)).is_err());
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 203: a terminal run writes one journal line per status change (run
    /// state, program, a result, an error) and none for a redraw that changed nothing.
    /// A prompt's line carries what the action reported (its file name), never its text.
    #[test]
    fn terminal_run_journals_each_status_change_once() {
        let (dir, mut ui, _ran, [mute, ..]) = configure_session("journal");
        let fired = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let count = fired.clone();
        ui.actions = crate::actions::Dispatcher::with(move |_, _, _| {
            match count.fetch_add(1, std::sync::atomic::Ordering::SeqCst) {
                0 => Ok("Prompt review.md pasted into the focused window".into()),
                _ => Err("Prompt review.md not sent: agent missing".into()),
            }
        });
        ui.context_verified = true;
        ui.at_menu = true;
        ui.script = Some(Play::default());
        let press = |ui: &mut Terminal| {
            ui.handle_events(vec![
                Event::Press(mute),
                Event::Release(mute, crate::ReleaseType::NoteOff),
            ])
            .unwrap();
            let before = (ui.notice.clone(), ui.error.clone());
            for _ in 0..200 {
                ui.draw("").unwrap();
                if (ui.notice.clone(), ui.error.clone()) != before {
                    break;
                }
                std::thread::sleep(Duration::from_millis(10));
            }
        };
        ui.draw("").unwrap();
        ui.draw("").unwrap(); // nothing changed: no second line
        press(&mut ui);
        press(&mut ui);
        ui.pause("test").unwrap(); // what Live's ❚❚ Pause does
        ui.draw("").unwrap();
        ui.draw("").unwrap();
        let mut play = ui.script.take().unwrap();
        let run = "Terminal run | Program 1 verified";
        let expected = [
            format!("{run} | RUNNING"),
            format!("{run} | RUNNING | Prompt review.md pasted into the focused window"),
            format!(
                "{run} | RUNNING | Prompt review.md pasted into the focused window | Action failed: Prompt review.md not sent: agent missing"
            ),
        ];
        let paused = play.journal.pop().unwrap();
        assert_eq!(play.journal, expected);
        assert!(paused.starts_with(&format!("{run} | PAUSED")), "{paused}");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 226: a run stopped by a signal journals the pause and one line naming the
    /// signal, after held keys are released and before quit; a second tick adds nothing.
    #[test]
    fn a_signal_stop_journals_the_pause_and_the_signal_before_quit() {
        let (dir, mut ui, _ran, [.., shift]) = configure_session("signal-stop");
        ui.context_verified = true;
        ui.at_menu = true;
        ui.script = Some(Play::default());
        ui.draw("").unwrap();
        ui.handle_events(vec![Event::Press(shift)]).unwrap();
        ui.stopped_by
            .store(signal_hook::consts::SIGTERM as usize, Ordering::SeqCst);
        ui.stop.store(true, Ordering::SeqCst);
        assert!(ui.tick().unwrap_err().to_string() == STOPPED);
        let recorded = &ui.output.as_ref().unwrap().recorded;
        assert!(
            (recorded.iter().rev())
                .find(|(k, _)| *k == evdev::KeyCode::KEY_LEFTSHIFT)
                .is_some_and(|(_, down)| !down),
            "Shift released before the line"
        );
        let _ = ui.tick();
        let play = ui.script.as_ref().unwrap();
        let n = play.journal.len();
        assert!(
            play.journal[n - 2].contains("| PAUSED"),
            "{:?}",
            play.journal
        );
        assert_eq!(
            play.journal[n - 1],
            "Terminal run | stopped by SIGTERM | held keys released"
        );
        drop(ui); // Drop writes the quit line after it
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 164: a fired pad adds a press, its family and the keys it typed, and the
    /// day file holds names and numbers only; Insights builds the recap, tiles, heatmap and
    /// streaks from fixture day files.
    #[test]
    fn usage_counts_fired_actions_and_insights_read_the_days() {
        use crate::usage::{Day, file, flush, today};
        let (dir, mut ui, ran, [mute, down, ..]) = configure_session("usage");
        let usage = dir.join("usage");
        ui.usage_dir = Some(usage.clone());
        ui.handle_events(vec![
            Event::Press(mute),
            Event::Release(mute, crate::ReleaseType::NoteOff),
            Event::Press(down),
            Event::Release(down, crate::ReleaseType::NoteOff),
        ])
        .unwrap();
        let _ = ran.recv_timeout(Duration::from_secs(2));
        ui.flush_usage();
        let text = std::fs::read_to_string(file(&usage, today())).unwrap();
        assert!(
            text.contains(&format!("press\t{}\t1\n", ui.name(mute))),
            "{text}"
        );
        assert!(
            text.contains("family\tshortcut\t1\n") && text.contains("keys\t-\t1\n"),
            "{text}"
        );
        for line in text.lines() {
            let [kind, _, count] = line.split('\t').collect::<Vec<_>>()[..] else {
                panic!("{line}")
            };
            assert!(crate::usage::KINDS.contains(&kind) && count.parse::<u64>().is_ok());
        }
        // Fixture days: fourteen busy days up to yesterday (today has the two presses above).
        let day = today();
        for back in 1..=14 {
            let mut counts = Day::default();
            counts.add("press", "Bank A Pad 5", if back <= 10 { 60 } else { 400 });
            counts.add("prompt", "review", 2);
            flush(&usage, day - back, &counts).unwrap();
        }
        ui.read_insights();
        let all = ui
            .insights
            .iter()
            .flat_map(|(title, rows)| std::iter::once(title.clone()).chain(rows.clone()))
            .collect::<Vec<_>>()
            .join("\n");
        assert!(
            all.contains("Weekly recap") && all.contains("Last week ·"),
            "{all}"
        );
        assert!(all.contains("top control Bank A Pad 5"), "{all}");
        assert!(all.contains("Current streak 15 days · longest 15"), "{all}");
        assert!(
            all.contains('▒') && all.contains('█'),
            "50–149 and 300+ bands drawn"
        );
        assert!(
            all.contains("Prompts sent to agents 28 · top review ×28"),
            "{all}"
        );
        assert!(all.contains("· 0  ░ 1–49  ▒ 50–149  ▓ 150–299  █ 300+ a day"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 162: CONTEXT and TOKENS render from what an agent reports (`▰▰▰▱▱ 62%`,
    /// `1.4M`) and read `—` for one that reports nothing; cards say it in words.
    #[test]
    fn agent_context_and_tokens_render_and_dash_without_them() {
        assert_eq!(context_text(Some(62)), "▰▰▰▱▱ 62%");
        assert_eq!(context_text(Some(0)), "▱▱▱▱▱ 0%");
        assert_eq!(context_text(None), "—");
        assert_eq!(tokens_text(Some(1_400_000)), "1.4M");
        assert_eq!(tokens_text(Some(240_500)), "240k");
        let (dir, mut ui, _ran, _) = configure_session("context");
        ui.status_at = Instant::now() + Duration::from_secs(3600);
        ui.agent_states = vec![
            ("claude".into(), "w1".into(), "thinking"),
            ("codex".into(), "w2".into(), "idle"),
        ];
        ui.contexts
            .insert("claude".into(), (Some(62), Some(200_000), Some(1_400_000)));
        let rows = ui.live_panes(120, usize::MAX).remove(1).1;
        let lines = rows.iter().map(|(l, _)| l[0].clone()).collect::<Vec<_>>();
        assert!(
            lines[1].contains("CONTEXT") && lines[1].contains("TOKENS"),
            "{}",
            lines[1]
        );
        let claude = lines.iter().find(|l| l.contains("claude")).unwrap();
        assert!(
            claude.contains("▰▰▰▱▱ 62%") && claude.contains("1.4M"),
            "{claude}"
        );
        let codex = lines.iter().find(|l| l.contains("codex")).unwrap();
        assert!(
            codex.contains("IDLE") && codex.matches('—').count() >= 2,
            "{codex}"
        );
        ui.agent_cards = true;
        let cards = ui.live_panes(120, usize::MAX).remove(1).1;
        let text = cards
            .iter()
            .flat_map(|(l, _)| l.clone())
            .collect::<Vec<_>>()
            .join("\n");
        assert!(text.contains("Context 62% of 200k · 1.4M tokens"), "{text}");
        assert!(text.contains("Context — · tokens —"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 161: with a fake clock, waits render (`NEEDS INPUT 4m`) and the longest
    /// wait sorts first within a state; the last hour fills as an agent works; `z` Focus lists
    /// only the agents needing input or a decision and counts the rest; Esc leaves Focus.
    #[test]
    fn agent_waits_sort_and_focus_lists_only_who_needs_you() {
        let (dir, mut ui, _ran, _) = configure_session("waits");
        ui.status_at = Instant::now() + Duration::from_secs(3600);
        let t0 = ui.started;
        ui.agent_states = vec![
            ("newer".into(), "w1".into(), "thinking"),
            ("older".into(), "w2".into(), "thinking"),
            ("worker".into(), "w3".into(), "thinking"),
            ("rester".into(), "w4".into(), "idle"),
        ];
        // All working for 20 minutes, sampled every 5 s.
        for tick in 0..240 {
            ui.track_agents(t0 + Duration::from_secs(5 * tick));
        }
        ui.agent_states[1].2 = "needs-input"; // older asks first
        ui.track_agents(t0 + Duration::from_secs(1200));
        ui.agent_states[0].2 = "needs-input"; // newer a minute later
        ui.track_agents(t0 + Duration::from_secs(1260));
        let now = t0 + Duration::from_secs(1200 + 240);
        let rows = ui.agent_rows_at(now);
        let names = rows.iter().map(|r| r.name.as_str()).collect::<Vec<_>>();
        assert_eq!(
            names,
            ["older", "newer", "worker", "rester"],
            "longest wait first"
        );
        assert_eq!(wait_text(rows[0].wait, true), " 4m");
        assert_eq!(wait_text(rows[1].wait, false), " 3 min");
        assert_eq!(rows[2].wait, None, "working has no wait");
        assert!(
            rows[2].hour.contains('█'),
            "busy last hour: {:?}",
            rows[2].hour
        );
        assert_eq!(rows[3].hour.trim(), "", "idle all along");

        ui.at_menu = true;
        ui.script = Some(Play {
            steps: [Key::Character(b'z'), Key::Escape, Key::Escape]
                .map(Step::Key)
                .into(),
            ..Play::default()
        });
        assert_eq!(command_menu(&mut ui).unwrap(), None);
        let play = ui.script.take().unwrap();
        let focus = play
            .screens
            .iter()
            .find(|s| s.contains("Focus · the agents that need you"))
            .expect("z opened Focus");
        assert!(focus.contains("older") && focus.contains("newer"));
        assert!(!focus.contains("● worker") && !focus.contains("● rester"));
        assert!(focus.contains("1 more working · 1 idle · 0 finished"));
        assert!(!ui.focus, "Esc left Focus");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 160: the controller map: the Akai's first row is Pads 5–8 with the
    /// fixture's labels per bank, the pressed pad is marked ◆, unmapped cells ·; every Xbox
    /// control sits at its grid place and Layer 2 changes labels, not places; the header's
    /// chip names the profile in use.
    #[test]
    fn controller_map_labels_marks_places_and_profile_chip() {
        let (dir, mut ui, _ran, [mute, down, ..]) = configure_session("map");
        let path = dir.join("mappings.tsv");
        let mut config = mappings::load_config(&path).unwrap();
        for m in &mut config.mappings {
            m.label = match m.control {
                c if c == mute => "Bank A Pad 5".into(),
                c if c == down => "Bank B Pad 1".into(),
                _ => m.label.clone(),
            };
        }
        for (layer2, key) in [(false, "Enter"), (true, "Space")] {
            let mut a = Mapping::new(Control::button(0), key, "tap").unwrap();
            a.context = mappings::xbox_context(1, layer2);
            config.mappings.push(a);
        }
        mappings::save_config(&path, &config).unwrap();
        ui.run_mappings = ui.context_mappings(&config.mappings);
        ui.read_view(Some(config.clone()));
        let rows = ui.map_rows(&config, 120);
        assert_eq!(rows[0], "── Akai MPK mini 3 · Bank A");
        assert!(
            rows[1].starts_with(" Pad 5 Toggle default output"),
            "first row is Pads 5–8: {}",
            rows[1]
        );
        assert!(
            rows[1].contains("·Pad 6") && rows[2].starts_with("·Pad 1"),
            "{rows:?}"
        );
        ui.pressed = Some((mute, Instant::now()));
        assert!(ui.map_rows(&config, 120)[1].starts_with("◆Pad 5"));
        ui.map_bank_b = true;
        let bank_b = ui.map_rows(&config, 120);
        assert!(
            bank_b[2].starts_with(" Pad 1 Down"),
            "Bank B's labels: {}",
            bank_b[2]
        );
        let xbox = |ui: &Terminal| {
            let rows = ui.map_rows(&config, 120);
            let at = rows.iter().position(|r| r.starts_with("── Xbox")).unwrap();
            rows[at + 1..].to_vec()
        };
        let layer1 = xbox(&ui);
        ui.map_layer2 = true;
        let layer2 = xbox(&ui);
        let place = |rows: &[String]| {
            let row = rows.iter().position(|r| r.contains(" A ")).unwrap();
            (
                row,
                rows[row][..rows[row].find(" A ").unwrap()].chars().count(),
            )
        };
        assert_eq!(place(&layer1), place(&layer2), "same place");
        assert_eq!(place(&layer1).0, 3, "A is the diamond's bottom (row 4)");
        assert!(layer1[3].contains(" A Enter") && layer2[3].contains(" A Space"));
        for name in [
            "LT", "LB", "RB", "RT", "View", "Xbox", "Menu", "Y", "X", "B", "R3", "L3",
        ] {
            assert!(layer1.iter().any(|r| r.contains(name)), "{name}");
        }
        ui.profile = Some("Orca".into());
        assert!(ui.screen("").header.contains("Orca profile · focused"));
        ui.profile = None;
        assert!(ui.screen("").header.contains("| Default |"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 159: SGR mouse: a click on a tab switches to it, a click on a row does
    /// what Enter does there; the wheel moves; a release or another button does nothing.
    #[test]
    fn a_click_switches_tabs_and_opens_rows() {
        assert_eq!(csi_key(b"<0;12;1M"), Key::Click(12, 1));
        assert_eq!(csi_key(b"<0;12;1m"), Key::Other, "a release");
        assert_eq!(csi_key(b"<64;3;3M"), Key::Up);
        assert_eq!(csi_key(b"<65;3;3M"), Key::Down);
        assert_eq!(csi_key(b"<2;3;3M"), Key::Other, "the right button");
        let (dir, mut ui, _ran, _) = configure_session("mouse");
        ui.at_menu = true;
        let at = |frame: &str, text: &str| {
            let rows = plain_rows(frame);
            let (row, line) = (rows.iter().enumerate())
                .find(|(_, l)| l.contains(text))
                .unwrap_or_else(|| panic!("{text} not in:\n{}", rows.join("\n")));
            let column = line[..line.find(text).unwrap()].chars().count() + 2;
            (column as u16, row as u16 + 1)
        };
        // Draw 2 Mappings once to know where /list is.
        ui.script = Some(Play {
            steps: [Key::Character(b'2'), Key::Escape].map(Step::Key).into(),
            ..Play::default()
        });
        command_menu(&mut ui).unwrap();
        let list = at(&ui.rendered, "/list");
        ui.tab = 0;
        ui.menu = 0;
        ui.script = Some(Play {
            steps: [Key::Escape].map(Step::Key).into(),
            ..Play::default()
        });
        command_menu(&mut ui).unwrap();
        let mappings_tab = at(&ui.rendered, "2 Mappings");
        ui.script = Some(Play {
            steps: [
                Key::Click(mappings_tab.0, mappings_tab.1),
                Key::Click(list.0, list.1),
            ]
            .map(Step::Key)
            .into(),
            ..Play::default()
        });
        assert_eq!(
            command_menu(&mut ui).unwrap(),
            Some(2),
            "the click opened /list"
        );
        assert_eq!(ui.tab, 1);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 242: the service's "Flow can't hear" note shows in System with its fix;
    /// Enter asks, then starts the Flow repair through the (fake) action runner. Without
    /// the note, nothing is listed.
    #[test]
    fn system_lists_the_flow_note_and_its_fix_starts_the_repair() {
        use crate::runtime::Fix;
        let (dir, mut ui, ran, _) = configure_session("flow-note");
        ui.status_at = Instant::now() + Duration::from_secs(3600);
        let marker = dir.join(FLOW_MARKER);
        ui.flow_marker = Some(marker.clone());
        ui.read_problems();
        assert!(
            !ui.problems.iter().any(|p| p.fix == Fix::Flow),
            "no note, nothing"
        );
        std::fs::write(&marker, "Flow can't hear VibeConsole's keyboard (the login service, after: Flow repair failed); select Start or repair Wispr Flow\n").unwrap();
        ui.read_problems();
        let index = (ui.problems.iter())
            .position(|p| p.fix == Fix::Flow)
            .expect("the note is listed");
        assert!(
            ui.problems[index]
                .message
                .starts_with("Flow can't hear VibeConsole's keyboard")
        );
        ui.script = Some(Play {
            steps: VecDeque::from([Step::Key(Key::Down), Step::Key(Key::Enter)]),
            ..Play::default()
        });
        ui.fix_problem(index).unwrap();
        let play = ui.script.take().unwrap();
        assert!(
            play.screens
                .iter()
                .any(|s| s.contains("held keys are released"))
        );
        assert!(ui.flow_pending, "the repair started");
        let action = ran.recv_timeout(Duration::from_secs(2)).unwrap();
        assert!(action.flow(), "{action:?}");
        drop(ui);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 157: two doctor problems show in System with the badge !2; Enter on one
    /// asks first, then runs its fixed command through the runner, one argument each; a user
    /// name that isn't an identifier is never put in a command.
    #[test]
    fn doctor_problems_show_in_system_and_fix_through_the_runner() {
        use crate::runtime::{Fix, problems};
        let found = problems(Some(true), |_| true, false, "tester");
        assert_eq!(found.len(), 2, "{found:?}");
        let Fix::Run { args, .. } = &found[0].fix else {
            panic!("uinput is fixed by a command")
        };
        assert_eq!(
            args,
            &["pkexec", "setfacl", "-m", "u:tester:rw", "/dev/uinput"]
        );
        let odd = problems(Some(true), |p| p != "tmux", true, "x; rm -rf ~");
        assert!(matches!(odd[0].fix, Fix::Show(_)), "never in a command");
        assert_eq!(odd[1].message, "tmux missing");
        assert!(problems(None, |_| true, true, "tester").is_empty());

        let (dir, mut ui, _ran, _) = configure_session("problems");
        ui.status_at = Instant::now() + Duration::from_secs(3600);
        ui.problems = found;
        ui.problems_at = Some(Instant::now());
        assert_eq!(ui.screen("").tabs[7], "8 System !2");
        ui.script = Some(Play {
            steps: VecDeque::from([Step::Key(Key::Down), Step::Key(Key::Enter)]),
            ..Play::default()
        });
        ui.fix_problem(0).unwrap();
        let play = ui.script.take().unwrap();
        assert!(
            play.ran
                .contains(&"pkexec setfacl -m u:tester:rw /dev/uinput".to_string()),
            "{:?}",
            play.ran
        );
        assert!(
            play.screens
                .iter()
                .any(|s| s.contains("asks for your password"))
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

