    /// v7.8 ticket 19: after an Xbox press every screen's hints name the Xbox buttons mapped
    /// to its keys (a key with none keeps its own name); the key VibeConsole sent for that
    /// press arriving back keeps them; a typed key brings the keyboard's back; a remapped
    /// Enter shows its own button.
    #[test]
    fn hints_follow_the_xbox_and_go_back_on_a_typed_key() {
        let (dir, mut ui, _ran, _) = configure_session("xbox-hints");
        let path = dir.join("mappings.tsv");
        ui.refresh_hints(&mappings::load_config(&path).unwrap());
        let keyboard = ui.screen("").hints;
        assert!(keyboard.contains("Enter: confirm"), "{keyboard}");
        // The built-in layout: A Enter, B Escape, the D-pad the arrows; nothing sends Space.
        ui.xbox_used(&Event::Press(Control::button(0)));
        let xbox = ui.screen("").hints;
        assert_eq!(
            xbox,
            "D-pad move · Ⓐ confirm · Space select · Ⓑ back · Ctrl+C quit"
        );
        ui.at_menu = true;
        let menu = ui.screen("").hints;
        assert!(
            menu.starts_with("Ⓨ / D-pad tabs · D-pad move · Ⓐ open"),
            "{menu}"
        );
        assert!(menu.contains("/ find"), "no button sends /: {menu}");
        ui.at_menu = false;
        // A's Enter arriving back in the terminal is the Xbox's own: the hints stay.
        ui.keyboard_used(&Key::Enter);
        assert_eq!(ui.screen("").hints, xbox, "the echo keeps the Xbox hints");
        // A key typed on the keyboard brings the keyboard's back.
        ui.keyboard_used(&Key::Down);
        assert_eq!(ui.screen("").hints, keyboard);
        // Enter remapped to Y (A sends Space now): the hints follow the program's buttons.
        let mut config = mappings::load_config(&path).unwrap();
        for (button, key) in [(0, "Space"), (3, "Enter")] {
            let mut m = Mapping::new(Control::button(button), key, "tap").unwrap();
            m.context = mappings::xbox_context(1, false);
            config.mappings.push(m);
        }
        mappings::save_config(&path, &config).unwrap();
        ui.refresh_hints(&config);
        ui.xbox_used(&Event::Press(Control::button(3)));
        let remapped = ui.screen("").hints;
        assert!(remapped.contains("Ⓨ confirm"), "{remapped}");
        assert!(remapped.contains("Ⓐ select"), "{remapped}");
        assert!(!remapped.contains("Ⓐ confirm"), "{remapped}");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 155: `/` Find goes to a row by its label ("presets" → 2 Mappings ›
    /// Presets) and by its old name ("settings xbox tuning" → 7 Xbox); Esc closes; the query
    /// stops at 64 characters. "What moved in 7.7" shows once for a v32 config and not again.
    #[test]
    fn find_by_label_and_old_name_and_what_moved_once() {
        let (dir, mut ui, _ran, _) = configure_session("find");
        let path = dir.join("mappings.tsv");
        ui.at_menu = true;
        ui.read_view(None);
        let find = |query: &str| {
            let mut steps = vec![Step::Key(Key::Character(b'/'))];
            steps.extend(typed(query).into_iter().map(Step::Key));
            steps.push(Step::Key(Key::Enter));
            steps
        };
        let mut steps = find("presets");
        steps.extend(find("settings xbox tuning"));
        steps.push(Step::Key(Key::Character(b'/')));
        steps.extend(typed(&"x".repeat(70)).into_iter().map(Step::Key));
        steps.extend([Step::Key(Key::Escape), Step::Key(Key::Escape)]);
        ui.script = Some(Play {
            steps: steps.into(),
            ..Play::default()
        });
        // The first Find runs from the menu; Enter returns to it on the found row.
        let mut seen = Vec::new();
        assert_eq!(command_menu(&mut ui).unwrap(), None);
        let play = ui.script.take().unwrap();
        for screen in &play.screens {
            if screen.contains("matches in") {
                seen.push(screen.clone());
            }
        }
        assert!(
            seen.iter().any(|s| s.contains("> Mappings › Presets")),
            "{seen:?}"
        );
        assert!(
            seen.iter()
                .any(|s| s.contains("> Settings › Xbox tuning → 7 Xbox")),
            "the old name is found"
        );
        assert!(
            seen.iter()
                .any(|s| s.contains(&format!("/ {}▌", "x".repeat(64)))),
            "the query stops at 64"
        );
        assert_eq!(ui.tab, 6, "Enter went to 7 Xbox");
        // Ticket 153: the old login switch's name finds Start at login.
        let login = ui.find_matches("when this session closes");
        assert_eq!(login.len(), 1);
        assert_eq!(
            login[0].0,
            "Start the service when this session closes → 8 System"
        );

        // What moved: a v32 file hasn't seen it.
        let v33 = saved_text(&path);
        let v32 = v33
            .replace("vibeconsole-mappings-v34", "vibeconsole-mappings-v32")
            .lines()
            .filter(|l| {
                ![
                    "theme\t",
                    "ai-share-usage\t",
                    "seen-7.7\t",
                    "agents-view\t",
                    "default-agent\t",
                    "speakers-rgb\t",
                    "mousepad-rgb\t",
                    "mouse-rgb\t",
                ]
                .iter()
                .any(|k| l.starts_with(k))
            })
            .map(|l| format!("{l}\n"))
            .collect::<String>();
        old_install(&path, v32);
        let mut script = Script {
            keys: [Key::Enter].into(),
            ..Default::default()
        };
        assert_eq!(
            what_moved_once(&mut script, &path).unwrap(),
            Some(0),
            "/pause → 1 Live"
        );
        assert!(
            script
                .screens
                .iter()
                .any(|s| s.contains("What moved in 7.7") && s.contains("> /pause → 1 Live")),
            "{:?}",
            script.screens
        );
        assert!(mappings::load_config(&path).unwrap().look.seen_moved);
        let mut again = Script::default();
        assert_eq!(
            what_moved_once(&mut again, &path).unwrap(),
            None,
            "only once"
        );
        assert!(again.screens.is_empty());
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 154: 8 System's Theme pane lists the 14 themes; Enter saves the pick
    /// (config v33 `theme`) and the next frame is drawn in it.
    #[test]
    fn picking_a_theme_saves_it_and_draws_with_it() {
        let (dir, mut ui, _ran, _) = configure_session("theme-pick");
        let path = dir.join("mappings.tsv");
        ui.at_menu = true;
        ui.tab = 7;
        ui.read_view(None);
        // The rows above the themes (problems, System's own), then the sixth theme: Latte.
        let above = (ui.tab_panes(7, 80, usize::MAX).into_iter())
            .flat_map(|(_, entries)| entries)
            .filter(|(_, open)| open.is_some())
            .take_while(|(_, open)| !matches!(open, Some(Open::Theme(_))))
            .count();
        let mut steps = vec![Step::Key(Key::Character(b'8'))];
        steps.extend((0..above + 5).map(|_| Step::Key(Key::Down)));
        steps.extend([Step::Key(Key::Enter), Step::Key(Key::Escape)]);
        ui.script = Some(Play {
            steps: steps.into(),
            ..Play::default()
        });
        assert_eq!(command_menu(&mut ui).unwrap(), None);
        let saved = mappings::load_config(&path).unwrap();
        assert_eq!(saved.look.theme, "Catppuccin Latte");
        let frame = ui.screen("").render(100, 30, true);
        crate::screen::set_theme("Tokyo Night");
        assert!(
            frame.contains("48;2;239;241;245"),
            "drawn on Latte's ground"
        );
        let rows = (ui.tab_panes(7, 80, usize::MAX).into_iter())
            .flat_map(|(_, entries)| entries.into_iter().flat_map(|(lines, _)| lines))
            .collect::<Vec<_>>();
        assert!(rows.iter().any(|r| r.contains("● Catppuccin Latte")));
        assert!(
            rows.iter()
                .any(|r| r.contains("Catppuccin Latte: light; accents darkened"))
        );
        assert_eq!(rows.iter().filter(|r| r.contains("■■■■■■")).count(), 14);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 150: Tab and → go to the next tab, Shift+Tab and ← to the previous (both
    /// wrap), 1–9 and 0 jump; a pad mapped to Tab switches tabs too. Switching releases
    /// nothing: a held Shift stays down.
    #[test]
    fn tab_keys_and_a_pad_mapped_to_tab_switch_tabs() {
        use Key::*;
        let (dir, mut ui, _ran, [.., shift]) = configure_session("tab-keys");
        let path = dir.join("mappings.tsv");
        let tab_pad = Control::from_note(10, 40).unwrap();
        let mut config = mappings::load_config(&path).unwrap();
        config
            .mappings
            .push(Mapping::new(tab_pad, "Tab", "tap").unwrap());
        mappings::save_config(&path, &config).unwrap();
        ui.run_mappings = ui.context_mappings(&config.mappings);
        let mut output = crate::keyboard::Output::recording(&ui.run_mappings).unwrap();
        output.keyboard.resume();
        ui.output = Some(output);
        ui.handle_events(vec![Event::Press(shift)]).unwrap();
        ui.script = Some(Play {
            steps: VecDeque::from([
                Step::Key(Tab),
                Step::Key(Tab),
                Step::Key(BackTab),
                Step::Key(Right),
                Step::Key(Left),
                Step::Key(Left),
                Step::Key(Left),
                Step::Key(Character(b'5')),
                Step::Key(Character(b'1')),
                tap(tab_pad),
                Step::Key(Escape),
            ]),
            ..Play::default()
        });
        assert_eq!(command_menu(&mut ui).unwrap(), None);
        let play = ui.script.take().unwrap();
        let active = play
            .screens
            .iter()
            .map(|screen| {
                TABS.iter()
                    .map(|(label, _)| *label)
                    .find(|label| screen.contains(&format!("[{label}")))
                    .unwrap_or_else(|| panic!("no active tab in:\n{screen}"))
            })
            .collect::<Vec<_>>();
        assert_eq!(
            active,
            [
                "1 Live",
                "2 Mappings",
                "3 Agents",
                "2 Mappings",
                "3 Agents",
                "2 Mappings",
                "1 Live",
                "0 AI",
                "5 Devices",
                "1 Live",
                "1 Live", // the pad's press; its Tab is read next
                "2 Mappings",
            ]
        );
        let recorded = &ui.output.as_ref().unwrap().recorded;
        assert!(
            !recorded
                .iter()
                .any(|(key, down)| *key == evdev::KeyCode::KEY_LEFTSHIFT && !down),
            "switching tabs is not a transition: Shift is still held"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 151: Live's Agents pane: agent, project, folder and status in that order,
    /// sorted needs input → decision → working → idle → finished, a dot and a word each;
    /// Enter on a tmux agent asks the runner for `select-window`, on an Orca or herdr agent
    /// submits its jump; an outside session opens nothing; the Table | Gallery switch
    /// draws cards and is saved as `agents-view`.
    #[test]
    fn live_agents_sort_go_to_the_agent_and_switch_to_cards() {
        use crate::actions::Action;
        let (dir, mut ui, ran, _) = configure_session("live-agents");
        let path = dir.join("mappings.tsv");
        let repo = dir.join("VibeConsole");
        std::fs::create_dir_all(repo.join(".git")).unwrap();
        std::fs::create_dir_all(repo.join("docs")).unwrap();
        let docs = repo.join("docs").to_string_lossy().into_owned();
        ui.status_at = Instant::now() + Duration::from_secs(3600); // keep these fake agents
        ui.agent_states = vec![
            ("idler".into(), "w1".into(), "idle"),
            ("done".into(), "w2".into(), "finished"),
            ("busy".into(), "w3".into(), "thinking"),
            ("orca-claude".into(), String::new(), "needs-decision"),
            ("asker".into(), "w5".into(), "needs-input"),
            ("herdr-one".into(), String::new(), "idle"),
        ];
        let tmux = (mappings::Host::Tmux, Some(docs.clone()));
        ui.agent_places = vec![
            tmux.clone(),
            tmux.clone(),
            tmux.clone(),
            (mappings::Host::Orca, Some(docs.clone())),
            tmux,
            (mappings::Host::Herdr, None),
        ];
        ui.light_sessions = vec![("/srv/outside".into(), "thinking", 0)];
        ui.projects.insert(docs.clone(), project_of(&docs));
        ui.projects
            .insert("/srv/outside".into(), project_of("/srv/outside"));
        assert_eq!(
            ui.projects[&docs], "VibeConsole",
            "the git top-level's name"
        );

        let wide = ui.live_panes(120, usize::MAX);
        let (title, agents) = &wide[1];
        assert!(title.starts_with("Agents · most urgent first"));
        let lines = agents.iter().map(|(l, _)| l[0].clone()).collect::<Vec<_>>();
        let head = &lines[1];
        let at = |word: &str| head.find(word).unwrap();
        assert!(
            at("AGENT") < at("PROJECT")
                && at("PROJECT") < at("FOLDER")
                && at("FOLDER") < at("STATUS")
        );
        let order = lines[2..]
            .iter()
            .map(|l| l.split_whitespace().nth(1).unwrap().to_owned())
            .collect::<Vec<_>>();
        assert_eq!(
            order,
            [
                "asker",
                "orca-claude",
                "busy",
                "outside",
                "idler",
                "herdr-one",
                "done"
            ]
        );
        for (line, word) in lines[2..].iter().zip([
            "NEEDS INPUT",
            "DECISION",
            "WORKING",
            "WORKING",
            "IDLE",
            "IDLE",
            "FINISHED",
        ]) {
            assert!(line.contains('●') && line.contains(word), "{line}");
        }
        assert!(lines[2].contains("VibeConsole") && lines[2].contains("/VibeConsole/docs"));
        assert!(
            lines[7].contains("—"),
            "herdr without a folder: {}",
            lines[7]
        );
        assert!(agents[5].1.is_none(), "an outside session opens nothing");

        // Entries: Resume, Release all, Quit, Quit until next login, View, (heading), asker,
        // orca-claude, busy,
        // (outside), idler, herdr-one, done. "done" is never entered: it would clear a real
        // status file.
        ui.menu = 0;
        ui.live_start = false; // counted from the first row (ticket 205 starts elsewhere)
        ui.at_menu = true; // as the session does around `command_menu`
        let down = |n| (0..n).map(|_| Step::Key(Key::Down)).collect::<Vec<_>>();
        let mut steps = down(5); // asker (the heading is skipped)
        steps.push(Step::Key(Key::Enter));
        steps.extend(down(1)); // orca-claude
        steps.push(Step::Key(Key::Enter));
        steps.extend(down(3)); // busy, (outside skipped), idler, herdr-one
        steps.push(Step::Key(Key::Enter));
        steps.extend((0..5).map(|_| Step::Key(Key::Up))); // idler, busy, orca, asker, View
        steps.push(Step::Key(Key::Enter));
        steps.push(Step::Key(Key::Escape));
        ui.script = Some(Play {
            steps: steps.into(),
            ..Play::default()
        });
        assert_eq!(command_menu(&mut ui).unwrap(), None);
        let play = ui.script.take().unwrap();
        assert_eq!(play.ran, ["tmux select-window -t vibe:w5"]);
        let got = [
            ran.recv_timeout(Duration::from_secs(2)).unwrap(),
            ran.recv_timeout(Duration::from_secs(2)).unwrap(),
        ];
        assert_eq!(
            got,
            [
                Action::OrcaJump {
                    agent: "orca-claude".into(),
                    folder: docs.clone()
                },
                Action::HerdrFocus("herdr-one".into())
            ]
        );
        let first = &play.screens[0];
        assert!(
            first.contains("> ▶ Resume") || first.contains("> ❚❚ Pause"),
            "{first}"
        );
        assert!(play.screens.iter().any(|s| s.contains("> ● asker")));
        let last = play.screens.last().unwrap();
        assert!(
            last.contains("[Gallery]") && last.contains("┌─ asker "),
            "{last}"
        );
        let cards = ui.live_panes(80, 5).remove(1).1; // entry 5 is asker's card now
        assert!(
            cards[1].0[0].starts_with("╔═ > asker "),
            "selected: {:?}",
            cards[1].0
        );
        assert!(
            cards[2].0[0].starts_with("┌─ orca-claude "),
            "{:?}",
            cards[2].0
        );
        assert!(
            saved_text(&path).contains("\nagents-view\tgallery\n"),
            "the view is saved"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn reset_requires_exact_confirmation_and_preserves_file_on_failed_save() {
        use Key::*;
        for (keys, confirmed) in [
            (vec![Escape], false),
            (vec![Character(b'n'), Character(b'o'), Enter], false),
            (
                vec![
                    Character(b'r'),
                    Character(b'e'),
                    Character(b's'),
                    Character(b'e'),
                    Character(b't'),
                    Enter,
                ],
                true,
            ),
        ] {
            let mut ui = Script {
                keys: keys.into(),
                ..Default::default()
            };
            assert_eq!(reset_confirmation(&mut ui).unwrap(), confirmed);
        }
        let dir = std::env::temp_dir().join(format!("vibeconsole-reset-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let mut config = mappings::Config::default();
        let mut mapping = Mapping::new(Control::note(10, 36).unwrap(), "Shift", "hold").unwrap();
        mapping.context = 7;
        config.mappings.push(mapping);
        config
            .set_idle(
                0,
                crate::feedback::Settings {
                    octave: Some(1),
                    ..Default::default()
                },
            )
            .unwrap();
        config
            .set_idle(
                7,
                crate::feedback::Settings {
                    tempo: Some(90),
                    ..Default::default()
                },
            )
            .unwrap();
        mappings::save_config(&path, &config).unwrap();
        // An old install's mappings.tsv (kept after the move) is backed up too.
        std::fs::write(&path, "kept since the move").unwrap();
        let before =
            vibeconsole_core::config::FILES.map(|f| std::fs::read(path.with_file_name(f)).unwrap());
        let backup = reset_file_at(&path, "20260101-000000").unwrap();
        assert_eq!(backup.file_name().unwrap(), "*.bak-20260101-000000");
        for (file, before) in vibeconsole_core::config::FILES.iter().zip(before) {
            let copy = dir.join(format!("{file}.bak-20260101-000000"));
            assert_eq!(std::fs::read(copy).unwrap(), before, "{file} is backed up");
        }
        assert_eq!(
            std::fs::read(dir.join("mappings.tsv.bak-20260101-000000")).unwrap(),
            b"kept since the move"
        );
        assert_eq!(
            mappings::load_config(&path).unwrap(),
            mappings::Config::default()
        );
        mappings::save_config(&path, &config).unwrap();
        // existing timestamped backup is never overwritten (fixed stamp: no clock race)
        assert!(reset_file_at(&path, "20260101-000000").is_err());
        assert_eq!(mappings::load_config(&path).unwrap(), config);

        let failed = dir.join("failed");
        std::fs::create_dir(&failed).unwrap();
        let failed_path = failed.join("mappings.tsv");
        mappings::save_config(&failed_path, &config).unwrap();
        block_saves(&failed_path);
        assert!(reset_file(&failed_path).is_err());
        assert_eq!(mappings::load_config(&failed_path).unwrap(), config);
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn reset_pauses_and_makes_no_fake_controller_write() {
        let dir = std::env::temp_dir().join(format!(
            "vibeconsole-reset-controller-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let mapping = Mapping::new(Control::note(10, 36).unwrap(), "Shift", "hold").unwrap();
        mappings::save(&path, &[mapping.clone()]).unwrap();
        let mut current = vec![mapping];
        let writes = Arc::new(std::sync::Mutex::new(0));
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        ui.controller = Some(crate::feedback::Controller::fake_for_reset(Arc::clone(
            &writes,
        )));
        let deadline = Instant::now() + Duration::from_secs(1);
        while ui.controller.as_ref().unwrap().baseline.is_none() {
            ui.controller.as_mut().unwrap().poll().unwrap();
            assert!(Instant::now() < deadline);
            std::thread::yield_now();
        }
        ui.wanted_run = true;
        ui.run_mappings = current.clone();
        let backup = ui.reset_confirmed(&mut current).unwrap();
        assert!(!ui.wanted_run && ui.suspended && current.is_empty());
        assert_eq!(*writes.lock().unwrap(), 0);
        assert_eq!(
            mappings::load_config(&path).unwrap(),
            mappings::Config::default()
        );
        let stamp = backup
            .file_name()
            .unwrap()
            .to_string_lossy()
            .replace('*', "");
        assert!(
            dir.join(format!("settings.json{stamp}")).exists(),
            "{backup:?}"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 06: Settings -> MIDI device picks another connected device; its pads are
    /// learned and mapped in its own context, with no feedback step, and survive switching
    /// back to the Akai.
    #[test]
    fn another_midi_device_is_chosen_learned_and_mapped_in_its_own_context() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-device-ui-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let to_device = [Down, Down, Down, Down, Down, Down, Down, Enter];
        let mut keys = to_device.to_vec();
        keys.extend([Down, Enter, Escape]); // nanoPAD2, back
        let mut ui = Script {
            keys: keys.into(),
            midi_devices: vec!["nanoPAD2".into()],
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty());
        let config = mappings::load_config(&path).unwrap();
        assert_eq!(config.midi_active.as_deref(), Some("nanoPAD2"));
        assert_eq!(config.midi_devices, ["nanoPAD2"]);
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("MIDI device: nanoPAD2"))
        );
        let context = config.device_context("nanoPAD2").unwrap();

        let note = Control::note(1, 60).unwrap();
        let mut keys = vec![Enter, Enter, Enter, Enter, Space, Enter];
        keys.extend(std::iter::repeat_n(Down, 7));
        keys.extend([Enter, Enter, Enter]); // done, hold, fire when pressed: no feedback step
        keys.extend([Enter, Tab, Tab, Enter]); // save, finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [note].into(),
            context,
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        let saved = mappings::load_config(&path).unwrap();
        assert_eq!(saved.mappings.len(), 1);
        assert_eq!(saved.mappings[0].context, context);
        assert_eq!(saved.mappings[0].control, note);
        assert_eq!(saved.mappings[0].keys, ["Ctrl"]);
        assert!(!saved.mappings[0].feedback.enabled());
        assert!(saved_text(&path).contains("\tmidi\tnote\t1\t60\t"));

        let mut keys = to_device.to_vec();
        keys.extend([Enter, Escape]); // back to the Akai
        let mut ui = Script {
            keys: keys.into(),
            midi_devices: vec![],
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        let config = mappings::load_config(&path).unwrap();
        assert_eq!(config.midi_active, None);
        assert_eq!(config.midi_devices, ["nanoPAD2"]);
        assert_eq!(config.mappings.len(), 1);
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("nanoPAD2  (not connected)  (in use)"))
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 07: an Xbox button learned in /configure is saved in the Xbox context
    /// (active beside every program) with no feedback step, and replaces its default.
    #[test]
    fn xbox_button_is_mapped_in_configure_and_replaces_its_default() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-xbox-ui-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let a = Control::button(0); // A
        assert_eq!(a.label(), "Xbox A");
        let mut keys = vec![Enter, Enter]; // learn, layer 1 (v7 ticket 97)
        keys.extend([Enter, Enter, Enter, Space, Enter]);
        keys.extend(std::iter::repeat_n(Down, 7));
        keys.extend([Enter, Enter]); // done, hold
        keys.push(Enter); // fire when pressed: no feedback step
        keys.extend([Enter, Tab, Tab, Enter]); // save, finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [a].into(),
            context: 2, // Program 3 open: the button still goes to the Xbox context
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        let saved = mappings::load_config(&path).unwrap().mappings;
        assert_eq!(saved.len(), 1);
        assert_eq!(saved[0].context, mappings::GAMEPAD_CONTEXT);
        assert_eq!(saved[0].keys, ["Ctrl"]);
        let text = saved_text(&path);
        assert!(text.contains("\txbox\tbutton\t1\t0\t0\t"), "{text}");
        let layout = crate::gamepad::layout(&saved);
        assert_eq!(
            layout.iter().find(|m| m.control == a).unwrap().keys,
            ["Ctrl"]
        );
        assert_eq!(layout.len(), crate::gamepad::default_layout().len());
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 42: an Xbox button saves through a non-shortcut family (here Fedora system
    /// action -> Output mute) on the layer chosen, instead of failing validation and pausing.
    #[test]
    fn xbox_button_saves_a_system_action_on_its_layer() {
        use Key::*;
        for (layer, context) in [
            (Enter, mappings::GAMEPAD_CONTEXT),
            (Down, mappings::GAMEPAD_LAYER_2),
        ] {
            let dir = std::env::temp_dir()
                .join(format!("vibeconsole-xbox-family-{}", std::process::id()));
            let _ = std::fs::remove_dir_all(&dir);
            std::fs::create_dir_all(&dir).unwrap();
            let path = dir.join("mappings.tsv");
            mappings::save(&path, &[]).unwrap();
            let a = Control::button(0);
            let mut keys = vec![Enter]; // learn a pad
            keys.push(layer); // its layer comes first (v7 ticket 97)
            if layer == Down {
                keys.push(Enter);
            }
            keys.extend([Down, Down, Enter]); // Music & Sound
            keys.extend([Down, Down, Enter]); // Output mute
            keys.extend([Enter, Enter, Tab, Tab, Enter]); // fire when, save, finish
            let mut ui = Script {
                keys: keys.into(),
                pads: [a].into(),
                context: 2,
                ..Default::default()
            };
            let mut current = Vec::new();
            let result = configure(&mut ui, &path, &mut current);
            assert!(
                result.is_ok(),
                "{result:?}\n{}",
                ui.screens.join("\n----\n")
            );
            let saved = mappings::load_config(&path).unwrap().mappings;
            assert_eq!(saved.len(), 1, "{}", ui.screens.join("\n----\n"));
            assert_eq!(saved[0].control, a);
            assert_eq!(saved[0].context, context);
            assert_eq!(saved[0].action, crate::actions::Action::OutputMute);
            std::fs::remove_dir_all(dir).unwrap();
        }
    }

    /// v7 ticket 76: pushing a stick in angle mode on Learn offers its range or a gesture;
    /// the choice is what gets saved.
    #[test]
    fn learning_a_stick_range_can_save_a_gesture_instead() {
        use crate::gamepad::{ANGLE_BASE, Gesture};
        use Key::*;
        let range = Control::button(ANGLE_BASE + mappings::MAX_RANGES as u8 + 2);
        for (downs, want) in [(5, Gesture::Turn(2).control(1)), (0, range)] {
            let dir = std::env::temp_dir().join(format!(
                "vibeconsole-gesture-{}-{downs}",
                std::process::id()
            ));
            let _ = std::fs::remove_dir_all(&dir);
            std::fs::create_dir_all(&dir).unwrap();
            let path = dir.join("mappings.tsv");
            mappings::save(&path, &[]).unwrap();
            let mut keys = vec![Enter]; // learn a pad: the stick is pushed into range 3
            keys.extend(std::iter::repeat_n(Down, downs));
            keys.push(Enter); // range, or "half circle clockwise"
            keys.push(Enter); // layer 1 (v7 ticket 97)
            keys.extend([Down, Down, Enter, Down, Down, Enter]); // Output mute
            keys.extend([Enter, Enter, Tab, Tab, Enter]); // fire when, save, finish
            let mut ui = Script {
                keys: keys.into(),
                pads: [range].into(),
                context: 2,
                ..Default::default()
            };
            let mut current = Vec::new();
            let result = configure(&mut ui, &path, &mut current);
            assert!(
                result.is_ok(),
                "{result:?}\n{}",
                ui.screens.join("\n----\n")
            );
            assert!(
                ui.screens
                    .iter()
                    .any(|s| s.contains("A half circle clockwise (from any start)")),
                "the gestures are offered"
            );
            let saved = mappings::load_config(&path).unwrap().mappings;
            assert_eq!(saved.len(), 1, "{}", ui.screens.join("\n----\n"));
            assert_eq!(saved[0].control, want);
            assert_eq!(saved[0].context, mappings::GAMEPAD_CONTEXT);
            std::fs::remove_dir_all(dir).unwrap();
        }
    }

    /// v7 ticket 97: learning an Xbox button asks its layer first, showing what each layer
    /// does; a free layer goes straight on (no Replace), and only a taken one asks.
    #[test]
    fn learning_an_xbox_button_asks_its_layer_first_and_replaces_only_that_layer() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-layer-first-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let x = Control::button(2);
        let f8 = Mapping::new(x, "F8", "hold").unwrap(); // layer 1
        mappings::save(&path, &[f8.clone()]).unwrap();
        let mut keys = vec![Enter, Down, Enter]; // learn X, layer 2
        keys.extend([Down, Down, Enter, Down, Down, Enter]); // Music & Sound, Output mute
        keys.extend([Enter, Enter, Tab, Tab, Enter]); // fire when, save, finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [x].into(),
            context: 2,
            ..Default::default()
        };
        let mut current = vec![f8.clone()];
        configure(&mut ui, &path, &mut current).unwrap();
        let screens = ui.screens.join("\n----\n");
        assert!(screens.contains("Which layer is Xbox X on?"), "{screens}");
        assert!(screens.contains("Layer 1 (normal): F8"), "{screens}");
        assert!(
            screens.contains("Layer 2 (while LB is held): free"),
            "{screens}"
        );
        assert!(
            !screens.contains("Already assigned"),
            "a free layer asks no Replace\n{screens}"
        );
        let saved = mappings::load_config(&path).unwrap().mappings;
        assert_eq!(saved.len(), 2, "both layers kept\n{screens}");
        assert!(
            saved
                .iter()
                .any(|m| m.context == mappings::GAMEPAD_CONTEXT && m.keys == ["F8"])
        );
        assert!(saved.iter().any(|m| m.context == mappings::GAMEPAD_LAYER_2
            && m.action == crate::actions::Action::OutputMute));
        // Layer 2 is taken now: learning X there asks, naming that layer's action; Cancel keeps it.
        let before = config_bytes(&path);
        ui.screens.clear();
        ui.pads = [x].into();
        ui.keys = [Enter, Down, Enter, Enter, Escape].into(); // learn X, layer 2, Cancel, leave
        configure(&mut ui, &path, &mut current).unwrap();
        let screens = ui.screens.join("\n----\n");
        assert!(
            screens.contains("Layer 2 (while LB is held): Toggle default output mute"),
            "{screens}"
        );
        assert!(screens.contains("Already assigned:"), "{screens}");
        assert_eq!(config_bytes(&path), before, "Cancel changes nothing");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 42: every non-shortcut family the user tried on an Xbox button saves there
    /// (the user's notes: launch with hold to quit, prompt, run command in tmux, sequence of
    /// steps, Orca, T3 Code, herdr, prompt sequence, terminal command).
    #[test]
    fn xbox_button_saves_in_every_action_family() {
        use crate::actions::Action;
        use Key::*;
        fn text(s: &str) -> Vec<Key> {
            s.bytes()
                .map(|b| {
                    if b == b' ' {
                        Key::Space
                    } else {
                        Key::Character(b)
                    }
                })
                .collect()
        }
        let family = |n: usize| {
            let mut keys = vec![Enter, Enter]; // learn a pad, layer 1 (v7 ticket 97)
            keys.extend(vec![Down; n]);
            keys.push(Enter);
            keys
        };
        let dir = std::env::temp_dir().join(format!("vibeconsole-xbox-all-{}", std::process::id()));
        let work = dir.to_string_lossy().into_owned();
        let command = |line: &str| {
            let mut keys = text(line);
            keys.push(Enter);
            keys.extend(text(&work));
            keys.push(Enter);
            keys
        };
        let cases: Vec<(&str, Vec<Key>, Vec<Key>, fn(&Action) -> bool)> = vec![
            (
                "launch, hold to quit",
                [family(1), vec![Enter, Enter]].concat(), // v7.8 ticket 21: hold to quit first
                vec![Enter, Enter, Down, Enter], // layer 1, fire when pressed, save and finish
                |a| matches!(a, Action::AppToggleQuit(_)),
            ),
            (
                "prompt",
                [
                    family(3),
                    vec![Enter],
                    text("review"),
                    vec![Enter, Enter, Enter],
                ]
                .concat(),
                vec![Enter, Enter, Enter, Down, Enter], // layer, fire when, status off, finish
                |a| matches!(a, Action::Prompt { .. }),
            ),
            (
                "run command in tmux",
                [family(4), command("claude")].concat(),
                vec![Enter, Enter, Enter, Down, Enter],
                |a| matches!(a, Action::Command { .. }),
            ),
            (
                "sequence of steps",
                [
                    family(5),
                    vec![
                        Enter, Down, Enter, Enter, Enter, Enter, Enter, Down, Down, Enter,
                        Enter, // v7.8 ticket 17: all at once
                    ],
                ]
                .concat(),
                vec![Enter, Enter, Enter, Down, Enter],
                |a| matches!(a, Action::Sequence(_)),
            ),
            (
                "orca needs me",
                [family(6), vec![Enter]].concat(),
                vec![Enter, Enter, Down, Enter], // layer, fire when, finish (Orca keys: no status)
                |a| a.encode().contains("Ctrl+J"),
            ),
            (
                "t3 code",
                [family(7), vec![Down, Down, Enter]].concat(),
                vec![Enter, Enter, Down, Enter],
                |a| matches!(a, Action::T3(_)),
            ),
            (
                "herdr",
                [family(8), vec![Down, Enter]].concat(),
                vec![Enter, Enter, Down, Enter],
                |a| matches!(a, Action::HerdrFocus(_)),
            ),
            (
                "prompt sequence",
                [
                    family(9),
                    vec![Enter, Enter, Enter, Enter, Down, Enter, Down, Down, Enter],
                ]
                .concat(),
                vec![Enter, Enter, Down, Enter], // layer, fire when, finish (no status step)
                |a| matches!(a, Action::PromptSequence(_)),
            ),
            (
                "terminal command",
                [family(10), command("sudo dnf update")].concat(),
                vec![Enter, Enter, Down, Enter], // layer, status off, finish (always held)
                |a| matches!(a, Action::Command { .. }),
            ),
        ];
        for (name, action, tail, check) in cases {
            let _ = std::fs::remove_dir_all(&dir);
            std::fs::create_dir_all(dir.join("prompts")).unwrap();
            std::fs::write(dir.join("prompts/review"), "Review this change.\n").unwrap();
            let path = dir.join("mappings.tsv");
            mappings::save(&path, &[]).unwrap();
            let a = Control::button(0);
            let mut ui = Script {
                // Each tail starts with the layer answer it had before ticket 97; the layer is
                // now asked first (in `family`), so it is dropped here.
                keys: [action, tail[1..].to_vec()].concat().into(),
                pads: [a].into(),
                orca: vec![("claude".into(), "/work/a".into())],
                t3: r#"[{"key":"mod+]","command":"thread.next"}]"#.into(),
                herdr: vec!["api".into(), "docs".into()],
                ..Default::default()
            };
            let mut current = Vec::new();
            let result = configure(&mut ui, &path, &mut current);
            let screens = ui.screens.join("\n----\n");
            assert!(result.is_ok(), "{name}: {result:?}\n{screens}");
            assert!(ui.keys.is_empty(), "{name}: keys left\n{screens}");
            let saved = mappings::load_config(&path).unwrap().mappings;
            assert_eq!(saved.len(), 1, "{name}");
            assert_eq!(saved[0].control, a, "{name}");
            assert_eq!(saved[0].context, mappings::GAMEPAD_CONTEXT, "{name}");
            assert!(check(&saved[0].action), "{name}: {:?}", saved[0].action);
        }
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 50: every control kind (pad, piano key, knob, joystick, Xbox button) saves
    /// through every action family it is offered, and is offered exactly the families it can
    /// take; a favourite it can't take is refused by name and saves nothing.
    #[test]
    fn every_kind_saves_through_every_family_it_offers() {
        use Key::*;
        use mappings::Input;
        fn text(s: &str) -> Vec<Key> {
            s.bytes()
                .map(|b| if b == b' ' { Space } else { Character(b) })
                .collect()
        }
        let dir = std::env::temp_dir().join(format!("vibeconsole-matrix-{}", std::process::id()));
        let work = dir.to_string_lossy().into_owned();
        let command = |line: &str| [text(line), vec![Enter], text(&work), vec![Enter]].concat();
        let prompt = [vec![Enter], text("review"), vec![Enter, Enter, Enter]].concat();
        let shortcut = vec![
            Enter, Enter, Space, Enter, Down, Down, Down, Down, Down, Down, Down, Enter,
        ];
        // What the family needs, then the steps up to Review (behaviour, pad light, layer,
        // fire when, status: each a plain Enter, so only their number matters).
        let family_keys = |family: usize, kind: &str| -> Vec<Key> {
            match family {
                0 => {
                    let after = match kind {
                        "pad" => 3,  // behaviour, hardware feedback, fire when
                        "knob" => 1, // knob step
                        "joystick" => 0,
                        _ => 2, // behaviour, fire when
                    };
                    [shortcut.clone(), vec![Enter; after]].concat()
                }
                1 => vec![Enter; 4], // app, second press, fire when, status
                2 => vec![Enter; 3],
                3 => [prompt.clone(), vec![Enter, Enter]].concat(),
                4 => [command("claude"), vec![Enter, Enter]].concat(),
                5 => vec![
                    Enter, Down, Enter, Enter, Enter, Enter, Enter, Down, Down, Enter, Enter,
                    Enter, Enter, // v7.8 ticket 17: the mode, all at once
                ],
                6 => [
                    vec![Enter],
                    prompt.clone(),
                    vec![Down, Enter],
                    prompt.clone(),
                    vec![Down, Down, Down, Enter],
                ]
                .concat(),
                7 => [
                    text(&format!("{work}/value")),
                    vec![Enter, Enter, Enter, Enter],
                ]
                .concat(),
                8 => vec![Enter, Enter, Enter],
                9 => vec![Down, Down, Enter, Enter],
                10 => vec![Down, Enter, Enter],
                11 => vec![
                    Enter, Enter, Enter, Enter, Down, Enter, Down, Down, Enter, Enter,
                ],
                12 => [command("sudo dnf update"), vec![Enter]].concat(),
                14 => vec![Enter, Enter], // v7.7 ticket 169: the family, its one action
                15 => vec![Enter, Enter], // v7.7 ticket 182: the first tmux agent, fire when
                // v7.8 ticket 12: the System update (a held terminal command: fire when isn't
                // asked), then its status feedback.
                17 => vec![Enter, Enter],
                18 => vec![Enter; 3], // v7.8 ticket 14: Firefox, New tab, fire when
                // v7.8 ticket 11: Left click, then what a shortcut asks after its behaviour.
                16 => match kind {
                    "pad" => vec![Enter; 3],  // click, hardware feedback, fire when
                    "knob" => vec![Enter; 2], // click, knob step
                    "joystick" => vec![Enter],
                    _ => vec![Enter; 2], // click, fire when
                },
                _ if kind == "knob" => vec![Enter, Enter], // 13: the favourite, knob step
                _ => vec![Enter],                          // 13: the starred favourite
            }
        };
        let knob = Control {
            channel: 1,
            id: 70,
            message: crate::Message::Cc,
            direction: 1,
        };
        let joystick = Control {
            message: crate::Message::Bend,
            channel: 1,
            id: 0,
            direction: 1,
        };
        let stick = Input::Joystick {
            center: 8192,
            min: 0,
            max: 16383,
            deadzone: 1024,
            hysteresis: 128,
        };
        let pressed = vec![0, 1, 2, 3, 4, 5, 8, 9, 10, 11, 12, 16, 14, 15, 17, 18];
        // (kind, learn page, control, motion, families offered)
        let kinds: Vec<(&str, usize, Control, Option<Input>, Vec<usize>)> = vec![
            (
                "pad",
                0,
                Control::from_note(10, 40).unwrap(),
                None,
                pressed.clone(),
            ),
            (
                "piano key",
                1,
                Control::note(1, 60).unwrap(),
                None,
                pressed.clone(),
            ),
            (
                "knob",
                2,
                knob,
                Some(Input::Knob { step: 4 }),
                vec![0, 2, 6, 7, 16],
            ),
            ("joystick", 3, joystick, Some(stick), vec![0, 16]),
            ("Xbox button", 4, Control::button(0), None, pressed),
        ];
        // The favourite: Output mute on another pad.
        let starred = Mapping::new_action(
            Control::from_note(10, 51).unwrap(),
            Input::Pad,
            crate::actions::Action::OutputMute,
        )
        .unwrap();
        let mut failures = Vec::new();
        for (kind, page, control, motion, offered) in kinds {
            for (i, &family) in offered.iter().enumerate() {
                let _ = std::fs::remove_dir_all(&dir);
                std::fs::create_dir_all(dir.join("prompts")).unwrap();
                std::fs::write(dir.join("prompts/review"), "Review this change.\n").unwrap();
                std::fs::create_dir_all(dir.join("families")).unwrap();
                let keys_family = mappings::Profile {
                    name: "Keys".into(),
                    apps: vec![],
                    mappings: vec![
                        Mapping::new(Control::from_note(10, 36).unwrap(), "Ctrl+T", "hold")
                            .unwrap(),
                    ],
                };
                std::fs::write(
                    dir.join("families/Keys.family"),
                    mappings::export_profile(&keys_family).unwrap(),
                )
                .unwrap();
                let path = dir.join("mappings.tsv");
                let mut config = mappings::Config::default();
                config.mappings = vec![starred.clone()]; // an existing assignment, unstarred
                mappings::save_config(&path, &config).unwrap();
                let mut keys = vec![Down; page];
                keys.push(Enter);
                if kind == "Xbox button" {
                    keys.push(Enter); // its layer, asked first (v7 ticket 97)
                }
                keys.extend(vec![Down; i]);
                keys.push(Enter);
                keys.extend(family_keys(family, kind));
                keys.extend([Enter, Escape]); // save and configure another, leave
                let (pads, motions) = match motion {
                    Some(input) => (VecDeque::new(), [(control, input, kind.into())].into()),
                    None => ([control].into(), VecDeque::new()),
                };
                let mut ui = Script {
                    keys: keys.into(),
                    pads,
                    motions,
                    orca: vec![("claude".into(), "/work/a".into())],
                    t3: r#"[{"key":"mod+]","command":"thread.next"}]"#.into(),
                    herdr: vec!["api".into()],
                    rows: Some(40), // every family on one screen (ticket 182)
                    ..Default::default()
                };
                let mut current = config.mappings.clone();
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    configure(&mut ui, &path, &mut current)
                }));
                let screens = ui.screens.join("\n----\n");
                let menu = ui.screens.iter().find(|s| s.starts_with("Action family"));
                // The families offered, read off the menu's rows.
                let listed = menu.map_or(vec![], |m| {
                    m.lines()
                        .filter_map(|l| {
                            let row = l.trim_start_matches(['>', ' ']);
                            FAMILIES.iter().position(|f| *f == row)
                        })
                        .collect::<Vec<_>>()
                });
                let saved = mappings::load_config(&path).unwrap().mappings;
                let copy = saved.iter().find(|m| m.control == control);
                let want = match family {
                    13 => 2,
                    14 => 0,
                    f => f,
                };
                // v7 ticket 55: editing the saved copy opens the family menu on its family
                // (pads and Xbox buttons; the starred favourite is listed first).
                let edit_ok = !matches!(kind, "pad" | "Xbox button") || copy.is_none() || {
                    // v7 ticket 109: an Xbox button and the starred Akai pad are listed apart;
                    // the device comes first, then the Xbox list holds only the copy.
                    let pick = if kind == "Xbox button" {
                        vec![Enter, Down, Enter, Enter, Enter] // v7.8 ticket 20: Change action
                    } else {
                        vec![Enter, Enter, Enter] // v7.8 ticket 18: nothing starred, the copy is first
                    };
                    let mut edit = Script {
                        keys: [vec![Down; 5], pick, vec![Escape, Escape]].concat().into(),
                        ..Default::default()
                    };
                    let mut again = saved.clone();
                    configure(&mut edit, &path, &mut again).unwrap();
                    let cursor = format!("> {}", FAMILIES[want]);
                    edit.screens
                        .iter()
                        .find(|s| s.starts_with("Action family"))
                        .is_some_and(|m| m.lines().any(|l| l.starts_with(&cursor)))
                };
                // A joystick can't take the starred Output mute: refused by name, nothing saved.
                let refused = false; // v7.8 ticket 18: the Favourites family is gone
                let ok = matches!(result, Ok(Ok(())))
                    && ui.keys.is_empty()
                    && listed == offered
                    && edit_ok
                    && if refused {
                        copy.is_none() && screens.contains("which Joystick X increase can't take")
                    } else {
                        copy.is_some_and(|m| action_family(m) == want)
                    };
                if !ok {
                    let titles = ui
                        .screens
                        .iter()
                        .map(|s| s.lines().next().unwrap_or(""))
                        .collect::<Vec<_>>();
                    failures.push(format!(
                        "{kind} / {}: {:?} keys left {}, listed {listed:?}, edit opens on it {edit_ok}, saved {:?}\n{}",
                        FAMILIES[family],
                        result
                            .as_ref()
                            .map(|r| r.as_ref().map_err(|e| e.to_string())),
                        ui.keys.len(),
                        copy.map(|m| &m.action),
                        titles.join(" | ")
                    ));
                }
            }
        }
        let _ = std::fs::remove_dir_all(&dir);
        assert!(failures.is_empty(), "{}", failures.join("\n=========\n"));
    }

    /// v7 ticket 55: editing a saved terminal command and pressing Enter all the way through
    /// keeps it a terminal command with its one-second hold (it used to open on "Run command
    /// in tmux", which dropped the hold).
    #[test]
    fn editing_a_terminal_command_keeps_its_hold() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-edit-hold-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let pad = Control::from_note(10, 36).unwrap();
        let action = crate::actions::Action::Command {
            window: "update".into(),
            dir: "/tmp".into(),
            line: "sudo dnf update".into(),
        };
        let mut held = Mapping::new_action(pad, mappings::Input::Pad, action).unwrap();
        held.risky = true;
        mappings::save(&path, &[held]).unwrap();
        // Edit saved assignment, the command, then Enter through every step and save.
        let mut keys = vec![Down; 5];
        keys.extend(vec![Enter; 12]);
        keys.push(Escape);
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        let mut current = mappings::load(&path).unwrap();
        configure(&mut ui, &path, &mut current).unwrap();
        let titles = ui
            .screens
            .iter()
            .map(|s| s.lines().next().unwrap_or("").to_owned())
            .collect::<Vec<_>>();
        let saved = mappings::load(&path).unwrap();
        assert_eq!(saved.len(), 1, "{titles:?}");
        // The tmux window name is made from the pad's name on save; the command stays.
        assert!(
            matches!(&saved[0].action, crate::actions::Action::Command { line, dir, .. }
                if line == "sudo dnf update" && dir == "/tmp"),
            "{titles:?}"
        );
        assert!(saved[0].risky, "the hold was dropped: {titles:?}");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.8 ticket 20: Edit → Change mapped input moves an assignment to a free control in
    /// one save and runs one transition; to a used control it asks first, and Cancel keeps
    /// both; a pad moves onto an Xbox button (replacing its default), and a moved button with
    /// a default leaves "nothing" behind so the default doesn't come back.
    #[test]
    fn change_mapped_input_moves_and_asks_before_replacing() {
        use crate::actions::Action;
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-move-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let [a, b, c] = [36, 37, 38].map(|n| Control::from_note(10, n).unwrap());
        let shift = Mapping::new(a, "Shift", "hold").unwrap();
        let enter = Mapping::new(b, "Enter", "tap").unwrap();
        let mut current = vec![shift.clone(), enter.clone()];
        mappings::save(&path, &current).unwrap();
        // Edit, the first saved pad (A), Change mapped input, press C, Move.
        let edit_a = [Tab, Enter, Enter, Down, Enter];
        let mut ui = Script {
            keys: [&edit_a[..], &[Down, Enter, Escape]].concat().into(),
            pads: [c].into(),
            ..Default::default()
        };
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        let screens = ui.screens.join("\n----\n");
        let n = |note| format!("Note ch10 #{note} (Program 1 unverified)");
        assert!(
            screens.contains(&format!("{} → {}: Shift", n(36), n(38))),
            "{screens}"
        );
        let saved = mappings::load(&path).unwrap();
        assert_eq!(saved, current);
        assert!(
            !saved.iter().any(|m| m.control == a),
            "A is free: {saved:?}"
        );
        let moved = saved.iter().find(|m| m.control == c).unwrap();
        assert_eq!(moved.keys, shift.keys);
        assert_eq!(moved.behavior, shift.behavior);
        assert_eq!(ui.applied, 1, "one transition after the save");

        // To a used control (B, Enter): it asks; Cancel changes nothing.
        let before = config_bytes(&path);
        let edit_c = [Tab, Enter, Down, Enter, Down, Enter]; // C is listed after B
        ui.screens.clear();
        ui.keys = [&edit_c[..], &[Enter, Escape]].concat().into();
        ui.pads = [b].into();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains(&format!("{} does Enter now; it is replaced.", n(37)))),
            "{}",
            ui.screens.join("\n----\n")
        );
        assert_eq!(config_bytes(&path), before, "Cancel keeps both");
        assert_eq!(ui.applied, 1, "no transition on Cancel");
        // Replace: B does Shift, C is free, nothing else is left.
        ui.keys = [&edit_c[..], &[Down, Enter, Escape]].concat().into();
        ui.pads = [b].into();
        configure(&mut ui, &path, &mut current).unwrap();
        let saved = mappings::load(&path).unwrap();
        assert_eq!(saved.len(), 1, "{saved:?}");
        assert_eq!(
            (saved[0].control, saved[0].keys.clone()),
            (b, shift.keys.clone())
        );

        // A pad onto an Xbox button with a built-in default: asked, replaced, layer 1.
        let south = crate::gamepad::default_layout()[0].control;
        ui.screens.clear();
        ui.keys = [Tab, Enter, Enter, Down, Enter, Enter, Down, Enter, Escape].into();
        ui.pads = [south].into();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty(), "{}", ui.screens.join("\n----\n"));
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("does Enter (default) now"))
        );
        let saved = mappings::load(&path).unwrap();
        assert_eq!(saved.len(), 1, "{saved:?}");
        assert_eq!(
            (saved[0].control, saved[0].context, saved[0].keys.clone()),
            (south, mappings::GAMEPAD_CONTEXT, shift.keys.clone())
        );
        // And on to a free button: South is saved as "nothing", so Enter doesn't come back.
        let free = (0..64)
            .map(Control::button)
            .find(|c| {
                !crate::gamepad::is_reserved(*c)
                    && !crate::gamepad::default_layout()
                        .iter()
                        .any(|d| d.control == *c)
            })
            .unwrap();
        ui.keys = [Tab, Enter, Enter, Down, Enter, Enter, Down, Enter, Escape].into();
        ui.pads = [free].into();
        configure(&mut ui, &path, &mut current).unwrap();
        let saved = mappings::load(&path).unwrap();
        let on = |c| {
            saved
                .iter()
                .find(|m| m.control == c)
                .map(|m| m.action.clone())
        };
        assert_eq!(on(south), Some(Action::Nothing), "{saved:?}");
        assert_eq!(on(free), Some(Action::Shortcut));
        std::fs::remove_dir_all(dir).unwrap();
    }

