    /// v7 ticket 08: Settings -> Xbox tuning saves the dead zone and trigger point; a failed
    /// save shows its reason and keeps the old values.
    #[test]
    fn xbox_tuning_saves_and_a_failed_save_keeps_the_old_values() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-tuning-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let to_tuning = vec![Down; 8];
        let mut keys = to_tuning.clone();
        keys.extend([Enter, Enter]); // Xbox tuning, dead zone
        keys.extend(vec![Up; 5]);
        keys.push(Enter); // 20%
        keys.extend(to_tuning.clone());
        keys.extend([Enter, Down, Enter]); // trigger point
        keys.extend(vec![Up; 30]);
        keys.extend([Enter, Escape]); // 60%
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty());
        let tuning = mappings::load_config(&path).unwrap().tuning;
        assert_eq!((tuning.dead_zone, tuning.trigger), (20, 60));
        assert!(!tuning.rumble, "rumble stays off until turned on");
        let mut keys = to_tuning.clone();
        keys.extend([Enter, Down, Down, Enter, Escape]);
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(mappings::load_config(&path).unwrap().tuning.rumble);
        // v7 ticket 108: the headset option is off until turned on, and saves.
        assert!(!mappings::load_config(&path).unwrap().tuning.headset);
        let mut keys = to_tuning.clone();
        keys.push(Enter);
        keys.extend(vec![Down; 7]);
        keys.extend([Enter, Escape]);
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Use the controller headset as speaker and mic: Off"))
        );
        assert!(mappings::load_config(&path).unwrap().tuning.headset);
        // v7 ticket 22: the left stick moves the pointer at speed 12.
        let mut keys = to_tuning.clone();
        keys.extend([Enter, Down, Down, Down, Enter, Down, Enter]);
        keys.extend(to_tuning.clone());
        keys.extend([Enter, Down, Down, Down, Down, Enter, Up, Up, Enter, Escape]);
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty());
        let tuning = mappings::load_config(&path).unwrap().tuning;
        assert_eq!(
            (tuning.mouse, tuning.mouse_speed),
            (mappings::MouseStick::Left, 12)
        );
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Xbox tuning: stick dead zone 20%, triggers fire at 60%"))
        );
        let before = config_bytes(&path);
        block_saves(&path);
        let mut keys = to_tuning;
        keys.extend([Enter, Enter, Up, Enter, Enter, Escape]); // 21% -> Not saved -> Back
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.screens.iter().any(|s| s.contains("Not saved")));
        assert_eq!(config_bytes(&path), before);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 129: Settings -> Xbox tuning shows the driver in use; switching asks first,
    /// then runs exactly `pkexec <this program> xbox-driver xone`; a cancelled password prompt
    /// says nothing changed. Test speaker and Test mic run the ALSA tools on the controller's
    /// card only with xone; with xpad they're unavailable and nothing runs.
    #[test]
    fn xbox_driver_switch_asks_first_and_audio_tests_need_xone() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-driver-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let tuning = |item: usize, then: &[Key]| {
            let mut keys = vec![Down; 8];
            keys.push(Enter); // Xbox tuning
            keys.extend(vec![Down; item]);
            keys.push(Enter);
            keys.extend(then);
            keys.push(Escape);
            keys
        };
        let mut ui = Script {
            keys: tuning(8, &[Down, Enter, Up, Enter, Enter]).into(), // xone, up to Switch (ticket 229: it opens on Back), Back
            driver: Some("xpad"),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Xbox driver: xpad (xpad is the default)"))
        );
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Switch the Xbox driver to xone?")
                    && s.contains("needs the light rule"))
        );
        let exe = std::env::current_exe().unwrap();
        assert_eq!(
            ui.ran,
            [
                "modinfo -n xone_wired".to_owned(),
                format!("pkexec {} xbox-driver xone", exe.display())
            ]
        );
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Replug the controller"))
        );

        // Cancelled password prompt.
        let mut ui = Script {
            keys: tuning(8, &[Down, Enter, Up, Enter, Enter]).into(),
            driver: Some("xpad"),
            run_error: Some(
                "pkexec: Error executing command as another user: Request dismissed".into(),
            ),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Not switched: polkit"))
        );

        // xone not installed: says so before any password prompt.
        let mut ui = Script {
            keys: tuning(8, &[Down, Enter, Enter]).into(),
            driver: Some("xpad"),
            xone_missing: true,
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert_eq!(ui.ran, ["modinfo -n xone_wired"]);
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("xone: unavailable: it isn't installed"))
        );

        // Back at the confirm step (it opens there, ticket 229): only the install check ran.
        let mut ui = Script {
            keys: tuning(8, &[Down, Enter, Enter]).into(),
            driver: Some("xpad"),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert_eq!(ui.ran, ["modinfo -n xone_wired"]);

        // Test speaker and Test mic on xone with the headset card.
        let cards = " 0 [Chroma         ]: USB-Audio - Razer Nommo Chroma\n 3 [Headset        ]: xone-gip-headse - Microsoft Xbox Headset\n".to_owned();
        let mut ui = Script {
            keys: [tuning(9, &[Enter]), tuning(10, &[Enter])].concat().into(),
            driver: Some("xone"),
            cards: cards.clone(),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
        assert_eq!(ui.ran[0], "speaker-test -D plughw:Headset -c 2 -t wav -l 1");
        let file = ui.ran[1].rsplit(' ').next().unwrap().to_owned();
        assert_eq!(
            ui.ran[1],
            format!("arecord -D plughw:Headset -f S16_LE -r 48000 -c 1 -d 5 {file}")
        );
        assert_eq!(ui.ran[2], format!("aplay {file}"));
        assert!(
            !std::path::Path::new(&file).exists(),
            "the recording is deleted"
        );

        // xpad: unavailable, nothing runs.
        let mut ui = Script {
            keys: tuning(9, &[Enter]).into(),
            driver: Some("xpad"),
            cards,
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.ran.is_empty());
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("unavailable: needs xone"))
        );
        // v7 ticket 130: the light rule item asks first, then runs exactly the pkexec command.
        // Ticket 229: the question opens on Back, so Up to "Yes, install".
        let mut ui = Script {
            keys: tuning(11, &[Up, Enter, Enter]).into(),
            driver: Some("xone"),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Xbox button light rule: not installed (Install…)"))
        );
        assert_eq!(
            ui.ran,
            [format!("pkexec {} xbox-light-rule install", exe.display())]
        );
        let mut ui = Script {
            keys: tuning(11, &[Up, Enter, Enter]).into(), // Up to "Yes, remove" (ticket 229)
            driver: Some("xone"),
            rule: true,
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert_eq!(
            ui.ran,
            [format!("pkexec {} xbox-light-rule remove", exe.display())]
        );
        let mut ui = Script {
            keys: tuning(11, &[Enter]).into(), // Back at the confirm: it opens there (ticket 229)
            driver: Some("xone"),
            ..Default::default()
        };
        settings_menu(&mut ui, &path).unwrap();
        assert!(ui.ran.is_empty());
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// Fix after developer test 129: a long title never pushes the options off screen; it's
    /// cut instead, so a confirm always shows Yes and Back.
    #[test]
    fn a_long_title_is_cut_so_every_option_shows() {
        let mut ui = Script {
            keys: vec![Key::Down, Key::Enter].into(),
            ..Default::default()
        };
        let title = vec!["A long explanation line that wraps."; 30].join("\n");
        let chosen = choose(
            &mut ui,
            &title,
            &strings(&["Yes, switch to xpad", "Back (discard: nothing changes)"]),
        )
        .unwrap();
        assert_eq!(chosen, Some(1));
        let first = &ui.screens[0];
        assert!(
            first.contains("> Yes, switch to xpad") && first.contains("Back (discard"),
            "{first}"
        );
        assert!(first.contains(" …"));
    }

