    /// v7 ticket 20: a prompt sequence is built step by step (n+1), reordered and saved.
    #[test]
    fn prompt_sequence_is_built_reordered_and_saved() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-seq-ui-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("prompts")).unwrap();
        std::fs::write(dir.join("prompts/build"), "Build it.\n").unwrap();
        std::fs::write(dir.join("prompts/plan"), "Plan it.\n").unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut keys = vec![Enter];
        keys.extend(vec![Down; 9]); // Prompt sequence family
        keys.push(Enter);
        keys.push(Enter); // Add step 1
        keys.extend([Enter, Enter, Enter, Down, Enter]); // build, use, target, paste and Enter
        keys.extend([Down, Enter]); // Add step 2
        keys.extend([Down, Enter, Enter, Enter, Down, Enter]); // plan
        keys.extend([Down, Enter, Enter]); // step 2: move up
        keys.extend([Down, Down, Down, Enter]); // Done
        keys.extend([Enter, Enter, Enter, Tab, Tab, Enter]);
        let mut ui = Script {
            keys: keys.into(),
            pads: [Control::from_note(10, 36).unwrap()].into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        let saved = mappings::load(&path).unwrap();
        let crate::actions::Action::PromptSequence(steps) = &saved[0].action else {
            panic!("not a prompt sequence: {:?}", saved[0].action);
        };
        let files = steps
            .iter()
            .map(|s| match s {
                crate::actions::Action::Prompt { file, .. } => file.as_str(),
                _ => "?",
            })
            .collect::<Vec<_>>();
        assert_eq!(files, ["plan", "build"]);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 81: a step can be edited for this sequence only (the prompt file stays
    /// byte-for-byte the same), discarded back to the saved prompt, or written to the saved
    /// prompt with "Update prompt to match" after a confirmation. A failed edit or a failed
    /// update changes nothing.
    #[test]
    fn sequence_step_edits_stay_in_the_sequence_until_update_prompt() {
        use crate::actions::{Action, Target};
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-seq-own-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let prompts = dir.join("prompts");
        std::fs::create_dir_all(&prompts).unwrap();
        std::fs::write(prompts.join("plan"), "Saved plan.\n").unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let plan = Action::Prompt {
            file: "plan".into(),
            target: Target::Agent("claude".into()),
            enter: true,
        };
        let edited = Action::PromptOwn {
            file: "plan".into(),
            target: Target::Agent("claude".into()),
            enter: true,
            text: "Review this change.\n".into(), // what the scripted editor writes
        };
        let run = |keys: Vec<Key>, saved: &Action, edit_fails: bool| {
            let mut ui = Script {
                keys: keys.into(),
                edit_fails,
                ..Default::default()
            };
            let result = prompt_sequence_action(&mut ui, &path, Some(saved));
            assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
            (result, ui.screens)
        };
        let done = |n: usize| [vec![Down; n + 1], vec![Enter]].concat(); // past n steps and Add
        // Step 1 → Edit for this sequence only → Done.
        let keys = [vec![Enter, Down, Down, Enter], done(1)].concat();
        let (result, _) = run(keys, &Action::PromptSequence(vec![plan.clone()]), false);
        assert_eq!(
            result.unwrap(),
            Some(Action::PromptSequence(vec![edited.clone()]))
        );
        assert_eq!(
            std::fs::read(prompts.join("plan")).unwrap(),
            b"Saved plan.\n"
        );
        assert!(
            !prompts.join(".plan.sequence-edit").exists(),
            "no scratch left behind"
        );
        // The edited step is marked Edited in this sequence; Discard returns to the prompt.
        let own = Action::PromptSequence(vec![edited.clone()]);
        let keys = [
            vec![Enter],
            vec![Down; 4],
            vec![Enter, Down, Enter],
            done(1),
        ]
        .concat();
        let (result, screens) = run(keys, &own, false);
        assert_eq!(
            result.unwrap(),
            Some(Action::PromptSequence(vec![plan.clone()]))
        );
        assert!(
            screens
                .iter()
                .any(|s| s.contains("Edited in this sequence"))
        );
        // Update prompt to match: Cancel changes nothing; Update writes the prompt and the
        // step points at it again.
        let keys = [vec![Enter], vec![Down; 5], vec![Enter, Enter], done(1)].concat();
        let (result, _) = run(keys, &own, false);
        assert_eq!(result.unwrap(), Some(own.clone()));
        assert_eq!(
            std::fs::read(prompts.join("plan")).unwrap(),
            b"Saved plan.\n"
        );
        let keys = [
            vec![Enter],
            vec![Down; 5],
            vec![Enter, Down, Enter],
            done(1),
        ]
        .concat();
        let (result, _) = run(keys, &own, false);
        assert_eq!(
            result.unwrap(),
            Some(Action::PromptSequence(vec![plan.clone()]))
        );
        assert_eq!(
            std::fs::read(prompts.join("plan")).unwrap(),
            b"Review this change.\n"
        );
        // A failed edit keeps the step and the file; so does an update that can't be written.
        std::fs::write(prompts.join("plan"), "Saved plan.\n").unwrap();
        let keys = vec![Enter, Down, Down, Enter];
        let (result, _) = run(keys, &Action::PromptSequence(vec![plan.clone()]), true);
        assert!(
            result
                .unwrap_err()
                .to_string()
                .contains("editor exited unsuccessfully")
        );
        assert_eq!(
            std::fs::read(prompts.join("plan")).unwrap(),
            b"Saved plan.\n"
        );
        assert!(!prompts.join(".plan.sequence-edit").exists());
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&prompts, std::fs::Permissions::from_mode(0o555)).unwrap();
        let keys = [vec![Enter], vec![Down; 5], vec![Enter, Down, Enter]].concat();
        let (result, _) = run(keys, &own, false);
        std::fs::set_permissions(&prompts, std::fs::Permissions::from_mode(0o755)).unwrap();
        assert!(result.unwrap_err().to_string().contains("file I/O"));
        assert_eq!(
            std::fs::read(prompts.join("plan")).unwrap(),
            b"Saved plan.\n"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 92: a step written only in a sequence reserves its name until it's saved
    /// as a prompt: another sequence, or an earlier step of this one, can't take it.
    #[test]
    fn an_unsaved_step_name_is_reserved_across_sequences() {
        use crate::actions::{Action, Target};
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-seq-reserve-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let prompts = dir.join("prompts");
        std::fs::create_dir_all(&prompts).unwrap();
        std::fs::write(prompts.join("plan"), "Saved plan.\n").unwrap();
        let path = dir.join("mappings.tsv");
        let own = |file: &str| Action::PromptOwn {
            file: file.into(),
            target: Target::Agent("claude".into()),
            enter: true,
            text: "Draft.\n".into(),
        };
        let pad = Control::from_note(10, 36).unwrap();
        let elsewhere = Mapping::new_action(
            pad,
            mappings::Input::Pad,
            Action::PromptSequence(vec![own("draft")]),
        )
        .unwrap();
        mappings::save(&path, &[elsewhere]).unwrap();
        let plan = Action::Prompt {
            file: "plan".into(),
            target: Target::Agent("claude".into()),
            enter: true,
        };
        let typed = |text: &str| text.bytes().map(Character).collect::<Vec<_>>();
        let run = |keys: Vec<Key>, saved: &Action| {
            let mut ui = Script {
                keys: keys.into(),
                ..Default::default()
            };
            let result = prompt_sequence_action(&mut ui, &path, Some(saved)).unwrap();
            assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
            (result, ui.screens)
        };
        // Another sequence's unsaved step holds "draft": refused, naming it; no step added.
        let one = Action::PromptSequence(vec![plan.clone()]);
        let keys = [
            vec![Down, Down, Down, Enter],
            typed("draft"),
            vec![Enter, Enter],
            vec![Down; 2],
            vec![Enter],
        ]
        .concat();
        let (result, screens) = run(keys, &one);
        assert_eq!(result, Some(one.clone()));
        assert!(
            screens
                .iter()
                .any(|s| s.contains("step 1 of Bank A Pad 1 already uses the name draft")),
            "{}",
            screens.join("\n----\n")
        );
        // An earlier step of this sequence holds "local": refused, naming that step.
        let two = Action::PromptSequence(vec![plan.clone(), own("local")]);
        let keys = [
            vec![Down; 4],
            vec![Enter],
            typed("local"),
            vec![Enter, Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, screens) = run(keys, &two);
        assert_eq!(result, Some(two.clone()));
        assert!(
            screens
                .iter()
                .any(|s| s.contains("step 2 of this sequence already uses the name local"))
        );
        // v7 ticket 93: the item and the step list use the ticket's words.
        assert!(
            screens
                .iter()
                .any(|s| s.contains("New prompt (this sequence only)"))
        );
        assert!(
            screens
                .iter()
                .any(|s| s.contains("2. Prompt local (Edited in this sequence)"))
        );
        // A free name is accepted as before.
        let keys = [
            vec![Down, Down, Down, Enter],
            typed("fresh"),
            vec![Enter, Enter, Down, Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, _) = run(keys, &one);
        let Some(Action::PromptSequence(steps)) = result else {
            panic!("no sequence");
        };
        assert!(matches!(&steps[1], Action::PromptOwn { file, .. } if file == "fresh"));
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 81: a step written only in the sequence gets a new prompt name (validated,
    /// not already taken) and sends its own text; "Save as new prompt" then creates that
    /// prompt, never overwriting one that appeared meanwhile, and can take another name.
    #[test]
    fn a_new_sequence_step_is_saved_as_a_new_prompt_without_overwriting() {
        use crate::actions::{Action, Target};
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-seq-new-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let prompts = dir.join("prompts");
        std::fs::create_dir_all(&prompts).unwrap();
        std::fs::write(prompts.join("plan"), "Saved plan.\n").unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let plan = Action::Prompt {
            file: "plan".into(),
            target: Target::Agent("claude".into()),
            enter: true,
        };
        let run = |keys: Vec<Key>, saved: &Action| {
            let mut ui = Script {
                keys: keys.into(),
                ..Default::default()
            };
            let result = prompt_sequence_action(&mut ui, &path, Some(saved)).unwrap();
            assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
            (result, ui.screens)
        };
        let typed = |text: &str| text.bytes().map(Character).collect::<Vec<_>>();
        // "New prompt (this sequence only)": name, target (claude), Paste and Enter,
        // then the editor; Done.
        let keys = [
            vec![Down, Down, Down, Enter],
            typed("follow-up"),
            vec![Enter, Enter, Down, Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, _) = run(keys, &Action::PromptSequence(vec![plan.clone()]));
        let new = Action::PromptOwn {
            file: "follow-up".into(),
            target: Target::Agent("claude".into()),
            enter: true,
            text: "Review this change.\n".into(),
        };
        assert_eq!(
            result,
            Some(Action::PromptSequence(vec![plan.clone(), new.clone()]))
        );
        assert!(!prompts.join("follow-up").exists(), "nothing saved yet");
        // A taken or bad name is refused with the reason, and no step is added.
        for name in ["plan", "../escape"] {
            let keys = [
                vec![Down, Down, Down, Enter],
                typed(name),
                vec![Enter, Enter],
                vec![Down; 2],
                vec![Enter],
            ]
            .concat();
            let (result, screens) = run(keys, &Action::PromptSequence(vec![plan.clone()]));
            assert_eq!(
                result,
                Some(Action::PromptSequence(vec![plan.clone()])),
                "{name}"
            );
            assert!(screens.iter().any(|s| s.starts_with("Not saved")), "{name}");
        }
        // Back on that step changes nothing and writes nothing.
        let seq = Action::PromptSequence(vec![plan.clone(), new.clone()]);
        let keys = [
            vec![Down, Enter],
            vec![Down; 4],
            vec![Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, screens) = run(keys, &seq);
        assert_eq!(result, Some(seq.clone()));
        assert!(!screens.iter().any(|s| s.contains("Write this step's text")));
        assert!(!prompts.join("follow-up").exists());
        // Step 2 → Save as new prompt (its name offered): the prompt is created and the step
        // points at it.
        let keys = [
            vec![Down, Enter],
            vec![Down; 3],
            vec![Enter, Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, _) = run(keys, &seq);
        let saved_as = |file: &str| Action::Prompt {
            file: file.into(),
            target: Target::Agent("claude".into()),
            enter: true,
        };
        assert_eq!(
            result,
            Some(Action::PromptSequence(vec![
                plan.clone(),
                saved_as("follow-up")
            ]))
        );
        assert_eq!(
            std::fs::read(prompts.join("follow-up")).unwrap(),
            b"Review this change.\n"
        );
        // The name was taken meanwhile: Save never overwrites it ("already exists"), and the
        // step can be saved under another name instead; the other prompt stays as it is.
        std::fs::write(prompts.join("follow-up"), "Someone else's.\n").unwrap();
        let keys = [
            vec![Down, Enter],
            vec![Down; 3],
            vec![Enter],
            typed("follow-up"),
            vec![Enter, Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, screens) = run(keys, &seq);
        assert_eq!(result, Some(seq.clone()), "the step keeps its own text");
        assert!(
            screens
                .iter()
                .any(|s| s.starts_with("Not saved") && s.contains("already exists"))
        );
        let keys = [
            vec![Down, Enter],
            vec![Down; 3],
            vec![Enter],
            typed("follow-up-2"),
            vec![Enter],
            vec![Down; 3],
            vec![Enter],
        ]
        .concat();
        let (result, _) = run(keys, &seq);
        assert_eq!(
            result,
            Some(Action::PromptSequence(vec![
                plan.clone(),
                saved_as("follow-up-2")
            ]))
        );
        assert_eq!(
            std::fs::read(prompts.join("follow-up-2")).unwrap(),
            b"Review this change.\n"
        );
        assert_eq!(
            std::fs::read(prompts.join("follow-up")).unwrap(),
            b"Someone else's.\n"
        );
        assert!(
            std::fs::read_dir(&prompts).unwrap().all(|e| !e
                .unwrap()
                .file_name()
                .to_string_lossy()
                .ends_with(".new")),
            "no scratch left"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 21: a launcher pad can minimize on a tap and quit on a one-second hold.
    /// v7.8 ticket 21: the second-press list puts "Minimize; hold 1 second to quit" first
    /// and selected for a new app toggle, then Minimize, then Close; a saved one opens on its
    /// own choice and Enter keeps it.
    #[test]
    fn second_press_offers_hold_to_quit_first_and_keeps_a_saved_choice() {
        use crate::actions::Action;
        let app = "/nonexistent/recorded.desktop".to_string();
        let second_press = |screens: &[String]| {
            screens
                .iter()
                .find(|s| s.starts_with("Second press"))
                .cloned()
                .unwrap()
        };
        let mut new = Script {
            keys: [Key::Enter, Key::Enter].into(), // the app, then the second press as offered
            ..Default::default()
        };
        let made = action_menu(&mut new, 1, mappings::Input::Pad, None, true, None).unwrap();
        assert_eq!(made, Some(Action::AppToggleQuit(app.clone())));
        let rows = second_press(&new.screens);
        let rows = rows
            .lines()
            .skip(1)
            .filter(|l| !l.is_empty())
            .collect::<Vec<_>>();
        assert_eq!(
            rows,
            [
                "> Minimize; hold 1 second to quit (when a window is open, not minimized)",
                "  Minimize",
                "  Close",
            ],
            "{:?}",
            new.screens
        );
        for (saved, mark) in [
            (
                Action::AppToggle {
                    path: app.clone(),
                    close: false,
                },
                "> Minimize  [x] (saved)",
            ),
            (
                Action::AppToggle {
                    path: app.clone(),
                    close: true,
                },
                "> Close  [x] (saved)",
            ),
        ] {
            let mut edit = Script {
                keys: [Key::Enter, Key::Enter].into(),
                ..Default::default()
            };
            let kept =
                action_menu(&mut edit, 1, mappings::Input::Pad, Some(&saved), true, None).unwrap();
            assert_eq!(kept.as_ref(), Some(&saved), "Enter keeps the saved choice");
            assert!(
                second_press(&edit.screens).contains(mark),
                "{:?}",
                edit.screens
            );
        }
    }

