    /// v7 ticket 48: Orca and T3 Code are listed first, once each, matched by desktop ID
    /// (GNOME's screen reader "Orca" isn't); they save as launchers like any app; a missing
    /// herdr says not installed and saves nothing.
    #[test]
    fn agent_apps_are_listed_first_as_launchers() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-agentapps-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let usr = |id: &str| format!("/usr/share/applications/{id}");
        let local = |id: &str| format!("/home/u/.local/share/applications/{id}");
        let apps = vec![
            ("Firefox".into(), usr("firefox.desktop")),
            ("Orca".into(), usr("orca-ide.desktop")),
            ("Orca".into(), usr("orca.desktop")), // the screen reader
            ("T3 Code".into(), local("com.t3tools.T3Code.desktop")),
            (
                "T3 Code (Nightly)".into(),
                local("appimagekit_99c9-T3_Code__Nightly_.desktop"),
            ),
        ];
        // learn, Launch application, the app (Downs), then: hold to quit, fire when, save and finish
        let quit = [Enter, Enter, Down, Enter]; // v7.8 ticket 21: hold to quit is first
        let pick = |downs: usize, then: &[Key]| {
            let mut keys = vec![Enter, Down, Enter];
            keys.extend(vec![Down; downs]);
            keys.push(Enter);
            keys.extend(then);
            let mut ui = Script {
                keys: keys.into(),
                pads: [Control::from_note(10, 42).unwrap()].into(),
                apps: apps.clone(),
                ..Default::default()
            };
            let mut current = Vec::new();
            let result = configure(&mut ui, &path, &mut current).map(|_| current);
            (result, ui.screens.join("\n----\n"))
        };
        let (saved, screens) = pick(0, &quit);
        let list = screens
            .split("\n----\n")
            .find(|s| s.contains("Installed visible applications"))
            .unwrap();
        let rows = |text: &str| list.lines().filter(|l| l.contains(text)).count();
        assert!(
            list.find("Agent app: Orca | orca-ide.desktop").unwrap()
                < list
                    .find("Agent app: T3 Code | com.t3tools.T3Code.desktop")
                    .unwrap()
                && list.find("T3Code.desktop").unwrap() < list.find("Firefox").unwrap(),
            "{list}"
        );
        assert_eq!(rows("T3_Code"), 0, "duplicate shown once:\n{list}");
        assert_eq!(
            rows("Agent app: Orca"),
            1,
            "screen reader isn't the agent app"
        );
        assert_eq!(rows("Agent app: herdr (not installed)"), 1, "{list}");
        assert_eq!(
            saved.unwrap()[0].action,
            crate::actions::Action::AppToggleQuit(usr("orca-ide.desktop"))
        );
        let (saved, _) = pick(1, &quit);
        assert_eq!(
            saved.unwrap()[0].action,
            crate::actions::Action::AppToggleQuit(local("com.t3tools.T3Code.desktop"))
        );

        let before = config_bytes(&path);
        let (_, screens) = pick(4, &[Escape, Escape]); // herdr (not installed): error, leave
        assert!(screens.contains("herdr not installed"), "{screens}");
        assert_eq!(config_bytes(&path), before, "nothing saved");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 23: a terminal command is always a one-second-hold (risky) control.
    #[test]
    fn terminal_commands_always_need_a_one_second_hold() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-termcmd-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut keys = vec![Enter];
        keys.extend(vec![Down; 10]); // Terminal command family
        keys.push(Enter);
        keys.extend(b"sudo dnf update".map(|b| if b == b' ' { Space } else { Character(b) }));
        keys.push(Enter);
        keys.extend(dir.to_string_lossy().bytes().map(Character)); // working directory
        keys.push(Enter);
        keys.extend([Enter, Down, Enter]); // no status feedback, save and finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [Control::from_note(10, 43).unwrap()].into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        assert!(
            !ui.screens.iter().any(|s| s.starts_with("Fire when")),
            "no choice: always held"
        );
        let saved = mappings::load(&path).unwrap();
        assert!(saved[0].risky, "fires only after a one-second hold");
        let crate::actions::Action::Command { window, line, .. } = &saved[0].action else {
            panic!("not a command: {:?}", saved[0].action);
        };
        assert!(!window.is_empty(), "the window is named after the pad");
        assert_eq!(line, "sudo dnf update");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.8 ticket 12: Fedora System's suspend is always held for one second (never asked),
    /// and Lock is asked like any action (pressed by default).
    #[test]
    fn fedora_system_suspend_is_always_held() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-fedora-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let family = |row: usize| {
            let mut keys = vec![Enter];
            keys.extend(vec![Down; 14]); // Fedora System
            keys.push(Enter);
            keys.extend(vec![Down; row]);
            keys.push(Enter);
            keys
        };
        let mut keys = family(3); // the two updates, Lock, Suspend
        keys.extend([Down, Enter]); // save and finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [Control::from_note(10, 43).unwrap()].into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty(), "{}", ui.screens.join("\n---\n"));
        assert!(!ui.screens.iter().any(|s| s.starts_with("Fire when")));
        let saved = mappings::load(&path).unwrap();
        use crate::actions::{Action, System};
        assert_eq!(saved[0].action, Action::System(System::Suspend));
        assert!(saved[0].risky, "fires only after a one-second hold");
        // Lock: asked, and Pressed saves it unheld.
        let mut keys = family(2);
        keys.extend([Enter, Down, Enter]); // Fire when: Pressed; save and finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [Control::from_note(10, 44).unwrap()].into(),
            ..Default::default()
        };
        let mut current = saved.clone();
        configure(&mut ui, &path, &mut current).unwrap();
        let saved = mappings::load(&path).unwrap();
        let lock = saved
            .iter()
            .find(|m| m.action == Action::System(System::Lock))
            .unwrap();
        assert!(!lock.risky);
        // A suspend the file says isn't held is refused, never run unheld.
        let mut unheld = saved[0].clone();
        unheld.risky = false;
        assert!(
            unheld
                .validate()
                .unwrap_err()
                .to_string()
                .contains("held for one second")
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.8 ticket 18: F stars a family and an action inside it (★ first); "★ Favourites"
    /// opens a starred action's own setup; F again unstars; removing an assignment leaves
    /// the stars alone.
    #[test]
    fn stars_on_families_and_actions() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-stars-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let f = Character(b'f');
        let stars = || mappings::load_config(&path).unwrap().favourites;
        // Learn a pad → Down to Music & Sound, F → (now first, ★) Enter → Down 5 to Next
        // track, F → back out.
        let mut ui = Script {
            keys: [
                Enter, Down, Down, f, Enter, Down, Down, Down, Down, Down, f, Escape, Escape, Tab,
                Tab, Enter,
            ]
            .into(),
            pads: [Control::from_note(10, 40).unwrap()].into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert_eq!(stars(), ["family:music", "action:music:Next track"]);
        let screens = ui.screens.join("\n---\n");
        assert!(screens.contains("> ★ Music & Sound"), "{screens}");
        assert!(screens.contains("★ Next track"), "{screens}");
        // ★ Favourites → Next track → its setup (fire when: Pressed) → save and finish.
        let mut ui = Script {
            keys: [Enter, Enter, Enter, Enter, Down, Enter].into(),
            pads: [Control::from_note(10, 41).unwrap()].into(),
            ..Default::default()
        };
        configure(&mut ui, &path, &mut current).unwrap();
        let screens = ui.screens.join("\n---\n");
        assert!(
            screens.contains("> ★ Favourites (1 starred actions)"),
            "{screens}"
        );
        use crate::actions::{Action, Media};
        assert_eq!(
            mappings::load(&path).unwrap()[0].action,
            Action::Media(Media::Next)
        );
        // Removing the assignment leaves the stars alone.
        let mut ui = Script {
            keys: [Tab, Down, Enter, Enter, Down, Enter, Tab, Tab, Enter].into(),
            ..Default::default()
        };
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(
            mappings::load(&path).unwrap().is_empty(),
            "{}",
            ui.screens.join("\n---\n")
        );
        assert_eq!(stars(), ["family:music", "action:music:Next track"]);
        // F on the starred family again unstars it.
        let mut ui = Script {
            keys: [Enter, Down, f, Escape, Tab, Tab, Enter].into(),
            pads: [Control::from_note(10, 42).unwrap()].into(),
            ..Default::default()
        };
        configure(&mut ui, &path, &mut current).unwrap();
        assert_eq!(
            stars(),
            ["action:music:Next track"],
            "{}",
            ui.screens.join("\n---\n")
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.8 ticket 18: v7's slot stars move once: each on an assignment becomes its family's
    /// star (and its action's, where the action's list can be starred); a slot without an
    /// assignment is dropped; profile stars stay.
    #[test]
    fn slot_stars_migrate_to_families_and_actions() {
        let dir = std::env::temp_dir().join(format!("vibeconsole-starmig-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let mute = Mapping::new_action(
            Control::from_note(10, 36).unwrap(),
            mappings::Input::Pad,
            crate::actions::Action::OutputMute,
        )
        .unwrap();
        let keys = Mapping::new(Control::from_note(10, 37).unwrap(), "Ctrl+T", "hold").unwrap();
        let gone = Mapping::new(Control::from_note(10, 38).unwrap(), "F9", "hold").unwrap();
        let mut config = mappings::Config::default();
        config.mappings = vec![mute.clone(), keys.clone()];
        config.favourites = vec![
            mappings::favourite_key(&mute),
            mappings::favourite_key(&gone),
            mappings::profile_favourite_key("Orca"),
            mappings::favourite_key(&keys),
        ];
        mappings::save_config(&path, &config).unwrap();
        migrate_stars(&path).unwrap();
        let after = mappings::load_config(&path).unwrap();
        assert_eq!(
            after.favourites,
            [
                "family:music",
                "action:music:Output mute",
                "profile:Orca",
                "family:shortcut"
            ]
        );
        assert_eq!(after.mappings, config.mappings, "assignments untouched");
        migrate_stars(&path).unwrap(); // once: nothing left to move
        assert_eq!(
            mappings::load_config(&path).unwrap().favourites,
            after.favourites
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

