    #[test]
    fn presets_save_load_and_refuse_bad_files() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-presets-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let a = Mapping::new(Control::from_note(10, 36).unwrap(), "F1", "hold").unwrap();
        mappings::save(&path, &[a.clone()]).unwrap();
        let presets = |keys: Vec<Key>| {
            let mut all = vec![Down; 11];
            all.push(Enter);
            all.extend(keys);
            all.extend([Escape, Escape]);
            let mut ui = Script {
                keys: all.into(),
                ..Default::default()
            };
            settings_menu(&mut ui, &path).unwrap();
            assert!(ui.keys.is_empty());
            ui.screens
        };
        let mut save = vec![Down, Enter]; // Save All Programs Preset
        save.extend(b"Work".map(Character));
        save.push(Enter);
        presets(save);
        let saved = std::fs::read_to_string(dir.join("presets/Work.preset")).unwrap();
        assert!(
            saved.starts_with("{") && saved.contains("\"mappings.json\""),
            "{saved}"
        );
        let b = Mapping::new(Control::from_note(10, 37).unwrap(), "F2", "hold").unwrap();
        mappings::save(&path, &[b]).unwrap();
        presets(vec![Enter, Enter, Enter]); // Work.preset -> Load it -> Back
        assert_eq!(mappings::load(&path).unwrap(), [a]);
        std::fs::write(dir.join("presets/Bad.preset"), "not a config").unwrap();
        let before = config_bytes(&path);
        let screens = presets(vec![Enter, Enter, Enter]); // Bad.preset -> Load -> Back
        assert!(
            screens
                .iter()
                .any(|s| s.contains("Bad.preset") && s.contains("nothing loaded"))
        );
        assert_eq!(config_bytes(&path), before);
        // Presets have no history: replacing or deleting one asks first, Cancel first.
        let work = dir.join("presets/Work.preset");
        let kept = std::fs::read(&work).unwrap();
        let c = Mapping::new(Control::from_note(10, 38).unwrap(), "F3", "hold").unwrap();
        mappings::save(&path, &[c]).unwrap(); // a replace would now change Work.preset
        let mut again = vec![Down, Down, Down, Enter]; // Save All Programs Preset
        again.extend(b"Work".map(Character));
        again.extend([Enter, Enter]); // Replace preset Work.preset? -> Cancel
        presets(again);
        assert_eq!(std::fs::read(&work).unwrap(), kept);
        presets(vec![Down, Enter, Down, Enter, Enter]); // Work -> Delete it -> Cancel
        assert!(work.exists());
        presets(vec![Down, Enter, Down, Enter, Down, Enter]); // Work -> Delete it -> Delete
        assert!(!work.exists());
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 47: Save Program Preset keeps the selected program only and loads back into
    /// it alone; Save All Programs Preset keeps everything; each load says so. A program
    /// preset holding more than one program is refused whole.
    #[test]
    fn program_and_all_programs_presets() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-presets2-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let pad = Control::from_note(10, 36).unwrap();
        let on = |context: u8, keys: &str| {
            let mut m = Mapping::new(pad, keys, "hold").unwrap();
            m.context = context;
            m
        };
        let y = Mapping::new(Control::button(3), "Left", "hold").unwrap();
        let setup = |p1: &str, p2: &str| {
            let mut all = vec![on(0, p1), on(1, p2), y.clone()];
            all.sort_by_key(|m| (m.context, m.control));
            mappings::save(&path, &all).unwrap();
        };
        let keys_of = |context: u8| {
            mappings::load(&path)
                .unwrap()
                .into_iter()
                .find(|m| m.context == context && m.control == pad)
                .map(|m| m.keys.join("+"))
        };
        let presets = |keys: Vec<Key>| {
            let mut all = vec![Down; 11];
            all.push(Enter);
            all.extend(keys);
            all.extend([Escape, Escape]);
            let mut ui = Script {
                keys: all.into(),
                context: 1, // Program 2 selected
                ..Default::default()
            };
            settings_menu(&mut ui, &path).unwrap();
            assert!(ui.keys.is_empty(), "{}", ui.screens.join("\n----\n"));
            ui.screens.join("\n----\n")
        };
        let name = |text: &[u8], mut keys: Vec<Key>| {
            keys.extend(text.iter().map(|c| Character(*c)));
            keys.push(Enter);
            keys
        };
        setup("F1", "F2");
        let mut config = mappings::load_config(&path).unwrap();
        config.profiles.push(mappings::Profile {
            name: "Firefox".into(),
            apps: vec!["firefox.desktop".into()],
            mappings: vec![Mapping::new(pad, "Ctrl+T", "hold").unwrap()],
        });
        mappings::save_config(&path, &config).unwrap();
        let screens = presets(name(b"Live", vec![Enter])); // Save Program Preset
        assert!(
            screens.contains("Save Program Preset (Program 2)"),
            "{screens}"
        );
        assert!(dir.join("presets/Live.program-preset").exists());
        setup("F4", "F3");
        let screens = presets(vec![Enter, Enter, Enter]); // Live -> Load it -> Back
        assert!(
            screens.contains("Loaded Live preset successfully"),
            "{screens}"
        );
        assert_eq!(keys_of(1).as_deref(), Some("F2"), "Program 2 comes back");
        assert_eq!(keys_of(0).as_deref(), Some("F4"), "Program 1 stays");
        assert!(mappings::load(&path).unwrap().contains(&y), "Xbox stays");
        let mut config = mappings::load_config(&path).unwrap();
        assert!(config.profile("Firefox").is_some(), "profiles stay");

        presets(name(b"All", vec![Down, Down, Enter])); // Save All Programs Preset
        assert!(dir.join("presets/All.preset").exists());
        config.profiles.clear();
        mappings::save_config(&path, &config).unwrap();
        setup("F5", "F6");
        let screens = presets(vec![Enter, Enter, Enter]); // All -> Load it -> Back
        assert!(
            screens.contains("Loaded All preset successfully"),
            "{screens}"
        );
        assert_eq!(
            (keys_of(0), keys_of(1)),
            (Some("F4".into()), Some("F2".into()))
        );
        assert!(
            mappings::load(&path).unwrap().contains(&y),
            "Xbox comes back"
        );
        assert!(
            mappings::load_config(&path)
                .unwrap()
                .profile("Firefox")
                .is_some(),
            "profiles come back"
        );
        assert!(screens.contains("All.preset (all programs)"), "{screens}");
        assert!(
            screens.contains("Live.program-preset (one program)"),
            "{screens}"
        );

        // A "program preset" holding two programs is refused whole.
        std::fs::write(dir.join("presets/Two.program-preset"), saved_text(&path)).unwrap();
        let before = config_bytes(&path);
        let screens = presets(vec![Down, Down, Enter, Enter, Enter]); // Two -> Load -> Back
        assert!(screens.contains("nothing loaded"), "{screens}");
        assert_eq!(config_bytes(&path), before);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 26: Claude's profile is shown for review and saved only when confirmed; a
    /// reply that fails the checks saves nothing.
    #[test]
    fn claude_profiles_are_reviewed_and_bad_replies_save_nothing() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-ai-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let pad = Control::from_note(10, 36).unwrap();
        // v7 ticket 104: a setup like the user's, whose first mappings are a knob and a lit
        // pad (neither may be a profile override), used to fail before Claude was asked.
        let knob = Control {
            channel: 1,
            id: 20,
            message: crate::Message::Cc,
            direction: 1,
        };
        let mut turn = Mapping::new(knob, "Right", "pulse").unwrap();
        turn.input = mappings::Input::RelativeKnob { step: 1 };
        let mut lit = Mapping::new(Control::from_note(10, 37).unwrap(), "Shift", "hold").unwrap();
        lit.feedback.octave = Some(crate::feedback::Octave::Offset(-1));
        mappings::save(
            &path,
            &[turn, lit, Mapping::new(pad, "F1", "hold").unwrap()],
        )
        .unwrap();
        let profile = mappings::Profile {
            name: "Firefox".into(),
            apps: vec!["firefox.desktop".into()],
            mappings: vec![Mapping::new(pad, "Ctrl+T", "hold").unwrap()],
        };
        let reply = format!(
            "Sure!\n```\n{}```\n",
            mappings::export_profile(&profile).unwrap()
        );
        let ask = |claude: String, confirm: Vec<Key>| {
            let mut keys = vec![Down; 9];
            keys.extend([Enter, Down, Down, Enter]); // App profiles -> Ask Claude
            keys.extend([Enter, Enter]); // the app, no wish
            keys.extend([Space, Enter]); // the Akai
            keys.extend(confirm);
            keys.extend([Escape, Escape]);
            let mut ui = Script {
                keys: keys.into(),
                claude,
                apps: vec![(
                    "Firefox".into(),
                    "/usr/share/applications/firefox.desktop".into(),
                )],
                ..Default::default()
            };
            settings_menu(&mut ui, &path).unwrap();
            assert!(ui.keys.is_empty());
            ui.screens
        };
        let before = config_bytes(&path);
        let screens = ask(reply.replace("Ctrl+T", "Ctrl+Nope"), vec![Enter]);
        assert!(
            screens
                .iter()
                .any(|s| s.contains("Claude's profile:") && s.contains("nothing saved"))
        );
        assert_eq!(config_bytes(&path), before);
        let screens = ask(reply.clone(), vec![Enter]); // Cancel
        assert!(
            screens
                .iter()
                .any(|s| s.starts_with("Claude suggests profile Firefox"))
        );
        assert_eq!(config_bytes(&path), before);
        // v7.7 ticket 147: a terminal command from Claude is refused by name; nothing saved.
        let mut command = profile.clone();
        command.mappings = vec![
            Mapping::new_action(
                pad,
                mappings::Input::Pad,
                crate::actions::Action::parse("command:dev:/tmp:sudo dnf update").unwrap(),
            )
            .unwrap(),
        ];
        command.mappings[0].label = "Bank A Pad 1".into();
        let sudo = format!("```\n{}```\n", mappings::export_profile(&command).unwrap());
        let screens = ask(sudo, vec![Enter]);
        assert!(
            screens.iter().any(|s| s
                .contains("refused: Bank A Pad 1 would run a terminal command")
                && s.contains("nothing saved")),
            "{screens:?}"
        );
        assert_eq!(config_bytes(&path), before);
        ask(reply, vec![Down, Enter]); // Save this profile
        assert_eq!(mappings::load_config(&path).unwrap().profiles, [profile]);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 141: the devices are asked first (one or both), the request names every
    /// control of each, the review is grouped by device and restated in plain words, and a
    /// reply with a control the devices lack saves nothing.
    #[test]
    fn claude_profiles_ask_for_devices_and_name_every_control() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-ai-dev-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let pad = Control::from_note(10, 36).unwrap();
        let profile = mappings::Profile {
            name: "Both".into(),
            apps: vec!["firefox.desktop".into()],
            mappings: vec![
                Mapping::new(pad, "Ctrl+T", "hold").unwrap(),
                Mapping::new(Control::button(0), "Ctrl+T", "hold").unwrap(),
            ],
        };
        let reply = format!("```\n{}```\n", mappings::export_profile(&profile).unwrap());
        let run = |claude: String, devices: Vec<Key>, then: Vec<Key>| {
            let mut keys = vec![Down; 9];
            keys.extend([Enter, Down, Down, Enter]); // App profiles -> Ask Claude
            keys.extend([Enter, Enter]); // the app, no wish
            keys.extend(devices);
            keys.extend(then);
            keys.extend([Escape, Escape]);
            let mut ui = Script {
                keys: keys.into(),
                claude,
                apps: vec![(
                    "Firefox".into(),
                    "/usr/share/applications/firefox.desktop".into(),
                )],
                ..Default::default()
            };
            settings_menu(&mut ui, &path).unwrap();
            assert!(ui.keys.is_empty());
            (ui.screens, ui.asked)
        };
        // Enter with nothing picked stays on the chooser; Esc cancels without asking Claude.
        let (screens, asked) = run(reply.clone(), vec![Enter, Escape], vec![]);
        assert!(screens.iter().any(|s| s.starts_with("Which devices")));
        assert!(asked.is_empty());
        // Both devices: every control of each, by name, in the one request.
        let (screens, asked) = run(reply.clone(), vec![Space, Down, Space, Enter], vec![Enter]);
        assert!(asked[0].contains("Akai MPK mini 3 and Xbox controller"));
        assert!(asked[0].contains("- Bank A Pad 1: ") && asked[0].contains("- Xbox A: "));
        let review = screens
            .iter()
            .find(|s| s.starts_with("Claude suggests profile Both"))
            .unwrap();
        assert!(
            review.contains("Akai MPK mini 3:\n  Bank A Pad 1: Ctrl+T"),
            "{review}"
        );
        assert!(
            review.contains("Xbox controller:\n  Xbox A: Ctrl+T"),
            "{review}"
        );
        assert!(
            review.contains("Xbox A on the Xbox controller presses Ctrl+T in firefox.desktop."),
            "{review}"
        );
        assert!(!review.to_lowercase().contains("note 1"), "{review}");
        // Only the Akai asked for: an Xbox override in the reply is refused, nothing saved.
        let (screens, _) = run(reply, vec![Space, Enter], vec![Enter]);
        assert!(screens.iter().any(|s| s.contains("Claude's profile: override 2: Xbox A isn't a control of the chosen devices; nothing saved")));
        assert!(mappings::load_config(&path).unwrap().profiles.is_empty());
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn menus_save_both_banks_cancel_edit_remove_and_preserve_failed_save() {
        use Key::*;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-menu-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let a = Control::from_note(10, 36).unwrap();
        let b = Control::from_note(10, 44).unwrap();
        let mut keys = Vec::new();
        for (which, save_choice) in [(1, 0), (0, 0)] {
            keys.extend([Enter, Enter, Enter, Enter]); // learn, family, shortcut, modifiers
            keys.extend(std::iter::repeat_n(Down, which));
            keys.extend([Space, Enter]);
            keys.extend(std::iter::repeat_n(Down, 7));
            keys.extend([Enter, Enter, Enter, Enter]); // done, hold, no feedback, fire when pressed
            keys.extend(std::iter::repeat_n(Down, save_choice));
            keys.push(Enter);
        }
        keys.extend([Tab, Enter, Enter, Escape]); // cancel edit after inspecting A
        keys.extend([Tab, Down, Enter, Down, Enter, Down, Enter]); // remove B explicitly
        keys.extend([Tab, Tab, Enter]); // finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [a, b].into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        assert!(
            ui.screens
                .iter()
                .any(|s| s.contains("Note ch10 #44 (Program 1 unverified)") && s.contains("Ctrl"))
        );
        assert_eq!(current, mappings::load(&path).unwrap());
        assert_eq!(current.len(), 1);
        assert_eq!(current[0].keys, ["Shift"]);
        block_saves(&path);
        let previous = current.clone();
        assert!(commit(&path, &mut current, a, 0, None, None).is_err());
        assert_eq!(current, previous);
        assert_eq!(mappings::load(&path).unwrap(), previous);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// Ticket 01: each family the menu offers must save for that control, and every failure names its stage.
    #[test]
    fn knob_piano_and_joystick_configuration_save_and_failures_name_their_stage() {
        use Key::*;
        use mappings::Input;
        let dir = std::env::temp_dir().join(format!("vibeconsole-controls-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let knob = Control {
            message: crate::Message::Cc,
            channel: 1,
            id: 70,
            direction: 1,
        };
        let joystick = Control {
            message: crate::Message::Bend,
            channel: 1,
            id: 0,
            direction: 1,
        };
        let stick = Input::Joystick {
            center: 8192,
            min: 0,
            max: 16383,
            deadzone: 1024,
            hysteresis: 128,
        };
        let shortcut_ctrl = [
            Enter, Enter, Space, Enter, Down, Down, Down, Down, Down, Down, Down, Enter,
        ];
        let mut keys = vec![Down, Down, Down, Enter]; // learn joystick
        keys.extend([Enter]); // its only family: keyboard shortcut
        keys.extend(shortcut_ctrl);
        keys.extend([Enter]); // review: save and configure another
        keys.extend([Down, Down, Enter, Down, Enter, Enter, Enter, Enter, Enter]); // knob -> system -> volume up, step, knob step, save
        keys.extend([Down, Enter, Enter]); // piano -> keyboard shortcut
        keys.extend(shortcut_ctrl);
        keys.extend([Enter, Enter, Enter]); // hold, fire when pressed, save
        keys.push(Escape);
        let mut ui = Script {
            keys: keys.into(),
            pads: [Control::note(1, 60).unwrap()].into(),
            motions: [
                (joystick, stick, "Joystick Right".into()),
                (knob, Input::Knob { step: 4 }, "Knob 1 increase".into()),
            ]
            .into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        let menus = ui
            .screens
            .iter()
            .filter(|s| s.starts_with("Action family\n") && s.contains("> Keyboard shortcut"))
            .collect::<Vec<_>>();
        assert_eq!(menus.len(), 3);
        assert!(!menus[0].contains("Launch") && !menus[0].contains("Prompt")); // joystick
        assert!(menus[1].contains("Music & Sound") && !menus[1].contains("Prompt")); // knob
        assert!(menus[1].contains("Choice knob") && menus[1].contains("Value knob"));
        assert!(menus[2].contains("Prompt") && !menus[2].contains("Choice knob")); // piano
        assert_eq!(current, mappings::load(&path).unwrap());
        assert_eq!(current.len(), 3);
        assert!(
            current
                .iter()
                .any(|m| m.input == stick && m.keys == ["Ctrl"])
        );
        assert!(
            current
                .iter()
                .any(|m| m.action == crate::actions::Action::Volume { up: true, step: 5 })
        );
        assert!(
            current
                .iter()
                .any(|m| m.input == Input::Piano && m.keys == ["Ctrl"])
        );
        // Shortcuts and audio steps have no observable state: no status option (ticket 10).
        assert!(!ui.screens.iter().any(|s| s.starts_with("Status feedback")));

        // Failures name their stage and leave the file byte-for-byte unchanged.
        let before = config_bytes(&path);
        let mut ui = Script {
            keys: [Down, Down, Enter].into(),
            ..Default::default()
        };
        let error = configure(&mut ui, &path, &mut current)
            .unwrap_err()
            .to_string();
        assert!(error.starts_with("controller I/O: "), "{error}");
        let mut config = mappings::load_config(&path).unwrap();
        config.idle.arp = Some(true);
        config.mappings.retain(|m| m.input != Input::Piano);
        mappings::save_config(&path, &config).unwrap();
        current = config.mappings.clone();
        let before_piano = config_bytes(&path);
        let mut ui = Script {
            keys: [Down, Enter, Enter, Escape].into(), // learn piano -> Back -> leave
            pads: [Control::note(1, 62).unwrap()].into(),
            ..Default::default()
        };
        configure(&mut ui, &path, &mut current).unwrap(); // a note, not a failure that pauses
        assert!(
            ui.screens
                .iter()
                .any(|s| s.starts_with("Not saved: validation: piano keys")
                    && s.contains("feedback comes from the idle settings"))
        );
        assert!(!ui.screens.iter().any(|s| s.starts_with("Action family"))); // refused before any choice
        assert_eq!(config_bytes(&path), before_piano);
        block_saves(&path);
        let mut ui = Script {
            keys: [Down, Down, Enter, Down, Enter, Enter, Enter, Enter, Enter].into(),
            motions: [(
                Control { id: 71, ..knob },
                Input::Knob { step: 4 },
                "Knob 2 increase".into(),
            )]
            .into(),
            ..Default::default()
        };
        let error = configure(&mut ui, &path, &mut current)
            .unwrap_err()
            .to_string();
        assert!(error.starts_with("file I/O: "), "{error}");
        assert_eq!(config_bytes(&path), before_piano);
        assert_ne!(before, before_piano);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// A thumbstick sweep wobbles the other axis a little; the dominant axis is learned, not refused.
    #[test]
    fn joystick_calibration_keeps_the_dominant_axis_and_refuses_two_real_sources() {
        use Key::*;
        let sweep = vec![
            [0xe0, 0, 64],
            [0xb0, 1, 3],
            [0xe0, 127, 127],
            [0xb0, 1, 0],
            [0xe0, 0, 0],
            [0xe0, 0, 64],
        ];
        let mut ui = Script {
            keys: [Down, Enter, Enter, Enter, Enter, Down, Enter].into(),
            ..Default::default()
        };
        let (control, input, label) = calibrate_motion(&mut ui, sweep, false).unwrap().unwrap();
        assert_eq!(control.message, crate::Message::Bend);
        assert!(matches!(
            input,
            mappings::Input::Joystick { center: 8192, .. }
        ));
        assert_eq!(label, "Joystick Right");
        let both = vec![[0xe0, 0, 0], [0xe0, 127, 127], [0xb0, 1, 0], [0xb0, 1, 127]];
        let error = calibrate_motion(&mut Script::default(), both, false).unwrap_err();
        assert!(error.to_string().contains("multiple sources"));
    }

    /// Ticket 05: learning an assigned pad shows its mapping; only Replace changes anything.
    #[test]
    fn learning_an_assigned_pad_warns_and_cancel_changes_nothing() {
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-replace-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let a = Control::from_note(10, 36).unwrap();
        let mut current = vec![Mapping::new(a, "Shift", "hold").unwrap()];
        mappings::save(&path, &current).unwrap();
        let before = config_bytes(&path);
        let mut ui = Script {
            keys: [Enter, Enter, Escape].into(), // learn A -> Cancel (default) -> leave
            pads: [a].into(),
            ..Default::default()
        };
        configure(&mut ui, &path, &mut current).unwrap();
        let warning = ui
            .screens
            .iter()
            .find(|s| s.starts_with("Already assigned:"))
            .expect("warning shown");
        assert!(warning.contains("Shift") && warning.contains("> Cancel"));
        assert!(!ui.screens.iter().any(|s| s.starts_with("Action family")));
        assert_eq!(config_bytes(&path), before);
        assert_eq!(current[0].keys, ["Shift"]);
        // Replace: Down to Replace, then shortcut Ctrl, hold, no feedback, pressed, save and finish.
        // The key picker starts with saved Shift selected: add Ctrl, drop Shift.
        let mut keys = vec![
            Enter, Down, Enter, Enter, Enter, Enter, Space, Down, Space, Enter,
        ];
        keys.extend(std::iter::repeat_n(Down, 7));
        keys.extend([Enter, Enter, Enter, Enter, Down, Enter]);
        ui.keys = keys.into();
        ui.pads = [a].into();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        assert_eq!(mappings::load(&path).unwrap()[0].keys, ["Ctrl"]);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// Ticket 02: a pad prompt and a sequence prompt step both save and reload unchanged.
    #[test]
    fn pad_prompt_and_sequence_prompt_step_save() {
        use crate::actions::{Action, Step, Target};
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-prompts-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let (a, b) = (
            Control::from_note(10, 36).unwrap(),
            Control::from_note(10, 37).unwrap(),
        );
        let new_prompt = |name: &[u8]| {
            let mut keys = vec![Enter]; // "New prompt" (the only file entry)
            keys.extend(name.iter().map(|c| Character(*c)));
            keys.extend([Enter, Enter, Enter]); // name, target claude, paste only
            keys
        };
        let mut keys = vec![Enter, Down, Down, Down, Enter]; // learn A -> Prompt
        keys.extend(new_prompt(b"review"));
        keys.extend([Enter, Down, Enter, Enter]); // fire when pressed, status On, save (Script labels the pad itself)
        keys.extend([Enter, Down, Down, Down, Down, Down, Enter]); // learn B -> sequence
        keys.extend([Enter, Down, Enter]); // add step -> prompt
        keys.extend([Enter, Enter, Enter, Enter]); // review, use existing, claude, paste only
        keys.extend([Down, Down, Enter, Enter]); // done, all at once (v7.8 ticket 17)
        keys.extend([Enter, Enter, Down, Enter]); // fire when pressed, status Off, save and finish
        let mut ui = Script {
            keys: keys.into(),
            pads: [a, b].into(),
            ..Default::default()
        };
        let mut current = Vec::new();
        configure(&mut ui, &path, &mut current).unwrap();
        assert!(ui.keys.is_empty());
        let prompt = Action::Prompt {
            file: "review".into(),
            target: Target::Agent("claude".into()),
            enter: false,
        };
        assert_eq!(current, mappings::load(&path).unwrap());
        assert_eq!(current[0].action, prompt);
        assert!(current[0].status && !current[1].status);
        assert_eq!(current[1].action, Action::Sequence(vec![Step::Do(prompt)]));
        assert_eq!(
            std::fs::read_to_string(dir.join("prompts/review")).unwrap(),
            "Review this change.\n"
        );
        // v7.7 ticket 243: with claude removed from this temporary config, pad A's prompt
        // is marked; the mark comes from this config, never from yours.
        let saved = mappings::load_config(&path).unwrap();
        let mut gone = saved.clone();
        gone.agents.retain(|agent| agent.name != "claude");
        mappings::save_config(&path, &gone).unwrap();
        let screens = ui.screens.len();
        ui.keys = [Enter, Escape, Escape, Escape, Escape, Escape].into();
        ui.pads = [a].into();
        let _ = configure(&mut ui, &path, &mut current);
        assert!(
            ui.screens[screens..]
                .iter()
                .any(|s| s.contains("[INVALID: agent removed]")),
            "{:?}",
            &ui.screens[screens..]
        );
        mappings::save_config(&path, &saved).unwrap();
        let before = config_bytes(&path);
        block_saves(&path);
        ui.keys = [
            Enter, Down, Down, Down, Enter, Enter, Enter, Enter, Enter, Enter, Enter, Enter,
        ]
        .into();
        ui.pads = [Control::from_note(10, 38).unwrap()].into();
        let error = configure(&mut ui, &path, &mut current)
            .unwrap_err()
            .to_string();
        assert!(error.starts_with("file I/O: "), "{error}");
        assert_eq!(config_bytes(&path), before);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 43: with a verified Akai program, Xbox buttons saved in /configure fire
    /// without pausing: a shortcut (saved Y = Left, or the default A = Enter) passes the Akai
    /// lights, and a non-shortcut action (X = Output mute) runs. The session's sets come from
    /// the saved file, as at Run. An Akai pad the program's lights don't know still fails.
    #[test]
    fn xbox_buttons_fire_beside_a_verified_akai_program_without_pausing() {
        use crate::actions::Action;
        use crate::feedback::{Octave, Resolver, Settings, State};
        let dir = std::env::temp_dir().join(format!("vibeconsole-xbox-run-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let pad = Control::from_note(10, 36).unwrap();
        let mut lit = Mapping::new(pad, "F1", "hold").unwrap();
        lit.feedback.octave = Some(Octave::Offset(1));
        let y = Mapping::new(Control::button(3), "Left", "hold").unwrap();
        let x = Mapping::new_action(Control::button(2), mappings::Input::Pad, Action::OutputMute)
            .unwrap();
        mappings::save(&path, &[lit, y.clone(), x.clone()]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        let (sent, ran) = std::sync::mpsc::channel();
        ui.actions = crate::actions::Dispatcher::with(move |action, _, _| {
            sent.send(action.clone()).unwrap();
            Ok("done".into())
        });
        let saved = mappings::load_config(&path).unwrap().mappings;
        ui.run_mappings = ui.context_mappings(&saved); // the Akai program's set, as at Run
        let baseline = State {
            octave: 0,
            tempo: 120,
            arp: false,
        };
        ui.resolver = Some(Resolver::new(&ui.run_mappings, baseline, Settings::default()).unwrap());
        for button in [y.control, Control::button(0)] {
            ui.transition(button, true).unwrap();
            ui.transition(button, false).unwrap();
        }
        ui.transition(x.control, true).unwrap();
        assert_eq!(
            ran.recv_timeout(Duration::from_secs(2)).unwrap(),
            Action::OutputMute
        );
        ui.transition(pad, true).unwrap(); // the Akai pad's own light still works
        let stranger = Control::from_note(10, 37).unwrap();
        assert!(ui.transition(stranger, true).is_err());
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 88: a prompt sequence sends steps 1, 2, 3 once each, then a tap sends
    /// nothing and says so; letting go early or a pause cancels the start-over hold; a
    /// one-second hold starts it over without sending, and the next tap sends step 1.
    #[test]
    fn finished_sequence_waits_for_a_one_second_hold() {
        use crate::actions::{Action, Target};
        let dir = std::env::temp_dir().join(format!("vibeconsole-seq-end-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        let prompt = |file: &str| Action::Prompt {
            file: file.into(),
            target: Target::Agent("claude".into()),
            enter: true,
        };
        // Ticket 81: step 2 was edited for this sequence; its own text is what gets sent.
        let own = Action::PromptOwn {
            file: "build".into(),
            target: Target::Agent("claude".into()),
            enter: true,
            text: "Build only the parser.\n".into(),
        };
        let steps = vec![prompt("plan"), own, prompt("review")];
        let button = Control::button(1);
        let seq = Mapping::new_action(
            button,
            mappings::Input::Pad,
            Action::PromptSequence(steps.clone()),
        )
        .unwrap();
        mappings::save(&path, &[seq]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        let (sent, ran) = std::sync::mpsc::channel();
        ui.actions = crate::actions::Dispatcher::with(move |action, _, _| {
            sent.send(action.clone()).unwrap();
            Ok("done".into())
        });
        ui.run_mappings = ui.context_mappings(&mappings::load_config(&path).unwrap().mappings);
        let tap = |ui: &mut Terminal| {
            ui.transition(button, true).unwrap();
            ui.transition(button, false).unwrap();
        };
        let nothing = |ran: &std::sync::mpsc::Receiver<Action>| {
            assert!(
                ran.recv_timeout(Duration::from_millis(200)).is_err(),
                "nothing sent"
            );
        };
        for step in &steps {
            tap(&mut ui);
            assert_eq!(&ran.recv_timeout(Duration::from_secs(2)).unwrap(), step);
        }
        tap(&mut ui);
        nothing(&ran);
        assert!(
            ui.notice
                .ends_with("sequence finished · hold 1 s to start over"),
            "{}",
            ui.notice
        );
        // That tap let go early: its hold is cancelled, even once a second has passed.
        std::thread::sleep(Duration::from_millis(1100));
        ui.quit_holds();
        tap(&mut ui);
        nothing(&ran);
        // A pause (it releases everything) cancels a hold in progress.
        ui.transition(button, true).unwrap();
        ui.release_all().unwrap();
        std::thread::sleep(Duration::from_millis(1100));
        ui.quit_holds();
        ui.transition(button, false).unwrap();
        tap(&mut ui);
        nothing(&ran);
        // A full hold starts it over and sends nothing; the next tap sends step 1.
        ui.transition(button, true).unwrap();
        std::thread::sleep(Duration::from_millis(1100));
        ui.quit_holds();
        ui.transition(button, false).unwrap();
        nothing(&ran);
        assert!(
            ui.notice.ends_with("sequence starts over at step 1"),
            "{}",
            ui.notice
        );
        tap(&mut ui);
        assert_eq!(ran.recv_timeout(Duration::from_secs(2)).unwrap(), steps[0]);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 51: with a verified Akai program, pressing Xbox shortcuts (a saved Y = Left
    /// and the default A = Enter) through the session's event path types the keys, keeps the
    /// session running with no error, and leaves every key released. The keyboard records its
    /// keys instead of reaching the desktop.
    /// v7 ticket 113: while output runs, the keyboard LED shows an agent needing input (by its
    /// pattern); paused, it goes back to what it showed. A stand-in LED records the writes.
    #[test]
    fn the_keyboard_led_follows_agents_and_goes_back_on_pause() {
        let dir = std::env::temp_dir().join(format!("vibeconsole-lock-led-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        let writes = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let seen = writes.clone();
        ui.lock_lights = Some(crate::keyboard::LockLights::with(vec![
            crate::keyboard::Led::new(
                "test keyboard",
                false,
                Box::new(move |on| {
                    seen.lock().unwrap().push(on);
                    Ok(())
                }),
            ),
        ]));
        let mut patterns = crate::status::DevicePatterns::default();
        patterns.keyboard_on = true;
        patterns.keyboard[1] = crate::status::Light::Steady; // needs input
        ui.device_lights = Some(patterns);
        ui.agent_states = vec![("claude".into(), "claude".into(), "needs-input")];
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.show_lock_light();
        assert_eq!(*writes.lock().unwrap(), [true], "lit for needs input");
        ui.suspend().unwrap();
        assert_eq!(
            *writes.lock().unwrap(),
            [true, false],
            "paused: back to what it showed"
        );
        ui.show_lock_light();
        assert_eq!(writes.lock().unwrap().len(), 2, "nothing more while paused");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7 ticket 128: while output runs, the Razer RGB (fake OpenRazer files) shows the most
    /// urgent agent state's effect; idle or paused, the resting effect and the old brightness
    /// go back; quitting restores it too.
    #[test]
    fn keyboard_rgb_follows_agents_and_rests_on_idle_pause_and_quit() {
        use crate::status::Rgb;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-rgb-session-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let kbd = dir.join("razerkbd/0003:1532:021A.0001");
        std::fs::create_dir_all(&kbd).unwrap();
        std::fs::write(kbd.join("matrix_brightness"), "200\n").unwrap();
        for f in ["none", "spectrum", "wave", "static", "breath", "reactive"] {
            std::fs::write(kbd.join(format!("matrix_effect_{f}")), "").unwrap();
        }
        let read = |f: &str| std::fs::read(kbd.join(f)).unwrap();
        let clear = || {
            for f in [
                "matrix_effect_static",
                "matrix_effect_spectrum",
                "matrix_effect_breath",
            ] {
                std::fs::write(kbd.join(f), "").unwrap();
            }
        };
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        ui.rgb = Some(
            crate::keyboard::RgbKeyboards::open(&dir.join("razerkbd"), Rgb::SPECTRUM).unwrap(),
        );
        let mut patterns = crate::status::DevicePatterns::default();
        patterns.rgb_devices[0].on = true;
        patterns.rgb_brightness = [120; 4];
        patterns.rgb_in_step = false; // each device's firmware breath (ticket 212)
        ui.device_lights = Some(patterns);
        ui.agent_states = vec![("claude".into(), "claude".into(), "needs-input")];
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.show_rgb();
        assert_eq!(
            read("matrix_effect_static"),
            [255, 128, 0],
            "needs input: orange"
        );
        assert_eq!(read("matrix_brightness"), b"120");
        ui.agent_states[0].2 = "idle";
        ui.show_rgb();
        assert_eq!(
            read("matrix_effect_spectrum"),
            b"1",
            "idle: the resting effect"
        );
        assert_eq!(
            read("matrix_brightness"),
            b"200",
            "idle: the brightness from before"
        );
        clear();
        ui.agent_states[0].2 = "thinking";
        ui.show_rgb();
        assert_eq!(
            read("matrix_effect_breath"),
            [0, 0, 255],
            "thinking: breathing blue"
        );
        ui.suspend().unwrap();
        assert_eq!(
            read("matrix_effect_spectrum"),
            b"1",
            "paused: the resting effect"
        );
        clear();
        ui.show_rgb();
        assert!(
            read("matrix_effect_breath").is_empty(),
            "nothing while paused"
        );
        ui.suspended = false;
        ui.show_rgb();
        assert_eq!(read("matrix_effect_breath"), [0, 0, 255]);
        clear();
        drop(ui);
        assert_eq!(
            read("matrix_effect_spectrum"),
            b"1",
            "quit: the resting effect"
        );
        assert_eq!(read("matrix_brightness"), b"200");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 209: each state shows at its own brightness (fake OpenRazer files); with
    /// every agent and session idle, and on pause and quit, the keyboard's own comes back. The
    /// user's report: `agent-status claude idle` left 30 because an outside Claude Code
