        std::fs::write(kbd.join("matrix_brightness"), "90\n").unwrap();
        for f in ["none", "spectrum", "wave", "static", "breath", "reactive"] {
            std::fs::write(kbd.join(format!("matrix_effect_{f}")), "").unwrap();
        }
