    /// v7.7 ticket 189: while running, the speakers (fake `razeraccessory` files) show the
    /// most urgent state's own effect and, idle, their resting effect; an effect they lack is
    /// named, not written; the switched-off mousepad gets nothing; brightness is never
    /// written; pause writes nothing more once resting.
    #[test]
    fn accessory_rgb_follows_agents_names_what_it_lacks_and_rests() {
        use crate::status::Rgb;
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-acc-session-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let device = |id: &str, name: &str, effects: &[&str]| {
            let d = dir.join(id);
            std::fs::create_dir_all(&d).unwrap();
            std::fs::write(d.join("device_type"), format!("{name}\n")).unwrap();
            std::fs::write(d.join("matrix_brightness"), "0\n").unwrap();
            for f in effects {
                std::fs::write(d.join(format!("matrix_effect_{f}")), "").unwrap();
            }
            d
        };
        let nommo = device(
            "0003:1532:0517.000B",
            "Razer Nommo Chroma",
            &["none", "spectrum", "wave", "static", "breath"],
        );
        let firefly = device(
            "0003:1532:0C04.0001",
            "Razer Firefly V2",
            &["none", "static"],
        );
        let read = |d: &Path, f: &str| std::fs::read(d.join(f)).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        ui.accessories[0] = Some(
            crate::keyboard::RgbKeyboards::open_accessory(
                &dir,
                Rgb::SPECTRUM,
                "Speakers RGB",
                "Nommo",
            )
            .unwrap(),
        );
        let mut patterns = crate::status::DevicePatterns::default();
        patterns.rgb_devices[1].on = true;
        let mut own = patterns.rgb_shared;
        own.rest = Rgb::Static([255, 255, 255]);
        own.states[2] = Rgb::Reactive([255, 0, 0], None);
        patterns.rgb_devices[1].own = Some(own);
        ui.device_lights = Some(patterns);
        ui.agent_states = vec![("claude".into(), "claude".into(), "needs-input")];
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.show_rgb();
        assert_eq!(
            read(&nommo, "matrix_effect_static"),
            [255, 128, 0],
            "needs input: orange"
        );
        assert!(
            read(&firefly, "matrix_effect_static").is_empty(),
            "mousepad switched off"
        );
        ui.agent_states[0].2 = "thinking";
        ui.show_rgb();
        assert!(
            ui.notice
                .contains("Reactive · Red unavailable on Razer Nommo Chroma"),
            "{}",
            ui.notice
        );
        assert!(!nommo.join("matrix_effect_reactive").exists());
        ui.agent_states[0].2 = "idle";
        ui.show_rgb();
        assert_eq!(
            read(&nommo, "matrix_effect_static"),
            [255, 255, 255],
            "idle: resting"
        );
        std::fs::write(nommo.join("matrix_effect_static"), "").unwrap();
        ui.suspend().unwrap();
        assert!(
            read(&nommo, "matrix_effect_static").is_empty(),
            "paused: already resting"
        );
        assert_eq!(
            read(&nommo, "matrix_brightness"),
            b"0\n",
            "brightness never written"
        );
        drop(ui);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 190: while running, the G502 logo (a fake logirgb) previews the most
    /// urgent state's effect once; a wave it can't show is named, not sent; idle puts the
    /// mouse's stored effect back; pause sends nothing more; with the switch off and no
    /// mouse open, nothing runs (tests never start the real logirgb).
    #[test]
    fn g502_logo_follows_agents_and_puts_the_stored_effect_back() {
        use crate::status::Rgb;
        use std::sync::{Arc, Mutex};
        let dir = std::env::temp_dir().join(format!("vibeconsole-g502-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let calls = Arc::new(Mutex::new(Vec::<String>::new()));
        let run = fake_logirgb(&calls, Duration::ZERO);
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        let mut patterns = crate::status::DevicePatterns::default();
        ui.device_lights = Some(patterns.clone());
        ui.agent_states = vec![("claude".into(), "claude".into(), "needs-input")];
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.show_rgb();
        assert!(ui.mouse.is_none(), "switched off: nothing opened");
        ui.mouse = Some(crate::keyboard::MouseWorker::start(run));
        patterns.rgb_devices[3].on = true;
        let mut own = patterns.rgb_shared;
        own.states[2] = Rgb::Wave(None);
        patterns.rgb_devices[3].own = Some(own);
        ui.device_lights = Some(patterns);
        ui.show_rgb();
        until(|| calls.lock().unwrap().len() == 2);
        ui.show_rgb();
        ui.agent_states[0].2 = "thinking";
        until(|| {
            ui.show_rgb();
            ui.notice.contains("Wave unavailable on the G502 logo")
        });
        ui.agent_states[0].2 = "idle";
        ui.show_rgb();
        until(|| calls.lock().unwrap().len() == 5);
        ui.suspend().unwrap();
        drop(ui);
        assert_eq!(
            *calls.lock().unwrap(),
            [
                "logirgb profiles -d g502",
                "logirgb set -d g502 -z 1 static --color #ff8000 --preview",
                "logirgb profiles -d g502",
                "logirgb list",
                "logirgb set -d g502 -z 1 static --color #8000ff --preview",
            ]
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 205: Live opens with the cursor on the most urgent agent, else on
    /// Release all, never on Pause: a stray Enter goes to the agent or releases held keys
    /// while output keeps running; Pause is a few rows up, and Enter there pauses.
    #[test]
    fn live_opens_off_pause_so_a_stray_enter_never_pauses() {
        let enter_then = |ui: &mut Terminal, more: &[Key]| {
            let mut steps = vec![Step::Key(Key::Enter)];
            steps.extend(more.iter().map(|k| Step::Key(*k)));
            ui.script = Some(Play {
                steps: steps.into(),
                ..Play::default()
            });
            let id = command_menu(ui).unwrap();
            (id, ui.script.take().unwrap())
        };
        // No agents: Enter is Release all, and the held Shift is let go.
        let (dir, mut ui, _ran, [.., shift]) = configure_session("live-start");
        ui.status_at = Instant::now() + Duration::from_secs(3600); // no agents appear
        ui.at_menu = true;
        ui.handle_events(vec![Event::Press(shift)]).unwrap();
        assert_eq!(shifts(&ui), 1);
        let (id, _) = enter_then(&mut ui, &[]);
        assert_eq!(id, Some(5), "Release all");
        ui.release_all().unwrap(); // what the session does with it
        let recorded = &ui.output.as_ref().unwrap().recorded;
        assert_eq!(
            recorded.last(),
            Some(&(evdev::KeyCode::KEY_LEFTSHIFT, false))
        );
        assert!(ui.wanted_run, "output keeps running");
        drop(ui);
        std::fs::remove_dir_all(dir).unwrap();

        // One agent: Enter goes to it; then up to Pause, and Enter pauses.
        let (dir, mut ui, _ran, _) = configure_session("live-start-agent");
        ui.status_at = Instant::now() + Duration::from_secs(3600); // keep the fake agent
        ui.agent_states = vec![("asker".into(), "w5".into(), "needs-input")];
        let folder = dir.to_string_lossy().into_owned();
        ui.agent_places = vec![(mappings::Host::Tmux, Some(folder))];
        ui.at_menu = true;
        let (id, play) = enter_then(&mut ui, &[Key::Escape]);
        assert_eq!(id, None);
        assert_eq!(play.ran, ["tmux select-window -t vibe:w5"]);
        assert!(ui.wanted_run, "output keeps running");
        // Up: View, Quit until next login, Quit, Release all, Pause.
        ui.script = Some(Play {
            steps: [Key::Up, Key::Up, Key::Up, Key::Up, Key::Up, Key::Enter]
                .map(Step::Key)
                .into(),
            ..Play::default()
        });
        assert_eq!(command_menu(&mut ui).unwrap(), Some(1), "❚❚ Pause");
        ui.pause("test").unwrap(); // what the session does with it while running
        assert!(!ui.wanted_run);
        drop(ui);
        std::fs::remove_dir_all(dir).unwrap();
    }

