    /// v7.7 ticket 257: Enter on a tmux agent with no tmux server says so plainly and asks,
    /// opening on Cancel; Cancel starts nothing; Start submits the agent's Ensure agent step
    /// to the (fake) dispatcher. No tmux or agent is started.
    #[test]
    fn going_to_an_agent_not_in_tmux_offers_to_start_it() {
        use crate::actions::Action;
        let (dir, mut ui, ran, _) = configure_session("agent-not-in-tmux");
        ui.status_at = Instant::now() + Duration::from_secs(3600); // keep the fake agent
        ui.agent_states = vec![("asker".into(), "w5".into(), "needs-input")];
        let folder = dir.to_string_lossy().into_owned();
        ui.agent_places = vec![(mappings::Host::Tmux, Some(folder))];
        ui.at_menu = true;
        let asked = "asker isn't running in tmux yet: start it?";
        let go = |ui: &mut Terminal, keys: &[Key]| {
            ui.script = Some(Play {
                steps: keys.iter().map(|k| Step::Key(*k)).collect(),
                tmux_down: true,
                ..Play::default()
            });
            assert_eq!(command_menu(ui).unwrap(), None);
            ui.script.take().unwrap()
        };
        // Enter on the agent, Enter on Cancel, Esc leaves Live.
        let play = go(&mut ui, &[Key::Enter, Key::Enter, Key::Escape]);
        let question = (play.screens.iter())
            .map(|s| plain_rows(s).join("\n"))
            .find(|s| s.contains(asked))
            .expect("the plain question shows");
        assert!(question.contains("> Cancel"), "opens on Cancel");
        assert!(!question.contains("error connecting"), "no raw tmux error");
        assert_eq!(
            play.ran,
            [
                "tmux select-window -t vibe:w5",
                "tmux list-windows -t =vibe -F #{window_name}"
            ]
        );
        assert!(ui.notice.contains("nothing started"), "{}", ui.notice);
        assert!(
            ran.recv_timeout(Duration::from_millis(300)).is_err(),
            "Cancel runs nothing"
        );
        ui.live_start = true;
        go(&mut ui, &[Key::Enter, Key::Down, Key::Enter, Key::Escape]);
        assert_eq!(
            ran.recv_timeout(Duration::from_secs(2)).unwrap(),
            Action::Sequence(vec![crate::actions::Step::Agent("asker".into())])
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 256: Quit until next login asks first, opening on Cancel; Cancel and Esc
    /// stay in the session with nothing asked of the login service; confirming quits and
    /// leaves it stopped. Plain Quit doesn't ask.
    #[test]
    fn quit_until_next_login_asks_first() {
        use Key::*;
        let title = "Quit and leave the login service stopped until you log in again?";
        for keys in [vec![Enter], vec![Escape]] {
            let mut ui = Script {
                keys: keys.into(),
                login: (true, true),
                ..Default::default()
            };
            assert!(
                !quit_command(&mut ui, true).unwrap(),
                "stays in the session"
            );
            assert!(ui.keys.is_empty());
            assert!(ui.screens.iter().any(|s| s.contains(title)));
            assert!(ui.screens.last().unwrap().contains("> Cancel"));
            assert!(ui.login_calls.is_empty() && ui.journal.is_empty());
        }
        let mut ui = Script {
            keys: [Down, Enter].into(),
            login: (true, true),
            ..Default::default()
        };
        assert!(quit_command(&mut ui, true).unwrap(), "quits");
        assert_eq!(ui.login, (true, false), "the service is left stopped");
        assert_eq!(
            ui.journal,
            ["Login service: left stopped: Quit until next login"]
        );
        let mut ui = Script {
            login: (true, false),
            ..Default::default()
        };
        assert!(quit_command(&mut ui, false).unwrap());
        assert!(ui.screens.is_empty(), "plain Quit doesn't ask");
        assert_eq!(ui.login, (true, true));
    }

    /// v7.7 ticket 255: each way Quit leaves the login service writes its own line with the
    /// reason, from the decision made and what the (fake) service answered.
    #[test]
    fn quit_says_what_it_did_about_the_login_service() {
        let quit = |login: (bool, bool), fails: bool, until_next_login: bool| {
            let mut ui = Script {
                login,
                login_fails: fails,
                ..Default::default()
            };
            let result = quit_login(&mut ui, until_next_login);
            assert_eq!(result.is_err(), fails);
            (ui.journal, ui.login.1)
        };
        let line = |why: &str| vec![format!("Login service: {why}")];
        assert_eq!(
            quit((true, false), false, false),
            (line("starting it again (Start at login is On)"), true)
        );
        assert_eq!(
            quit((false, true), false, false),
            (line("starting it again (this run paused it)"), true)
        );
        assert_eq!(
            quit((true, true), false, true),
            (line("left stopped: Quit until next login"), false)
        );
        assert_eq!(
            quit((false, false), false, false),
            (line("left stopped: Start at login is Off"), false)
        );
        assert_eq!(
            quit((true, false), true, false),
            (line("not started: systemctl --user enable failed"), false)
        );
    }

    /// v7.7 ticket 204: Enter on Live's ❚❚ Pause, a click on it, and Find's /pause each
    /// pause with their own cause, on screen and in the journal line; held keys go first.
    #[test]
    fn each_way_to_pause_shows_and_journals_its_cause() {
        let (dir, mut ui, _ran, [.., shift]) = configure_session("pause-cause");
        ui.status_at = Instant::now() + Duration::from_secs(3600); // no agents appear
        ui.context_verified = true;
        ui.at_menu = true;
        // Draw Live once to find the Pause button.
        ui.script = Some(Play {
            steps: [Key::Escape].map(Step::Key).into(),
            ..Play::default()
        });
        command_menu(&mut ui).unwrap();
        let rows = plain_rows(&ui.rendered);
        let (row, line) = (rows.iter().enumerate())
            .find(|(_, l)| l.contains("❚❚ Pause"))
            .unwrap();
        let column = line[..line.find("❚❚ Pause").unwrap()].chars().count() + 2;
        let click = Key::Click(column as u16, row as u16 + 1);
        let mut find = vec![Key::Character(b'/')];
        find.extend(typed("pause"));
        find.extend([Key::Enter, Key::Enter]);
        for (keys, cause) in [
            (vec![Key::Enter], "Enter on Live ❚❚ Pause"),
            (vec![click], "click on Live ❚❚ Pause"),
            (find, "/pause"),
        ] {
            ui.handle_events(vec![Event::Press(shift)]).unwrap();
            // Live as it reads now (❚❚ Pause again after a resume): what the click lands on.
            ui.script = Some(Play {
                steps: [Key::Escape].map(Step::Key).into(),
                ..Play::default()
            });
            command_menu(&mut ui).unwrap();
            ui.script = Some(Play {
                steps: keys.into_iter().map(Step::Key).collect(),
                ..Play::default()
            });
            ui.menu = 0; // ❚❚ Pause, Live's first row (the first Escape ended its start row)
            assert_eq!(command_menu(&mut ui).unwrap(), Some(1), "{cause}");
            // What the session does with it while running.
            let opened_by = std::mem::replace(&mut ui.opened_by, "Enter");
            ui.pause_by(opened_by).unwrap();
            let recorded = &ui.output.as_ref().unwrap().recorded;
            assert_eq!(
                (recorded.iter().rev()).find(|(k, _)| *k == evdev::KeyCode::KEY_LEFTSHIFT),
                Some(&(evdev::KeyCode::KEY_LEFTSHIFT, false)),
                "held keys released"
            );
            ui.notice.clear();
            ui.error.clear();
            assert_eq!(ui.run_state(), format!("paused: {cause}"));
            ui.draw("").unwrap();
            assert!(
                ui.rendered.contains(&format!("PAUSED ({cause})")),
                "{cause}"
            );
            let play = ui.script.take().unwrap();
            let logged = play.journal.last().unwrap();
            assert!(logged.contains(&format!("| PAUSED ({cause})")), "{logged}");
            resume(&mut ui);
            ui.handle_events(vec![Event::Release(shift, crate::ReleaseType::NoteOff)])
                .unwrap();
        }
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 204: a rejected action and a lost controller pause with the cause and
    /// the error that names its stage.
    #[test]
    fn a_rejected_action_and_a_lost_controller_name_their_stage() {
        let (dir, mut ui, _ran, [.., shift]) = configure_session("pause-stage");
        let pad = Control::from_note(10, 40).unwrap();
        let gone = Mapping::new_action(
            pad,
            mappings::Input::Pad,
            crate::actions::Action::SavedSequence("gone".into()),
        )
        .unwrap();
        ui.run_mappings.push(gone);
        let mut output = crate::keyboard::Output::recording(&ui.run_mappings).unwrap();
        output.keyboard.resume();
        ui.output = Some(output);
        ui.context_verified = true;
        ui.at_menu = true;
        ui.handle_events(vec![Event::Press(shift)]).unwrap();
        assert_eq!(shifts(&ui), 1);
        ui.handle_events(vec![Event::Press(pad)]).unwrap();
        assert!(!ui.wanted_run);
        let recorded = &ui.output.as_ref().unwrap().recorded;
        assert_eq!(
            (recorded.iter().rev()).find(|(k, _)| *k == evdev::KeyCode::KEY_LEFTSHIFT),
            Some(&(evdev::KeyCode::KEY_LEFTSHIFT, false)),
            "held keys released"
        );
        assert_eq!(
            ui.run_state(),
            "paused: action or feedback rejected · Action/feedback rejected: validation: saved sequence gone is gone; paused"
        );

        resume(&mut ui);
        ui.error.clear();
        // v7.7 ticket 265: a lost Akai program releases held keys but keeps the run: pads
        // wait for detection, and the Xbox may run on its own meanwhile.
        ui.handle_events(vec![Event::Press(shift)]).unwrap();
        ui.controller = Some(crate::feedback::Controller::fake_lost());
        for _ in 0..200 {
            ui.tick().unwrap();
            if ui.controller.is_none() {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(ui.controller.is_none());
        assert!(ui.wanted_run && !ui.context_verified);
        let recorded = &ui.output.as_ref().unwrap().recorded;
        assert_eq!(
            (recorded.iter().rev()).find(|(k, _)| *k == evdev::KeyCode::KEY_LEFTSHIFT),
            Some(&(evdev::KeyCode::KEY_LEFTSHIFT, false)),
            "held keys released"
        );
        let state = ui.run_state();
        assert!(
            state
                .starts_with("running (Program 1 unverified; detecting program; actions inactive)"),
            "{state}"
        );
        assert!(
            ui.error.contains("Snapshot rejected: device unplugged"),
            "{}",
            ui.error
        );
        ui.gamepad_only(true).unwrap();
        assert!(!ui.suspended, "the Xbox runs on its own while pads wait");

        // A pause the user chose stays a pause, with its own cause.
        ui.pause_by("key").unwrap();
        ui.controller = Some(crate::feedback::Controller::fake_lost());
        for _ in 0..200 {
            ui.tick().unwrap();
            if ui.controller.is_none() {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(!ui.wanted_run);
        assert!(
            ui.run_state().starts_with("paused: Enter on Live ❚❚ Pause"),
            "{}",
            ui.run_state()
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 208: with another app focused, a Shift-only hold (the user's Xbox RT,
    /// Wispr Flow's talk key) fires on Live, on 3 Agents and inside Status light patterns.
    /// The cause: inside a menu it was left out of the keyboard (ticket 112's rule for
    /// /configure in `with_gamepad`, which every Settings menu shares since ticket 144).
    #[test]
    fn a_shift_hold_fires_on_every_screen_while_another_app_is_focused() {
        let (dir, mut ui, _ran, [.., shift]) = configure_session("shift-everywhere");
        let path = dir.join("mappings.tsv");
        ui.context_verified = true;
        ui.at_menu = true;
        let mut steps = Vec::from(hold(shift)); // Live
        steps.push(Step::Key(Key::Character(b'3'))); // 3 Agents: not a transition
        steps.extend(hold(shift));
        steps.push(Step::Key(Key::Escape));
        ui.script = Some(Play {
            steps: steps.into(),
            focus: Some("Mozilla Firefox".into()),
            ..Play::default()
        });
        command_menu(&mut ui).unwrap();
        assert_eq!(shifts(&ui), 2, "Live and 3 Agents");
        // 3 Agents › Status light patterns, opened as the session opens a Settings row.
        ui.at_menu = false;
        let mut steps = vec![Step::Key(Key::Down)]; // a key read resumes output there
        steps.extend(hold(shift));
        steps.push(Step::Key(Key::Escape));
        ui.script = Some(Play {
            steps: steps.into(),
            focus: Some("Mozilla Firefox".into()),
            ..Play::default()
        });
        ui.menu_fires(false, |ui| light_patterns_menu(ui, &path))
            .unwrap();
        assert_eq!(shifts(&ui), 3, "inside Status light patterns");
        std::fs::remove_dir_all(dir).unwrap();
    }
    fn hold(control: Control) -> [Step; 2] {
        [
            Step::Events(vec![Event::Press(control)]),
            Step::Events(vec![Event::Release(control, crate::ReleaseType::NoteOff)]),
        ]
    }

    /// v7.7 ticket 208, with a fake focus source: VibeConsole's own terminal focused, a
    /// Shift-only hold sends nothing and a held Shift is released; another app focused, it
    /// sends again. Other mapped keys (Down) still type, so pads keep driving the menus. With
    /// no focus source, Shift fires on Live and stays silent in menus (ticket 112), and Live
    /// says own-terminal focus is unavailable.
    #[test]
    fn own_terminal_focus_holds_back_shift_alone_and_releases_it() {
        let (dir, mut ui, _ran, [_, down, _, shift]) = configure_session("own-focus");
        let path = dir.join("mappings.tsv");
        ui.context_verified = true;
        ui.at_menu = true;
        let own = ui.own_title.clone();
        let downs = |ui: &Terminal| {
            let recorded = &ui.output.as_ref().unwrap().recorded;
            (recorded.iter())
                .filter(|(k, d)| *k == evdev::KeyCode::KEY_DOWN && *d)
                .count()
        };
        let play = |ui: &mut Terminal, focus: Option<&str>, steps: Vec<Step>| {
            let mut steps = steps;
            steps.push(Step::Key(Key::Escape));
            ui.script = Some(Play {
                steps: steps.into(),
                focus: focus.map(String::from),
                ..Play::default()
            });
            command_menu(ui).unwrap();
            ui.script.take().unwrap().screens
        };
        // Shift held down while another app is focused, then VibeConsole's terminal is.
        play(
            &mut ui,
            Some("Mozilla Firefox"),
            vec![Step::Events(vec![Event::Press(shift)])],
        );
        assert_eq!(shifts(&ui), 1);
        play(&mut ui, Some(&own), vec![]);
        let recorded = &ui.output.as_ref().unwrap().recorded;
        assert_eq!(
            recorded.last(),
            Some(&(evdev::KeyCode::KEY_LEFTSHIFT, false)),
            "focusing VibeConsole released the held Shift"
        );
        // Focused on VibeConsole: Shift alone sends nothing; Down still types.
        let mut steps = Vec::from(hold(shift));
        steps.extend(hold(down));
        play(&mut ui, Some(&own), steps);
        assert_eq!(shifts(&ui), 1, "held back");
        assert!(downs(&ui) >= 1, "Down still drives VibeConsole's menus");
        // Another app again: it sends.
        play(&mut ui, Some("Mozilla Firefox"), Vec::from(hold(shift)));
        assert_eq!(shifts(&ui), 2);
        // No focus source: Live fires, a menu stays silent, and Live says why.
        play(&mut ui, None, Vec::from(hold(shift)));
        assert_eq!(shifts(&ui), 3, "Live, focus unknown");
        ui.read_view(None); // Live's controller map
        ui.script = Some(Play::default());
        let titles = (ui.live_panes(200, usize::MAX).into_iter())
            .map(|(title, _)| title)
            .collect::<Vec<_>>();
        ui.script = None;
        assert!(
            titles
                .iter()
                .any(|t| t.ends_with("own terminal focus: unavailable")),
            "Live says so: {titles:?}"
        );
        ui.at_menu = false;
        let mut steps = vec![Step::Key(Key::Down)];
        steps.extend(hold(shift));
        steps.push(Step::Key(Key::Escape));
        ui.script = Some(Play {
            steps: steps.into(),
            ..Play::default()
        });
        ui.menu_fires(false, |ui| light_patterns_menu(ui, &path))
            .unwrap();
        assert_eq!(shifts(&ui), 3, "a menu, focus unknown: ticket 112's rule");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 206: back from a submenu, a menu's cursor is on the row you opened: 3
    /// Agents › Status light patterns › Keyboard lights that show it, then Esc; after a
    /// change saved in a submenu (Thinking's tempo), on the changed row.
    #[test]
    fn back_from_a_submenu_lands_on_the_row_you_opened() {
        let (dir, mut ui, _ran, _) = configure_session("rows-left");
        let path = dir.join("mappings.tsv");
        let run = |ui: &mut Terminal, keys: Vec<Key>| {
            ui.script = Some(Play {
                steps: keys.into_iter().map(Step::Key).collect(),
                ..Play::default()
            });
            light_patterns_menu(ui, &path).unwrap();
            ui.script.take().unwrap().screens
        };
        let selected = |screen: &str| {
            (plain_rows(screen).into_iter())
                .find_map(|l| {
                    (l.trim_start_matches(['│', ' ']).strip_prefix("> ")).map(str::to_owned)
                })
                .unwrap_or_default()
        };
        // Down to row 17, open it, Esc back: the parent shows, then Esc leaves.
        let mut keys = vec![Key::Down; 18];
        keys.extend([Key::Enter, Key::Escape, Key::Escape]);
        let screens = run(&mut ui, keys);
        let back = selected(screens.last().unwrap());
        assert!(back.starts_with("Keyboard lights that show it"), "{back}");
        // Thinking (row 2): tempo one down, octave as it is: saved, and back on Thinking.
        let before = mappings::load_config(&path).unwrap().light_patterns.states[2];
        let mut keys = vec![Key::Up; 15]; // from row 17 back to row 2
        keys.extend([Key::Enter, Key::Down, Key::Enter, Key::Enter, Key::Escape]);
        let screens = run(&mut ui, keys);
        let after = mappings::load_config(&path).unwrap().light_patterns.states[2];
        assert_ne!(before.0, after.0, "the tempo was saved");
        let back = selected(screens.last().unwrap());
        assert!(back.starts_with("Thinking: tempo"), "{back}");
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 206: a menu reopens on the row last opened by its text; a row removed
    /// while you were away puts the cursor at the same place. Ticket 229: a question
    /// (`question`) never gets a remembered cursor, whatever its length; every other menu,
    /// a three-row one too, does; a risky "Yes …" question opens on its safe row.
    #[test]
    fn a_menu_reopens_by_text_else_at_the_same_place_and_a_question_never_does() {
        let (dir, mut ui, _ran, _) = configure_session("rows-left-list");
        let pick = |ui: &mut Terminal, title: &str, rows: &[&str], keys: Vec<Key>| {
            ui.script = Some(Play {
                steps: keys.into_iter().map(Step::Key).collect(),
                ..Play::default()
            });
            choose(ui, title, &strings(rows)).unwrap()
        };
        let five = ["a", "b", "c", "d", "e"];
        assert_eq!(
            pick(&mut ui, "Things (5)", &five, vec![Key::Up, Key::Enter]),
            Some(4)
        );
        // Same list, its count changed in the title: opens on "e".
        assert_eq!(
            pick(
                &mut ui,
                "Things (6)",
                &["z", "a", "b", "c", "d", "e"],
                vec![Key::Enter]
            ),
            Some(5)
        );
        // "e" removed: the same place, the nearest row left.
        assert_eq!(
            pick(&mut ui, "Things", &["a", "b", "c", "d"], vec![Key::Enter]),
            Some(3)
        );
        let ask = |ui: &mut Terminal, title: &str, rows: &[&str], keys: Vec<Key>| {
            ui.script = Some(Play {
                steps: keys.into_iter().map(Step::Key).collect(),
                ..Play::default()
            });
            question(ui, title, &strings(rows)).unwrap()
        };
        // A question: never remembered, at any length.
        let sure = ["Cancel", "Delete", "Delete all", "Delete and quit"];
        assert_eq!(
            ask(&mut ui, "Sure?", &sure, vec![Key::Up, Key::Enter]),
            Some(3)
        );
        assert_eq!(ask(&mut ui, "Sure?", &sure, vec![Key::Enter]), Some(0));
        // A risky "Yes" first: it opens on Back.
        let yes = ["Yes, switch", "Back (discard: nothing changes)"];
        assert_eq!(ask(&mut ui, "Switch?", &yes, vec![Key::Enter]), Some(1));
        // A three-row navigation menu remembers, whatever its words.
        let rows = ["Edit", "Remove", "Back"];
        assert_eq!(
            pick(&mut ui, "Item", &rows, vec![Key::Down, Key::Enter]),
            Some(1)
        );
        assert_eq!(pick(&mut ui, "Item", &rows, vec![Key::Enter]), Some(1));
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 229: every confirmation goes through `question`, none missed: no
    /// `choose`/`choose_at` call in this file (outside its tests) has options that start
    /// with a question's answer (Cancel, No, Keep, Yes, Retry, Install, Use, Save and …);
    /// and the old guess (a row count, risky words) is gone from the picker.
    #[test]
    fn every_confirmation_goes_through_question() {
        let source = include_str!("terminal.rs");
        let code = &source[..source.find("#[cfg(test)]\nmod tests").unwrap()];
        let answers = [
            "\"Cancel",
            "\"No",
            "\"Keep",
            "\"Yes",
            "&yes",
            "\"Retry",
            "\"Install (merge",
            "\"Use\"",
            "\"Save and configure another",
        ];
        let mut missed = Vec::new();
        let mut asked = 0;
        for (at, _) in code
            .match_indices("choose(")
            .chain(code.match_indices("choose_at("))
        {
            let call = &code[at..(at + 700).min(code.len())];
            let call = &call[..call.find(")?").unwrap_or(call.len())];
            if let Some(list) = call.find("strings(&[") {
                let first = call[list + 10..].trim_start();
                let rows = call[list..].matches(',').count();
                if rows >= 1 && answers.iter().any(|a| first.starts_with(a)) {
                    missed.push(code[..at].lines().count());
                }
            }
        }
        for (at, _) in code.match_indices("question(") {
            asked += usize::from(!code[..at].ends_with("fn "));
        }
        assert!(
            missed.is_empty(),
            "confirmations not through question, at lines {missed:?}"
        );
        assert!(asked >= 34, "{asked} questions");
        let pick = &code[code.find("\nfn pick(").unwrap()..];
        let pick = &pick[..pick.find("\n}\n").unwrap()];
        assert!(!pick.contains("options.len() >= 4") && !code.contains("fn destructive("));
    }

    /// v7.7 ticket 191: a fake logirgb that logs each call, takes `delay` per `set`, and
    /// answers as the G502 does (active profile 5, its stored logo static #8000ff).
    fn fake_logirgb(
        calls: &std::sync::Arc<std::sync::Mutex<Vec<String>>>,
        delay: Duration,
    ) -> impl FnMut() -> crate::gamepad::Runner + Send + 'static {
        let calls = calls.clone();
        move || {
            let log = calls.clone();
            Box::new(move |args: &[&str]| {
                if args[1] == "set" {
                    std::thread::sleep(delay);
                }
                log.lock().unwrap().push(args.join(" "));
                Ok(match args[1] {
                    "profiles" => "G502 HERO Gaming Mouse profiles: 1 on, 5 on (active)\n".into(),
                    "list" => {
                        "   zone 1 (logo): G logo\n     profile 5: static color=#8000ff\n".into()
                    }
                    _ => String::new(),
                })
            })
        }
    }
    /// The mouse worker acts on its own thread: wait up to 3 s for it.
    fn until(mut done: impl FnMut() -> bool) {
        for _ in 0..300 {
            if done() {
                return;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        panic!("the mouse worker never got there");
    }

    /// v7.7 ticket 192: a light switched on in Status light patterns that this run found
    /// unavailable (logirgb can't open the mouse) is a System problem named by its stage;
    /// switched off, it isn't.
    #[test]
    fn a_switched_on_unavailable_light_is_a_system_problem() {
        use std::sync::{Arc, Mutex};
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-light-problem-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let calls = Arc::new(Mutex::new(Vec::<String>::new()));
        let log = calls.clone();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        ui.mouse = Some(crate::keyboard::MouseWorker::start(move || {
            let log = log.clone();
            Box::new(move |args: &[&str]| {
                log.lock().unwrap().push(args.join(" "));
                Err("logirgb: No such file or directory (os error 2)".into())
            })
        }));
        let mut patterns = crate::status::DevicePatterns::default();
        patterns.rgb_devices[3].on = true;
        ui.device_lights = Some(patterns.clone());
        ui.agent_states = vec![("claude".into(), "claude".into(), "needs-input")];
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.show_rgb();
        until(|| ui.mouse.as_ref().unwrap().unavailable());
        let mouse =
            |ui: &Terminal| (ui.problems.iter()).any(|p| p.stage == "Mouse light (Logitech G502)");
        ui.read_problems();
        assert!(mouse(&ui), "{:?}", ui.problems);
        patterns.rgb_devices[3].on = false;
        ui.device_lights = Some(patterns);
        ui.read_problems();
        assert!(!mouse(&ui), "switched off: no problem");
        drop(ui);
        assert_eq!(*calls.lock().unwrap(), ["logirgb profiles -d g502"]);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 191: logirgb takes about half a second a call on the G502, so it runs on
    /// the worker's thread: with a slow fake logirgb the screen's status pass still returns at
    /// once, a want that came and went while a change was pending is dropped (only the
    /// latest is sent), and quitting with a change pending still puts the stored lighting back.
    #[test]
    fn g502_logo_never_holds_up_the_screen_and_sends_only_the_latest() {
        use crate::status::Rgb;
        use std::sync::{Arc, Mutex};
        let dir =
            std::env::temp_dir().join(format!("vibeconsole-g502-slow-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let calls = Arc::new(Mutex::new(Vec::<String>::new()));
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        ui.mouse = Some(crate::keyboard::MouseWorker::start(fake_logirgb(
            &calls,
            Duration::from_millis(300),
        )));
        let mut patterns = crate::status::DevicePatterns::default();
        patterns.rgb_devices[3].on = true;
        let mut own = patterns.rgb_shared;
        own.states = [
            Rgb::Static([0, 0, 1]), // needs-decision
            Rgb::Static([0, 0, 2]), // needs-input
            Rgb::Static([0, 0, 3]), // thinking
            Rgb::Static([0, 0, 4]), // finished
        ];
        patterns.rgb_devices[3].own = Some(own);
        ui.device_lights = Some(patterns);
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.agent_states = vec![("claude".into(), "claude".into(), "needs-input")];
        let pass = |ui: &mut Terminal| {
            let at = Instant::now();
            ui.show_rgb();
            at.elapsed()
        };
        assert!(pass(&mut ui) < Duration::from_millis(50));
        until(|| calls.lock().unwrap().len() == 1); // the open; the set now takes 300 ms
        for state in ["thinking", "finished"] {
            ui.agent_states[0].2 = state;
            assert!(pass(&mut ui) < Duration::from_millis(50), "{state}");
        }
        until(|| calls.lock().unwrap().len() == 3);
        assert_eq!(
            *calls.lock().unwrap(),
            [
                "logirgb profiles -d g502",
                "logirgb set -d g502 -z 1 static --color #000002 --preview",
                "logirgb set -d g502 -z 1 static --color #000004 --preview",
            ],
            "thinking came and went while a change was pending: never sent"
        );
        ui.agent_states[0].2 = "needs-decision";
        ui.show_rgb();
        drop(ui); // quit while that change is pending
        let calls = calls.lock().unwrap();
        assert_eq!(
            calls[calls.len() - 3..],
            [
                "logirgb profiles -d g502",
                "logirgb list",
                "logirgb set -d g502 -z 1 static --color #8000ff --preview",
            ],
            "{calls:?}"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 199: Status light patterns: a shared state picks its effect from what
    /// every light shows, then its colour; Hex code refuses `#12345g` with the reason and
    /// takes `#123456` (ticket 207); Per device gives the keyboard its own effects (from
    /// the shared ones), where reactive and its speed are offered.
    #[test]
    fn rgb_rows_pick_effect_settings_then_colour_and_a_per_device_override() {
        use crate::status::Rgb;
        use Key::*;
        let dir = std::env::temp_dir().join(format!("vibeconsole-rgb-menu-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let typed = |text: &str| {
            let mut keys = vec![Backspace; 7];
            keys.extend(text.bytes().map(Character));
            keys.push(Enter);
            keys
        };
        let mut keys = vec![Down; 20];
        keys.push(Enter); // RGB, all lights · Needs input: static #ff8000
        keys.extend([Down, Enter]); // breath: one colour
        keys.extend(vec![Down; 6]);
        keys.push(Enter); // Hex code (#rrggbb)…
        keys.extend(typed("#12345g"));
        keys.extend(typed("#123456"));
        keys.extend(vec![Down; 29]); // past the four brightness rows (ticket 209)
        keys.push(Enter); // Keyboard RGB · Per device: follows all lights -> its own
        keys.extend(vec![Down; 31]);
        keys.push(Enter); // Keyboard RGB own · Needs input
        keys.extend([Down, Down, Down, Enter]); // reactive
        keys.extend([Down, Down, Down, Down, Enter]); // 4, long
        keys.extend([Up, Enter]); // white
        keys.push(Escape);
        let mut ui = Script {
            keys: keys.into(),
            ..Default::default()
        };
        light_patterns_menu(&mut ui, &path).unwrap();
        assert!(ui.keys.is_empty(), "keys left: {:?}", ui.keys);
        let screen = |text: &str| {
            ui.screens
                .iter()
                .find(|s| s.contains(text))
                .unwrap_or_else(|| panic!("no screen with {text}"))
                .clone()
        };
        let shared = screen(
            "RGB, all lights · Needs input (only effects every light that is on shows): effect",
        );
        assert!(
            !shared.contains("wave") && !shared.contains("reactive"),
            "{shared}"
        );
        screen("#12345g isn't a colour: #rrggbb takes six hex digits");
        let own = screen("Keyboard RGB own · Needs input: effect");
        assert!(own.contains("reactive: lights on each key press"), "{own}");
        screen("Keyboard RGB · Per device: its own effects (below)");
        let lights = mappings::load_config(&path).unwrap().device_lights;
        let custom = Rgb::Breath([18, 52, 86], Default::default());
        assert_eq!(lights.rgb_shared.states[1], custom);
        let keyboard = lights.rgb_devices[0].own.unwrap();
        assert_eq!(keyboard.states[1], Rgb::Reactive([255, 255, 255], Some(4)));
        assert_eq!(
            keyboard.states[0], lights.rgb_shared.states[0],
            "started from the shared set"
        );
        assert!(lights.rgb_devices[1..].iter().all(|d| d.own.is_none()));
        std::fs::remove_dir_all(dir).unwrap();
    }

