    /// v7.7 ticket 212: Keep effects in step on: thinking's breath reaches the keyboard,
    /// speakers and mousepad as the same static frame at the same tick, from one clock
    /// counted from when thinking began, repeating every `period=`; the G502 gets that period;
    /// pause stops the frames and the resting effect goes back on every device.
    /// v7.7 ticket 271: a resting effect changed while output is paused (or a menu holds it)
    /// is written to every Razer device at once, once, without a Resume.
    #[test]
    fn a_changed_resting_effect_shows_at_once_while_paused() {
        use crate::keyboard::RgbKeyboards;
        use crate::status::Rgb;
        let dir = std::env::temp_dir().join(format!("vibeconsole-rgb-rest-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let effects = ["none", "spectrum", "wave", "static", "breath", "reactive"];
        let device = |path: PathBuf, name: &str| {
            std::fs::create_dir_all(&path).unwrap();
            std::fs::write(path.join("device_type"), format!("{name}\n")).unwrap();
            std::fs::write(path.join("matrix_brightness"), "200\n").unwrap();
            for f in effects {
                std::fs::write(path.join(format!("matrix_effect_{f}")), "").unwrap();
            }
            path
        };
        let kbd = device(
            dir.join("razerkbd/0003:1532:021A.0001"),
            "Razer BlackWidow X Chroma",
        );
        let nommo = device(dir.join("acc/0003:1532:0517.000A"), "Razer Nommo Chroma");
        let firefly = device(dir.join("acc/0003:1532:0C04.0001"), "Razer Firefly V2");
        let all = [&kbd, &nommo, &firefly];
        let breaths = || all.map(|d| std::fs::read(d.join("matrix_effect_breath")).unwrap());
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        ui.rgb = Some(RgbKeyboards::open(&dir.join("razerkbd"), Rgb::SPECTRUM).unwrap());
        let acc = dir.join("acc");
        ui.accessories[0] = Some(
            RgbKeyboards::open_accessory(&acc, Rgb::SPECTRUM, "Speakers RGB", "Nommo").unwrap(),
        );
        ui.accessories[1] = Some(
            RgbKeyboards::open_accessory(&acc, Rgb::SPECTRUM, "Mousepad RGB", "Firefly").unwrap(),
        );
        let mut patterns = crate::status::DevicePatterns::default();
        for d in &mut patterns.rgb_devices[..3] {
            d.on = true;
        }
        patterns.rgb_in_step = false;
        ui.device_lights = Some(patterns.clone());
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        ui.show_rgb_at(Instant::now()); // running, idle: spectrum rests on all three
        ui.pause_by("key").unwrap();
        assert!(ui.suspended);
        assert_eq!(breaths(), [Vec::<u8>::new(), Vec::new(), Vec::new()]);
        // Changed in Status light patterns while paused: Breath · Blue.
        patterns.rgb_shared.rest = Rgb::Breath([0, 0, 255], Default::default());
        ui.device_lights = Some(patterns);
        ui.show_rgb_at(Instant::now());
        let blue = vec![0u8, 0, 255];
        assert_eq!(
            breaths(),
            [blue.clone(), blue.clone(), blue.clone()],
            "written at once"
        );
        for d in all {
            std::fs::write(d.join("matrix_effect_breath"), "").unwrap();
        }
        ui.show_rgb_at(Instant::now());
        assert_eq!(
            breaths(),
            [Vec::<u8>::new(), Vec::new(), Vec::new()],
            "once, not every tick"
        );
        drop(ui);
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn rgb_in_step_writes_one_frame_to_every_device_and_stops_on_pause() {
        use crate::status::{Rgb, Timing};
        use std::sync::{Arc, Mutex};
        let dir = std::env::temp_dir().join(format!("vibeconsole-rgb-step-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let effects = ["none", "spectrum", "wave", "static", "breath", "reactive"];
        let device = |path: PathBuf, name: &str| {
            std::fs::create_dir_all(&path).unwrap();
            std::fs::write(path.join("device_type"), format!("{name}\n")).unwrap();
            std::fs::write(path.join("matrix_brightness"), "200\n").unwrap();
            for f in effects {
                std::fs::write(path.join(format!("matrix_effect_{f}")), "").unwrap();
            }
            path
        };
        let kbd = device(
            dir.join("razerkbd/0003:1532:021A.0001"),
            "Razer BlackWidow X Chroma",
        );
        let nommo = device(dir.join("acc/0003:1532:0517.000A"), "Razer Nommo Chroma");
        let firefly = device(dir.join("acc/0003:1532:0C04.0001"), "Razer Firefly V2");
        let all = [&kbd, &nommo, &firefly];
        let frames = || all.map(|d| std::fs::read(d.join("matrix_effect_static")).unwrap());
        let three = |c: [u8; 3]| [c.to_vec(), c.to_vec(), c.to_vec()];
        let calls = Arc::new(Mutex::new(Vec::<String>::new()));
        let run = fake_logirgb(&calls, Duration::ZERO);
        let path = dir.join("mappings.tsv");
        mappings::save(&path, &[]).unwrap();
        let mut ui = Terminal::open_mode(&path, true).unwrap();
        use crate::keyboard::RgbKeyboards;
        ui.rgb = Some(RgbKeyboards::open(&dir.join("razerkbd"), Rgb::SPECTRUM).unwrap());
        let acc = dir.join("acc");
        ui.accessories[0] = Some(
            RgbKeyboards::open_accessory(&acc, Rgb::SPECTRUM, "Speakers RGB", "Nommo").unwrap(),
        );
        ui.accessories[1] = Some(
            RgbKeyboards::open_accessory(&acc, Rgb::SPECTRUM, "Mousepad RGB", "Firefly").unwrap(),
        );
        ui.mouse = Some(crate::keyboard::MouseWorker::start(run));
        let mut patterns = crate::status::DevicePatterns::default();
        for d in &mut patterns.rgb_devices {
            d.on = true;
        }
        assert!(patterns.rgb_in_step, "on by default");
        let thinking = Rgb::Breath(
            [0, 0, 255],
            Timing {
                period: Some(2000),
                ..Default::default()
            },
        );
        patterns.rgb_shared.states[2] = thinking;
        ui.device_lights = Some(patterns);
        ui.agent_states = vec![("claude".into(), "claude".into(), "thinking")];
        ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
        ui.suspended = false;
        let start = Instant::now();
        let at = |ms: u64| start + Duration::from_millis(ms);
        ui.show_rgb_at(at(0));
        assert_eq!(
            frames(),
            three([0, 0, 0]),
            "the cycle starts dark, together"
        );
        for d in all {
            let breath = std::fs::read(d.join("matrix_effect_breath")).unwrap();
            assert!(breath.is_empty(), "no firmware breath: {d:?}");
        }
        // v7.7 ticket 239: the cycle counts from when the mouse's set returned.
        until(|| ui.mouse.as_ref().unwrap().shown_since().is_some());
        let mouse = ui.mouse.as_ref().unwrap().shown_since().unwrap();
        let at = |ms: u64| mouse + Duration::from_millis(ms);
        ui.show_rgb_at(at(500));
        let quarter = crate::status::rgb_frame(thinking, 500, 4000).unwrap();
        assert_eq!(quarter, Rgb::Static([0, 0, 127]));
        assert_eq!(
            frames(),
            three([0, 0, 127]),
            "the same frame at the same tick"
        );
        ui.show_rgb_at(at(1000));
        assert_eq!(frames(), three([0, 0, 255]), "the peak at half the period");
        ui.show_rgb_at(at(2500));
        assert_eq!(frames(), three([0, 0, 127]), "period=2000: it repeats");
        until(|| {
            (calls.lock().unwrap().iter()).any(|c| {
                c == "logirgb set -d g502 -z 1 breathe --color #0000ff --period 2000 --preview"
            })
        });
        for d in all {
            std::fs::write(d.join("matrix_effect_static"), "").unwrap();
        }
        ui.suspend().unwrap();
        for d in all {
            let rest = std::fs::read(d.join("matrix_effect_spectrum")).unwrap();
            assert_eq!(rest, b"1", "paused: the resting effect on {d:?}");
        }
        ui.show_rgb_at(at(3000));
        assert!(frames().iter().all(Vec::is_empty), "paused: no more frames");
        drop(ui);
        std::fs::remove_dir_all(dir).unwrap();
    }

    /// v7.7 ticket 239: with the G502 in step, the Razer cycle holds its first frame until
    /// logirgb's set returns (a 300 ms fake), then counts from that moment; a mouse that
    /// doesn't answer within 1 s doesn't hold it longer.
    #[test]
    fn the_in_step_cycle_starts_when_the_mouse_confirms() {
        use crate::status::{Rgb, Timing};
        use std::sync::{Arc, Mutex};
        for delay in [300, 1400] {
            let dir = std::env::temp_dir().join(format!(
                "vibeconsole-step-mouse-{delay}-{}",
                std::process::id()
            ));
            let _ = std::fs::remove_dir_all(&dir);
            let kbd = dir.join("razerkbd/0003:1532:021A.0001");
            std::fs::create_dir_all(&kbd).unwrap();
            std::fs::write(kbd.join("matrix_brightness"), "200\n").unwrap();
            for f in ["none", "spectrum", "wave", "static", "breath", "reactive"] {
                std::fs::write(kbd.join(format!("matrix_effect_{f}")), "").unwrap();
            }
            let frame = || std::fs::read(kbd.join("matrix_effect_static")).unwrap();
            let path = dir.join("mappings.tsv");
            mappings::save(&path, &[]).unwrap();
            let calls = Arc::new(Mutex::new(Vec::<String>::new()));
            let mut ui = Terminal::open_mode(&path, true).unwrap();
            ui.rgb = Some(
                crate::keyboard::RgbKeyboards::open(&dir.join("razerkbd"), Rgb::SPECTRUM).unwrap(),
            );
            let fake = fake_logirgb(&calls, Duration::from_millis(delay));
            ui.mouse = Some(crate::keyboard::MouseWorker::start(fake));
            let mut patterns = crate::status::DevicePatterns::default();
            patterns.keyboard_on = false; // no real lock-key LED in a test
            for (j, device) in patterns.rgb_devices.iter_mut().enumerate() {
                device.on = j == 0 || j == 3;
                device.own = None;
            }
            let period = Timing {
                period: Some(2000),
                ..Default::default()
            };
            let thinking = Rgb::Breath([0, 0, 255], period);
            patterns.rgb_shared.states[2] = thinking;
            ui.device_lights = Some(patterns);
            ui.agent_states = vec![("claude".into(), "claude".into(), "thinking")];
            ui.output = Some(crate::keyboard::Output::recording(&[]).unwrap());
            ui.suspended = false;
            let start = Instant::now();
            ui.show_rgb_at(start);
            ui.show_rgb_at(start + Duration::from_millis(200)); // before the mouse answers
            assert_eq!(frame(), [0, 0, 0], "{delay} ms: the first frame holds");
            if delay == 300 {
                until(|| ui.mouse.as_ref().unwrap().shown_since().is_some());
                let mouse = ui.mouse.as_ref().unwrap().shown_since().unwrap();
                assert!(mouse >= start + Duration::from_millis(300));
                ui.show_rgb_at(mouse + Duration::from_millis(1000));
                assert_eq!(
                    frame(),
                    [0, 0, 255],
                    "counted from the mouse: the peak at 1000"
                );
            } else {
                ui.show_rgb_at(start + Duration::from_millis(1100)); // no answer within 1 s
                let expected = crate::status::rgb_frame(thinking, 1100, 4000).unwrap();
                let Rgb::Static(bytes) = expected else {
                    unreachable!()
                };
                assert_eq!(frame(), bytes, "started anyway, counted from the state");
            }
            drop(ui);
            std::fs::remove_dir_all(dir).unwrap();
        }
    }

